/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210312-3","meetingId":"r03-c-budget","date":"2021年3月12日","dateIso":"2021-03-12","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を194件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"小芝委員","kind":"質問・要望","question":"初めに、給食運営費に関連しまして、和牛の給食が出されたことについてお伺いいたします。今日に至るまで、和牛の給食が提供された学校の数、また献立の中にはどのようなものが多かったのかを教えてほしいと求めました。","respondent":"篠田学務課長","answer":"こちらは品川区内の小・中・義務教育学校、全ての学校で実施されてあります。牛丼ですとか、学校によってはステーキみたいな形で出されたところもあって、それぞれ子どもたちが大変喜んだと聞いているところです。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"この取組みを通じまして、子どもたちの反応だとか教員の反応はどうであったか、教えていただけますか尋ねました。","respondent":"篠田学務課長","answer":"牛肉は高いですから、なかなかメニューに入れられないということですので、子どもたちには本当に好評だったです。教員からもそういった形でなかなかメニューに出ない分、子どもたちの笑顔を見られてよかったというような声も聞いているところです。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問","question":"保護者にも伝わりますし、またこれが生産者に届けば、生産者もきっと喜ぶと思います。そういうものも一つの食育ではないかと考えますが、いかがお考えか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"委員のご提案もとてもよい案だと考えております。はそこの料理を掲示したりして、様々な食育活動の中の一つ大きな好事例として、こちらで理解していきたいと思います。","id":"exchange-003"},{"speaker":"小芝委員","kind":"質問","question":"先日農林水産省のほうに問合せましたところ、販路多様化緊急対策事業に名前が変わりまして、昨年１０月に補正予算で計上されました。この事業自体は３月の公募を最後に一旦事業が終わるそうですが、子どもたちに教えてもらいたいと思いますが、お考えをお願いします。","respondent":"篠田学務課長","answer":"先ほども少し申し上げたのですけれども、給食で牛肉というのはコストの点からなかなか難しい状況がありますので、そういった形で何らかの補助的な事業がまた実施されるということであれば、私どもも前向きに考えてまいりたいと捉えているところです。","id":"exchange-004"},{"speaker":"小芝委員","kind":"確認","question":"横田めぐみさん拉致事件を題材にしたアニメ「めぐみ」の小・中学校での上映状況を確認しましたところ、今年度の実施状況はいかがでしたでしょうか。具体的にどの学年でこのアニメを視聴したのかを教えていただけますか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"調べたときには既に半数の学校が取組んでおりまして、学年は主に小学生では６年生、中学生では９年生の実施が多くなってあります。全校朝会で取上げた学校もあります。","id":"exchange-005"},{"speaker":"小芝委員","kind":"質問・要望","question":"このアニメ視聴後に、例えば児童・生徒にこの感想文といったものを課題として出させている学校があるかどうか。児童・生徒がこのアニメを見た後のそういった気づきを、現場の先生方はどのように吸収しているのか教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"恐らく低学年だと思いますけれども、めぐみさんが連れていかれるときに「お母さん、お母さん」と叫んでいたのはかわいそうだと思った。めぐみさんに帰ってきてほしいなどの感想を聞いております。","id":"exchange-006"},{"speaker":"小芝委員","kind":"質問・要望","question":"その後、２００２年に拉致被害者５名が帰国されました。これから自分たちが取組むべきことなどを正確に教えていくべきであると考え、拉致問題について、説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"東京都は毎年全教員に人権教育プログラムを配布しています。そこに拉致問題が掲載されてありますので、いつでも研修の資料として活用できることとなっております。","id":"exchange-007"},{"speaker":"小芝委員","kind":"質問・要望","question":"２０１７年から政府の拉致問題対策本部が、中・高校生を対象にしました作文コンクールを実施しております。品川区のほうでこの作文コンクールの話というのは、人権教育の中で生徒に周知されているのかどうか、取組状況を教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"パンフレット、チラシ等が配布されることになっておりますので、学校には配布されていると思います。","id":"exchange-008"},{"speaker":"小芝委員","kind":"質問","question":"９年生にこのアニメの視聴等、教育をしているという話を伺いまして、お考えはいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"委員も十分ご存じのように、人権教育には様々ある中での拉致問題です。当然全ての人権課題、男女ですとか高齢者とか障害者とか外国人とか様々ある中で、総合的に人権教育は推進してまいりたいと思います。","id":"exchange-009"},{"speaker":"小芝委員","kind":"提案","question":"これは私からの提案ですが、「めぐみへの誓い」という映画ですけれども、クラウドファンディングで製作費を賄った映画があります。最後に、今後の教育に向けて積極的なお考えをお伺いしたいと思いますとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"ただいまの情報も含めて、様々な人権課題について誠心誠意、学校でも区でも一番の目標ですので、推進してまいりたいと考えております。","id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"１教科分のこの学習者用デジタル教科書の提供としておりますので、それに手を挙げたものを、まず最初に１点確認します。申請をすれば、これは必ず参加できるものかどうかというところを確認したいと思います。","respondent":"矢部教育総合支援センター長","answer":"デジタル教科書の申請のお尋ねです。できるだけ全校に１教科だけでも、１学年だけでも入れるように、働きかけております。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"結構な数でありますので、または一部の学校だけがオーケーとなってしまうことは非常に残念だと考えています。東京都に何か条件というか要望をしていただいて、では５年生だけは全員お願いしたいとか、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"東京都のほうでは約半数という条件でございましたが、本区としては何とかということで、できるだけ多くを要望しております。漏れる学校がないように、本区としても力を入れて、全校に１教科、１学年でも入れるように努めてまいります。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"例えば学校のトイレに生理用品を置き、無料で使えるようにするなども考えられるが、知事の考えと思いを伺うということで質問をいたしました。そのような状況から、この生理の影響がないか、どう捉えているのかということをお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"先ほどの数字のこともありますが、大人の方たちと同じように、やはり生理のある小さなお子さんについても、一定の不安はあるだろうと想定しています。２点目にも関わりますけれども、基本的には養護教諭、そして女性の教員に相談できる心のつながりはできていると認識しておりま…","id":"exchange-013"},{"speaker":"新妻委員","kind":"意見","question":"今日はちょっと生理の貧困というところで取り上げてまいりますが、そこで学校の保健室に生理用品のストックがあると思います。不足したらまた教育委員会からお渡しするのか、そこら辺のストックの様子、状況をお知らせくださいとの意見を述べました。","respondent":"篠田学務課長","answer":"学校に常備しております生理用品につきましては、教育委員会のほうから学校に配当している予算で、必要に応じて学校のほうで用意してもらっており、不足すればその分を補充しているというような状況です。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"中にはなかなか言いにくいとか、たくさんもらいにくいとかいう生徒もいると思います。学校のトイレにナプキンを置いておくということをぜひご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"区教育委員会として何かできることを、衛生上・管理上の課題を考えながら検討してまいりたいと思います。","id":"exchange-015"},{"speaker":"新妻委員","kind":"提案","question":"今回の予算特別委員会副委員長のつる副委員長が２０１２年の第２回定例会の一般質問で、電子図書館の導入を提案させていただいておりました。そして、どのような方をターゲットとして、利用されると想定されているのか伺いますとの意見を述べました。","respondent":"横山品川図書館長","answer":"ただ、再三ご説明させていただいたように、図書館で貸出しできるものについては著作権の制限が非常にあります。これについてはまず使っていただいて、その方たちに使っていただけるように丁寧に説明し、導入を進めていきたいと思っているところです。","id":"exchange-016"},{"speaker":"新妻委員","kind":"提案","question":"機器が苦手な方もいらっしゃると思うのですが、図書館に来る方はいろいろな世代の方がいらっしゃいます。この電子機器の使い方広場、使い方の教室などを行っていただきたいと提案いたしますが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"委員からご提案いただいた点については、非常にいいご提案だと思うので採用させていただきたいと思います。お知らせをする機会を設けているところですので、同じように丁寧な説明とともに、マニュアルやホームページでの解説を進めていきたいと思います。","id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"高齢者の支援策の中でも、スマホ、タブレットの教室を次年度開催するという予定になっております。図書館でも、ぜひ推進してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"質問に先立ちまして、たしか１,５００人ぐらいとお聞きしましたけれども、新型コロナウイルス感染者数がほぼ０名ということをお聞きいたしました。私の娘もそうですけれども、子どもたちに苦しくないのかとお聞きしましたら、苦しいけれども学校のルールですからというお話でした。","respondent":"矢部教育総合支援センター長","answer":"委員ご指摘のとおり、２月１９日に新型コロナウイルス感染症に対応した持続的な学校運営のためのガイドラインの改訂についてという文書が。そういう配慮で考えていたのですが、もし湿疹等がありましたら学校のほうにご相談いただいて、個別対応させていただきたいと考えています。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問・要望","question":"正しいマスクのつけ方、外した子どもがいたときにもいじめられないような形で、また子どもたちの健康につながるよう要望して、次の質問に移ります。一般質問でもお聞きしましたが、学校配布物の紙とデータベースとの検討、もし進んでいることがありましたら説明を求めました。","respondent":"工藤指導課長","answer":"ご指摘にありますように、欠席や遅刻の連絡の電子化などにつきましては各学校にマニュアルを配布して、具体的な検討を各学校が始めているところです。もう既に一斉メールに添付して保護者に送付するということを行っている学校もありますので、引き続き検討し…","id":"exchange-020"},{"speaker":"松澤委員","kind":"意見","question":"しかし、このタブレットですけれども、分からないことがあると思います。電話対応が大変なのではないかと思いますけれども、そこら辺で対応を取られていることは何かありますかとの意見を述べました。","respondent":"篠田学務課長","answer":"ヘルプデスクを設置いたしまして、中に入っているアプリの運用等も含めて対応していますけれども、教育委員会が窓口となっています。使い方でやはり気になる、その辺は、適宜対応できるものについては順次対応していくというような形で取組んでいるものです。","id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"まだ１日二、三件程度ということでしたら、切迫に広げるとかそういうことはないかと考えています。児童・生徒全員と、あと先生方と、またほかで先生以外にどなたがタブレットを持っているのかというのが分かれば説明を求めました。","respondent":"篠田学務課長","answer":"全ての児童・生徒はもちろん、指導するための教員、こちらのほうには全てお配りをしているです。そういった指導に関わる方にはある程度行き渡るような形でとは考えているのですが、その中で必要に応じて使っていただくような形で考えております。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問","question":"スクールカウンセラーが行う新たな心の支援の手段として、オンラインカウンセリングの導入は身近な有効手段かと思います。それを踏まえて、オンラインカウンセリングに対するご見解をお願いします。","respondent":"矢部教育総合支援センター長","answer":"オンラインカウンセリングについてです。今後、チャイルドラインとシグナルカードをＱＲコードで読み込んで対応していきたいと考えています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"３７１ページ、３５３ページ、子どもの権利条約について伺います。伺いますけれども、どう学校運営に活かしていくのでしょうか、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"顔色を見たり、これまでも繰り返していますスクールカウンセラーで対応したりとか、アンケートを学期で一回取っているというようなことで対応して。私もそうですが、不登校のお子さんも含めて、そういった事情も我々は分かって指導しているつもりです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"少人数学級について伺っていきたいのですけれども、１学級３０人以下など少人数学級を明記する答申を出すように要望しています。歓迎するのですかと聞いても、自治体として歓迎するかどうかという思いを簡単に表明すべきではないと、それすら表明しません。","respondent":"有馬庶務課長","answer":"こういうふうな考えをお持ちの教育長もいますということで、一つの紹介として、３０人学級の推薦ということが書かれていたというものです。全体といたしましては、昨年の２月に全国都市教育長協議会がまとめておりますけれども…","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"教育長として３０人学級を明記すべきだと要望したということですが、それはあくまで参加した教育長個人の発言だということで、私は受けとめました。改めて伺いたいと思います。","respondent":"篠田学務課長","answer":"委員からご指摘のあったとおり、コロナ禍ということで、学校におきましても様々な工夫をして対応しているというものです。段階的に３５人学級を実現していくですので、私どももそちらの考え方にのっとり対応していきたいと考えているところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、区の教育委員会として、教育環境の整備が仕事、所管だと思うのですけれども、これは教育委員会としてどうかと聞いたのです。中学校でも実現すべきだし、自ら汗を流すべきだと思うのですけれども、改めて伺いたいと思います。","respondent":"篠田学務課長","answer":"３５人学級につきましては、再三申し上げましたとおり、国のほうがそれに向けて動き出しをしているですので、そちらのほうをきちんと踏まえながら対応してまいりたいと考えているところです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、この間、世間でもずっと議論になっていました。あるいはクラスの規模などについて、子ども自身に意見を求めたり声を聞いたことがあったのでしょうか、伺いたいと思います。","respondent":"篠田学務課長","answer":"学級編制につきましては、あくまで教育委員会の権限で各学校で実施していくということになりますから、子どもの意見を聞いて対応するべきものではないと認識しているものです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"クラスの人数はどうですか、教室が窮屈ではないですか、席が近いと感染が不安ではないですかなどと耳を傾けるべきではないですか。伺います。","respondent":"篠田学務課長","answer":"繰り返しになってしまうのですけれども、あくまで学級編制というのは制度にのっとって行うものです。基本的な部分でクラスの人数を何人にするかといったものに関しては、あくまでも制度の枠組みの中で対応すべきものと考えているところです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"続いて子どもの権利条約についても伺っていくのですが、この子どもの権利条約の観点から品川区の競争教育を見直すべきと質問いたしました。品川の学校教育でそういう場面はあるのでしょうか、伺います。","respondent":"矢部教育総合支援センター長","answer":"子どもの権利条約につきましては、社会科の教科書でもありますし、市民科のほうでも指導している場面があります。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し具体的にお伺いしたいと思います。あるいは意見表明権など、この子どもの権利条約そのものをしっかりと扱うことを改めて私も求めたいと思うのですが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"様々な場面で憲法や人権を学ぶ機会に、その資料を提示することはままあると考えております。その話題になるということは十分ありますが、そのものだけをずっと時間をかけてやるという時間は取っていないと認識しております。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は、子どもの権利条約から品川の教育を点検し、見直す必要があると思うし、やっていただきたいと改めて求めたいと思います。この勧告について、品川区教委は思い当たるところがないのか、伺いたいと思います。","respondent":"工藤指導課長","answer":"品川区の教育におきましては、一貫教育を推進する中で児童・生徒の資質・能力を最大限伸ばし、未来を生きる力を育む教育を行っております。特に市民科学習におきましては、人間性の形成の部分で大きく寄与していますので…","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"思い当たる節はないのでしょうか。日本の今までの教育を引っ張ってきたと自負しておられましたけれども、どうなのでしょうか、伺いたいと思います。","respondent":"工藤指導課長","answer":"品川区で進めております一貫教育につきましては、児童・生徒一人ひとりの個に応じた教育を大事にしながら行っているものです。それぞれの児童・生徒が未来を生きる力をしっかりと育む、そのための教育をするものです。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"直接お答えにならないのですけれども、答えられないということなのでしょうか。これを制度、教育方針などを作っていく上で必ず位置づけて改善していくということを私は求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"筒井委員","kind":"提案","question":"３６５ページ、３５２ページ、ＳＴＥＡＭライブラリーについてお伺いいたします。具体的にどうやって音楽を聴いたり本を読んだりするのか、どのようなページになるのか、そのあたりを説明を求めました。","respondent":"横山品川図書館長","answer":"取っていただいた後は、もう自分のパスワードで入っていただいて、パソコンやスマートフォンでご利用いただけるようになります。２週間の間はデータベースをご利用いただけますので、その間においては電子書籍と同じように、ご自分の機器からアクセスできるような形になります。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"当然やはり幅広い層に向けて提供されるものですから、マニュアルというのも広く周知していかなくてはいけないと思っているのですけれども、今回のこの電子図書館導入についての周知はどのようにされていくのか尋ねました。","respondent":"横山品川図書館長","answer":"やはり区の政策の周知の第一で、広報紙を利用します。ツイッター等で周知するとともに、チラシやポスターを利用しますとともに、館内でもＰＲをさせていただいて進めさせていただきたいと考えています。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"書籍除菌機についてお伺いいたしますけれども、従来からの衛生面の配慮、これも非常によい事業かなと考えております。そして、それぞれの単価というのも、分かれば説明を求めました。","respondent":"横山品川図書館長","answer":"従来使っております４冊用のＬＩＶＡという機種と、２冊、３冊用のＣＯＣＯＣＨＩという機器を想定して配置を考えているところです。単価につきましては、機器購入費で８７万円を今想定させていただいているところです。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"ＬＩＶＡというのは韓国の企業のものなのですが、ＬＩＶＡという韓国メーカーを選定した理由は何でしょうか。何か日本製と比べて特筆すべき点というのはあるのか尋ねました。","respondent":"横山品川図書館長","answer":"従来の設置につきましては、指定管理者からの推薦を受けまして、そういう意味では各種を比べてという形を取っておりません。今のところあまり他社で製造しているというような情報が入っておりませんので、これから探していきたいと考えています。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"続いて、ＳＴＥＡＭライブラリーについてお伺いいたします。そうしたことから、このＳＴＥＡＭライブラリーについて、品川区の教育委員会へ連絡とか通知というのは事前にあったのか尋ねました。","respondent":"工藤指導課長","answer":"特に文部科学省から、あるいは経済産業省のほうから、通知が私どもの手に届いているということはございません。ただ、そういった活用につきましては教材の一つにもなりますので、学校のほうで活用が図れる部分については活用できるものと認識しております。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"１人１台タブレットの構想と非常に相性がよいものだと思うのですが、何かこの教科で使っていこうとか、現時点で具体的な構想というのはあるのか尋ねました。","respondent":"工藤指導課長","answer":"ＳＴＥＡＭライブラリーにつきましては、児童・生徒に配布したタブレットでも登録なしで動画等を視聴できるようになってあります。教材の一つとして利用を図ることができると現在考えているところですので、また児童・生徒の意見を聞きながら今後研究してまいりたいと考えていま…","id":"exchange-040"},{"speaker":"吉田委員","kind":"確認","question":"３７３ページの保健運営費にあたると思います給食着の問題、性教育の問題、新型コロナウイルス感染症対策、順不同で行けるところまで伺います。見解を伺います。","respondent":"有馬庶務課長","answer":"最近は、区といたしましても学校の用務等を通じて清掃の状況を確認し、また排水溝等を常時点検するようにということを進めているところです。一方、ある学校では表層改修とか、土の改修をそのまま継続するという学校もありますので…","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"同じ区の、しかも教育機関がこの問題についてやはり推進するというのは、ちょっとどうなのかなと思います。やはり別の表層、そのまま土のグラウンドにするという条件が許せばそちらの方向を検討すべきだと思いますが、改めて伺います。","respondent":"有馬庶務課長","answer":"ちぎれにくい、あるいはヒートアイランド対策で表層の温度が抑えられるということで、子どもたちも安全だというような品質のものも出ております。そういったことも出てくると思いますので、今後のそういった製品の改良の動向も注視してまいりたいと思います。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"この（４）全体がそもそも教員の役割なのでしょうか。ちょっと先生の役割としたら負担が大き過ぎるのではないかと思いますが、見解を伺います。","respondent":"有馬庶務課長","answer":"例えば消毒等に関して衛生管理をしていこうということでございまして、必ずしもこれを教員がやるというふうにしているものではありません。手すり、衛生環境を保つためには、ここはしっかりと消毒していきましょうということでガイドラインを示しているものです。","id":"exchange-043"},{"speaker":"吉田委員","kind":"質問","question":"では誰がやるというのは、それぞれ学校の中でルールがきちんと決められていると判断してよろしいか尋ねました。","respondent":"有馬庶務課長","answer":"そうです。やはり低学年は担任の先生が児童の机を拭いているというような状況もありますので、一律にどこがどうと全て決まっているわけではございません。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、衛生費のときにも質問したのですけれども、水道の蛇口、レバーのことがちょっと気になります。手を水で流すときにそのレバーの石けんも一緒に流すよう指導するとベストなのではないかと思うのですけれども、その点について見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"手洗い場の管理についてだと存じます。手洗い場における新型コロナウイルス感染症対策の徹底ということで保健所とも連携を取りながら、蛇口を使い終わったら、通知をしています。","id":"exchange-045"},{"speaker":"吉田委員","kind":"確認","question":"内容そのものや表現も含めて、例えば区内で言えば保健センターのアドバイスなど、連携とか相談はやっているのでしょうか。ガイドラインへのアドバイスとか、その後のルールの徹底などを協議してはいかがかと思いますが、見解を伺います。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"２点目の密を防ぐための時間設定は、校庭の広さもありますから、それに応じて交錯しないようにという工夫だと考えております。専門家の意見はぜひ取り入れたいと考えていますけれども、基本的には国、都の通知です。 ただ、都の教育委員会にいらっしゃる方なので、その全ての細かいところまでを見ていただくのは難しいだろうと考えています。様々な形で保健関係の指導等を行っていけると考えておりますので、なかなか学校保健技師を使ってというのは…","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"これは学校ごとの判断なのかを伺います。感染症対策として給食着の使い回しはしなくてよいと校長会などで事例として報告して、全体化してほしいのですけれども、いかがか尋ねました。","respondent":"篠田学務課長","answer":"割ぽう着、いわゆる給食着に関するお尋ねと受けとめてあります。各学校に対して柔軟に対応するように話していますので、逆に改めて校長会でこれを徹底するというような見解は今のところ持ち合わせていないものです。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひその辺についても理解をしていっていただきたいのと、それから、これは実は先ほど質問したマイクロプラスチックの問題なのです。これも学校単体の判断なのか、品川区としての方向性をこちらのほうに進めるということなのか、見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"標準服につきましては、学校の判断です。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"これもなかなか制服になじめなくて、それからトランスジェンダーの問題などで悩んでいる生徒も多いかと思います。先ほどと同じように、できたらそちらの方向に進めていってほしいと求めましたが、改めてその点について見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"標準服のことですが、人権教育ではこの視点でも制服についてこちらで紹介していますし、そういうことを校長も全て研修を受けて理解しておりますので、委員のご心配は要らないかと思います。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問","question":"心配する必要はないということで、進む方向だと理解します。ぜひその方向に進んでいただくようお願いして、質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"木村委員","kind":"質問","question":"ずばり、この解決策というものはどこにあるのでしょうか。そしていじめられる側ではなく、そのこと自体を傍観している児童・生徒がキーポイントになるのではないかと思っていますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"本人がいじめと認識した場合、本当はよかれと思って働きかけたことも、相手にとってはそれが嫌だったということがままあります。そのような事情も踏まえて、いじめのカウントを１とすると増えていってありますが、お互いの気持ちを尊重し合う教育を進めてあります。","id":"exchange-051"},{"speaker":"木村委員","kind":"質問・要望","question":"教職員の方々も、これは大変なことであろうと思いますけれども、頑張ってほしいと求めました。説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"毎年、学校から児童・生徒の代表が集まりまして、自分の学校のいじめについての取組みを紹介し合う場面があります。話し合いの中で好事例は当然共有できますし、自分たちもやってきたという責任感や自負の弁が聞けて、大変有効だと考えております。","id":"exchange-052"},{"speaker":"木村委員","kind":"質問","question":"次に、３５７ページの下のほうにありますけれども、特色ある教育活動経費の中のしながわドリームジョブからの質問であります。この事業は将来の自分を見つける、やりたいことやなりたい自分を見つける事業だと思いますが、それでよろしいのか尋ねました。","respondent":"工藤指導課長","answer":"しながわドリームジョブについてのお尋ねです。自分の将来について考え、自分の夢を実現させるための具体的な方法を学ぶことをねらいとして行っているものです。","id":"exchange-053"},{"speaker":"木村委員","kind":"質問","question":"私は、要は、夢を持たせることが一番大事なことであろうと思っていますし、また夢とともに成長することも大事だと思っています。周りの大人たちが子どもの成長期にいかにして夢を持たせる環境づくりをできるかどうかが、その点はいかがか尋ねました。","respondent":"工藤指導課長","answer":"このしながわドリームジョブにおきましても地域人材の方を講師としてお招きし、その方々からお話を聞くということを行ってあります。やはり自分の将来、どのような職業に就くのかということに興味を持ち、それが夢につながるものと考えております。","id":"exchange-054"},{"speaker":"木村委員","kind":"質問・要望","question":"我々の頃は中学校からの授業でしたが、本区の生徒は平成１６年頃から行っているとお聞きしました。なぜ１年生からになったのか、このことに対してご説明ください。","respondent":"工藤指導課長","answer":"品川区の英語教育についてのお尋ねです。１年生から９年間の系統的な英語教育を定めて、９年間で英語力、あるいはコミュニケーション能力を育むということで取組んでいるものです。","id":"exchange-055"},{"speaker":"木村委員","kind":"質問","question":"他区では小学校３年生から英語授業が行われているとお聞きしました。例えば成績の面においても、何か他区との比較、そういうことに対してもまたお答えください。","respondent":"工藤指導課長","answer":"１年生からの９年間の英語教育の中では、コミュニケーション能力の成長の様子が非常に見られるところです。国の目標が５０％というものですけれども、本年度の速報値ですが、本区の９年生は８０％を超えているという状況です。","id":"exchange-056"},{"speaker":"木村委員","kind":"質問・要望","question":"本当に何事にも一生懸命頑張る姿をまた見せてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"松本委員","kind":"質問","question":"３６９ページ、３５３ページ、学校での家庭内児童虐待の早期発見について伺います。こちらについて、開催に至った経緯、内容、児童の感想もお聞かせほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"教育総合支援センターの指導主事もお邪魔しました。小学校では５年生と６年生のそれぞれ理科、どのような内容を位置づけていくかとか、試みとしてはよかったと思います。","id":"exchange-058"},{"speaker":"松本委員","kind":"質問・要望","question":"次の質問もまさにそこを広げていっていただきたいというところではあるのですけれども、昨年、人々にゲームプレイを推奨する。分析をしていただいて、実施校を増やしてほしいと求めましたが、区のご所見を伺います。","respondent":"矢部教育総合支援センター長","answer":"ただ一方で、それも比較的子どもたちにとってはゲーム性があって楽しいものになってあります。様々な保護者や企業などと連携して、そういった活動を少しずつ広げていけたらと考えています。","id":"exchange-059"},{"speaker":"松本委員","kind":"質問・要望","question":"次に、学校維持管理費に関連して、学校内の教師によるわいせつ事件防止対策について伺います。昨年、全国学校ハラスメント被害者連絡会は文部科学省に対して、公立学校のトイレと更衣室以外の場所への防犯カメラの設置を要望しました。","respondent":"有馬庶務課長","answer":"防犯カメラの設置数ですけれども、５台を中心に、学校によって数が上下していると。そのような状況です。","id":"exchange-060"},{"speaker":"松本委員","kind":"質問","question":"それは、多分外から来る犯罪者というか、どちらかというと外部向けということで理解してよろしいか尋ねました。","respondent":"有馬庶務課長","answer":"申し訳ございません。設置場所については玄関ですとか通用門ですとか、そういった外部からの侵入のところを見るというような形で設置しています。","id":"exchange-061"},{"speaker":"松本委員","kind":"質問・要望","question":"９割の学校に防犯カメラが設置されていて、その設置場所というのが主に教室の後ろ、上付近。これは要望も上がっているところですので、学校の防犯カメラ設置について検討してほしいと求めましたが、いかがか尋ねました。","respondent":"有馬庶務課長","answer":"現状、トイレの中を見るですとか、どこか適当な教室内を監視するとか、そういったところには多分設置していないと思います。今後どういったことができるのかということは、そういったことがありますので、今後の一つの研究課題とさせていただきたいと思います。","id":"exchange-062"},{"speaker":"松本委員","kind":"質問","question":"最後に教職員人材育成経費に関連して、学校での家庭内児童虐待の早期発見について伺います。お伺いしたいのですけれども、そういったところはどのぐらい学校の教員の間で指導研修が行われているのか、お願いいたします。","respondent":"矢部教育総合支援センター長","answer":"虐待のお尋ねです。この３月にまた校内で研修を行いますので、改めてチェックリストの活用も促します。","id":"exchange-063"},{"speaker":"湯澤委員","kind":"質問","question":"私からは３６５ページ、学校ＩＣＴ活用経費、それから３５７ページ、プログラミング学習について質問します。保護者からは、動画による端末やアプリの説明を区の教育委員会のホームページにて行ってほしいという意見もありましたが。","respondent":"工藤指導課長","answer":"ログインの仕方などを確認できるようなものを配布しておりますので、そういったもので活用を図っていきたいと考えているところです。基本的にタブレットの中からそれを見られるような形で考えておりますので、そこで見られるということも併せてお知らせしていきたいと考えていま…","id":"exchange-064"},{"speaker":"湯澤委員","kind":"意見","question":"ＩＣＴ支援員が週１回学校支援を行うということですけれども、この支援員はどういった資格を持っている人がどこから派遣されてくるのか。子ども支援団体などがＧＩＧＡスクール端末を利用して連携を図っていくことについてはどうお考えになっているかをお知らせくださいとの意見を述べました。","respondent":"篠田学務課長","answer":"ＩＣＴ支援員は、ＩＣＴに関しての研修活動等に特化した専門の会社から品川区の対応者を決めた上で、委託事業となっています。引き続きＩＣＴ支援員とは別に、支援いただける方々にはご協力いただくという形で今後も続けてまいりたいと考えているところです。","id":"exchange-065"},{"speaker":"湯澤委員","kind":"意見","question":"児童・生徒の学習スタイルに大きな変化があるわけですけれども、学校や教員の役割について、今後も変わらず行っていくものがあればお知らせください。自宅学習において、児童・生徒、保護者が準備しなければいけないもの、また注意が必要なものがあれば、併せてお知らせくださいとの意見を述べました。","respondent":"工藤指導課長","answer":"ご家庭等での注意事項等ですが、例えばインターネットにつながる時間は朝７時から夜の９時まで、２１時までとしています。そういったものを通しながら、よりよい運用、また活用を図っていければと考えています。","id":"exchange-066"},{"speaker":"湯澤委員","kind":"質問","question":"ニーズが多いようであれば、品川区が主導して学校のオープンデータ化を進めるべきと考えますが、いかがでしょうか。学習目的であれば、貸与されたタブレットはどこでも誰とでも利用が可能なのか、以上４点をお願いいたします。","respondent":"工藤指導課長","answer":"やはりそういったところで運用を検討していきながら、そのようにしていきたいと考えています。各学校のほうで検討していただく中で、それらについては、やはり学校の意見をよく聞きながら調整していきたいと考えています。","id":"exchange-067"},{"speaker":"湯澤委員","kind":"確認","question":"ただ、スマートフォンやタブレットといったもので確認をしたいという方も少なくないと思いますので、今後ペーパーレスの観点からも。今後、リアルとオンラインの同時開催なども視野に入れていくことを検討すべきかと思いますが、いかがか尋ねました。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"保護者会などでの利用等につきましては、やはり委員ご指摘のとおり、活用することでメリットが様々あるということは私どもも承知しています。ですので、そういった利用につきましては保護者の意見… 理科で使うことになってありますので、今ある端末ですとか、教師が表示している画面において進めていくことと認識しております。そのノウハウを活かして、来年度に引き継ぎたいと考えております。","id":"exchange-068"},{"speaker":"湯澤委員","kind":"質問・要望","question":"学校でのタブレットの利用に際し、どのような形でモラルとルールの教育をしていくのでしょうか。チャイルドラインのようにいつでも必ず気持ちを受けとめてくれるような命を守るアプリを導入するべきとも思いますが、ご見解をお知らせください。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"ＳＮＳのルール等ですけれども、やはり今回タブレットが配布されたということで、ＩＣＴリテラシーも含めて、そういったものを効果的に活用しながら、より質の高い指導が、また教育ができるものと考えています。 ＳＮＳのルールにつきましても学校で進めておりまして、タブレットの活用方法については、それも指導の一つになっていくかと存じます。アイシグナル、あとチャイルドラインというところのＱＲコードを読み込んで…","id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問","question":"３６５ページ、３７１ページ、給食運営費を伺います。学校環境整備事業で、前々から何度かお伺いしている台場小学校の避難通路の件です。","respondent":"小林学校施設担当課長","answer":"私の聞いているところでは、現在お隣の都営住宅の入居者の２分の１の同意を取るというお話を聞いております。締結後、区としましては、速やかに令和３年度内には工事を進めたいと考えております。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点お伺いします。可能にしていただきたいという趣旨での質問ですが、。","respondent":"横山品川図書館長","answer":"今６区が導入している状況ですが、品川区も含めて６区がまた導入予定ですが、おそらくは大勢を占めるものと思われます。ただ、１回図書館に足を運んでいただいて、もしかしたら図書館を利用していただけるということで効果的だと考えています。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問","question":"学校ＩＣＴ活用経費でＧＩＧＡスクール構想、タブレット端末が幾つか出ていますけれども、まずお伺いします。ＧＩＧＡスクール構想のＧＩＧＡというのは何のことでしょうか、説明を求めました。","respondent":"篠田学務課長","answer":"「Global and Innovation Gateway for All」です。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど午前中に、湯澤委員からどうやって保護者の方に周知をするのですかという使い方の周知の話はありました。そういうことを保護者にお示ししていただいているのかどうかも含めて説明を求めました。","respondent":"工藤指導課長","answer":"これまでも行ってきた一貫教育の中で学力定着を図っていることをより効率よく、また質を高くできるというふうに考えてあります。これまでも広報等で行っている部分ではありますが、今申し上げたことをより保護者の方にもご理解いただくよう検討してまいりたいと考えています。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょっと細かいところを伺います。対象のお子さんがいらっしゃる方はご存じなのでしょうけれども、以前、伺いたいと思います。","respondent":"篠田学務課長","answer":"一つ大きな理由としまして、ＬＴＥの場合、タワーマンションの高層階では非常につながりにくいというような状況があるというふうにお伺いしました。そうなりますと、そういった場合に対応できるようにということと…","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、どういうものをやっていくのか、魂はどこに入れるのかという研究をよろしくお願いしたいと思います。そこのところについて、実践については学校の場で行う必要がないのか、そこについてお伺いをしたいと思います。","respondent":"篠田学務課長","answer":"なかなかこれまでも委員から様々なご指摘がありましたとおり、これまでも各学校におきまして柔軟な対応を取るという形で教育委員会も指導しています。ご指摘のように様々な観点を踏まえた形で、各学校の教職員も捉えているというふうに認識しているものです。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"請願にも書いてあるのですけれども、２万２,０００人掛ける１９５日で年間大体４２９万本ということになっています。そこは学校教育の場で、率先して実践をしていただきたいということをお願いして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３５５ページ、および３５７ページ、特色ある教育活動経費からメディアリテラシー教育について順次質問してまいります。がん教育についてお尋ねします。","respondent":"矢部教育総合支援センター長","answer":"簡潔に２点申し上げます。１点目はがんについて正しく理解することができるようにすること、２点目は健康と命の大切さについて主体的に考えることができるようにすることです。","id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"２０１９年の決算特別委員会の総括質疑でもＨＰＶワクチン接種と子宮がん検診の重要性を授業で取り上げることを要望しましたが。現在感染症とがんについてどのような授業が行われているのでしょうか、ご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"中学校では生活習慣病などの予防の中でがんの予防について指導しています。品川区では今年度から全区立中学校と義務教育学校後期課程において医師を講師としたがん教育を実施しており。","id":"exchange-078"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ぜひＨＰＶワクチンについて、９年生のがん予防の学習の中で取り上げることを強く要望いたします。この男子に対するＨＰＶワクチンの情報提供もがん教育、性教育の重要な一環ではないかと考えますが、教育委員会はどのようにお考えか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"男女一緒に共習で授業を実施しておりますので、子宮頸がんやワクチンについても男女ともに触れる機会はございました。先ほどのお話のとおり感染症とその予防の中で性感染症を取扱う内容は中学校や高等学校の学習内容で取扱いがあります。","id":"exchange-079"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、新型コロナウイルス検査陽性の小・中学生の対応についてお伺いいたします。は親が検査陽性のため濃厚接触者として自宅待機になった生徒への対応はどのように行われているのか尋ねました。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"いわゆる世間で流行が始まりました第３波といわれた時期、１２月が１６人、１月が４２人とかなり増えました。それから緊急事態宣言が出た後の２月は７人という形で抑えられまして… ４月、５月にもあったとおり教材を家庭に配付することもございましたし、課題を見たりということで対応しています。担任が中心になりまして電話等の定期連絡をすることで…","id":"exchange-080"},{"speaker":"鈴木（博）委員","kind":"意見","question":"俯瞰的に見ることが大切で、全体にどうアプローチするかを忘れてはいけない」と答えています。区のご見解についてご説明を願いますとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"学校では、分散登校が始まった６月から現在に至るまで校内でも継続して指導をしています。実施に向けて配慮しなければならないことがあるとは考えており、今後もさまざまな方法を検討しまして、偏見・差別防止を進めてまいります。","id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次の質問に移ります。品川区はメディア対策をどのようにお考えなのでしょうか、一言ご見解をお願いします。","respondent":"矢部教育総合支援センター長","answer":"膨大な情報の中から必要な情報を取捨選択するということは大変大事なことでございまして、市民科を中心にＳＮＳを中心に指導していますが、他教科とも関連させまして、総合的に指導してまいりたいと考えております。","id":"exchange-082"},{"speaker":"横山委員","kind":"質問・要望","question":"養護教諭の先生方などにユースクリニックを見学いただく機会を設けていただきたいと要望いたしますが、教育委員会のご見解をお伺いいたします。２点目に、市民科・各教科充実経費についてお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"基本的に学校に１人しかおりませんので、回数、内容について十分吟味して検討してまいりたいと考えております。約６時間程度で進めており、ＳＮＳということも関係しますので、さまざまな形で子どもたちを指導しています。","id":"exchange-083"},{"speaker":"横山委員","kind":"質問・要望","question":"子どもたちにあなたの経験を教えてあげてほしいといったようなグループセッションなど、褒められたり、効果があったというお話をお聞きしました。悩みを言語化する力というのをどのように育成しておりますか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"自殺予防については５年生以上でストレスや悩みの解消法、自分を大切にするなどの学習を通して言語化もその中に入りますが、系統的に指導しています。あわせて、言語化ですと、国や東京都、品川区が後援するＮＰＯなどの相談窓口も周知していますので…","id":"exchange-084"},{"speaker":"横山委員","kind":"質問","question":"３点目に、特色ある教育活動経費についてお伺いいたします。この経緯とグローバル給食の成果、また国際理解を深めていく今後の展開について説明を求めました。","respondent":"篠田学務課長、工藤指導課長","answer":"そういった給食が今実施できていないという状況がございまして、今年度も予算計上はしたのですけれども、実施ができなかったという状況です。来年度も検討をしたのですが、この事業自体が成立しないということがありますので… これまでもオリンピック・パラリンピック教育の中で海外の方との交流を行いながら他国の文化を学ぶ際に一緒に給食を食べるなどの取組みを行ってあり…今後におきましても…","id":"exchange-085"},{"speaker":"横山委員","kind":"質問・要望","question":"レガシーとしてぜひグローバル給食を未来に引き継いでいただきたいと要望いたしますが、その部分、教育委員会のお考えをお伺いいたします。オークランド市やアジア地域とのオンラインでの国際交流というのもご検討ほしいと求めましたが、教育委員会のお考えを説明を求めました。","respondent":"篠田学務課長、工藤指導課長","answer":"グローバル給食の今後の話です。オリ・パラのレガシーという意味合いもありますので、その状況を見ながら、今後の展開については改めて検討したいと考えています。 現在８年生全員がオンラインレッスンというのを授業の中でも、フィリピンにいる海外講師とのやりとりを行ってあります。そういった取組みを周知しながら、そういった部分の取組みも充実を図っていきたいというふうに考えてあります。","id":"exchange-086"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひグローバル給食を再検討していただいて、引き続きレガシーとして続けていっていただけたらと考えています。８年生のオンラインによるフィリピンの方とのレッスンというのも承知しておりまして、要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"おくの委員","kind":"質問・要望","question":"私は３５５ページ、学力定着度調査に関わって、いわゆる学力テストの中止を求めて質問いたします。国や東京都が学力テストを中止したことで何か困ったことになったと、そういう声は上がったのか尋ねました。","respondent":"工藤指導課長","answer":"独自に学力定着度調査を今年度も実施いたしましたので、そういった意味で、本区の中で活用に困るということはございませんでした。国および都が行わなくなったことで新たに検討した地区もあるというふうに情報をいただいているところですが、従来の学力定着度調査を行うことで。","id":"exchange-088"},{"speaker":"おくの委員","kind":"質問","question":"品川区が実施されたのは、特に学力テストをやってもらわないと困るというような声が区民の方から上がったということなのでしょうか。この点いかがでしょう。","respondent":"工藤指導課長","answer":"児童・生徒一人ひとりの学力の定着状況を見取り、教員が個々の児童・生徒の指導に活かし、授業改善を図ることを目的としているものです。今年度学校が再開された後、児童・生徒の過度な負担にならないよう配慮しつつ実施をしたというものです。","id":"exchange-089"},{"speaker":"おくの委員","kind":"質問","question":"要するにテストの正答率の人数分布を上から４分の１ずつ、Ｃ、比較することができるようになったというふうに文教委員会で説明されていました。こういう四分位分析をすることになったのは、そういう目的なのでしょうか、伺います。","respondent":"工藤指導課長","answer":"Ｂ層、Ｃ層、Ｄ層と２５％ずつの刻みの中で各学校が状況分析をしながら授業改善に活かしたところです。相対ではそのように評価していきますが、全体としての分析についてはこの四分位分析を国や都も行っておりますが、今年度から区でも導入したです。","id":"exchange-090"},{"speaker":"おくの委員","kind":"質問","question":"そういうものを生み出すということは大きな弊害を生み出しているのだというふうに認識なさらないのですか。伺います。","respondent":"工藤指導課長","answer":"知識、技能および思考力、判断力、表現力等、今学びを考える上ではさまざまな観点があります。繰り返しですが、学力定着度調査は他者や他校との比較などを意図して行っているものではございません。","id":"exchange-091"},{"speaker":"おくの委員","kind":"質問・要望","question":"物事の仕組みを発見していくわけですから、子どもにとっては喜びだと、そういうわけです。この大きな弊害を結果として生み出している学力テストはやめるべきだと思うのですけれども、いかがでしょうか、伺います。","respondent":"工藤指導課長","answer":"今の委員のご指摘のようにわかるというものを積み重ねていく、これはやはり学びの中で非常に大切なところです。見方、考え方も含めて定着を図っているものですので、引き続き実施をしていく考えです。","id":"exchange-092"},{"speaker":"芹澤委員","kind":"提案","question":"これから、教育委員会の所管内の話を伺おうと思うのですが、誰がどういうふうに検討していくのかお聞かせほしいと求めました。これからデジタルに関する課ができるというふうに伺っていますから、現状どのようなお考えで外部のアプリを入れるというような予定なのか尋ねました。","respondent":"篠田学務課長","answer":"現状は先ほど委員からもお話がございましたとおり、まずはそのような形で使っていただくのが重要だろうというふうに思っているところです。ただ、そういったものを導入するということも教育委員会として検討していくというのはありなのかなというふうに捉えているところです。","id":"exchange-093"},{"speaker":"芹澤委員","kind":"質問","question":"所管内の話、教育に関わるものに関して引き続き伺っていきますが、私からもいじめの相談窓口というのを以前問い合わさせていただいたことがあります。ご見解を説明を求めました。","respondent":"篠田学務課長","answer":"デスクトップにそういったショートカットを置くといったことに関しましては、技術的にそれほど難しくないものですが、内部的にこれから受付の窓口等の対応状況等もありますので、そういった点を踏まえながらできる手だては順次取ってまいりたいというふうに考えているところです。","id":"exchange-094"},{"speaker":"芹澤委員","kind":"質問・要望","question":"次の項目の給食運営費について伺います。ちょっとそれに関連して給食のことをお伺いしていきますが、大豆ミートが有名なものですけれども、代替肉というのが世界的に取り上げられています。","respondent":"矢部教育総合支援センター長","answer":"現在食育は市民科を中心に、社会、理科、家庭科等で教科横断的に進めております。植物由来の肉と畜産による牛肉のＣＯ２の排出量の比較など、一つの事例として発展的な学習や家庭学習として取り上げることは可能と考えております。","id":"exchange-095"},{"speaker":"芹澤委員","kind":"意見","question":"大豆ミートは私も毎年食べていますけれども、昔は本当に食べられたものではなかったのですね。食べられるよという議論になって、ぜひ大豆ミート、代替肉を使った給食というのを前向きにご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"せお委員","kind":"質問","question":"さらに、特別支援学校に籍を置くお子さんは、東京都がタブレットを準備するという認識でよろしいでしょうか。そこに区はどのように関与するのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"今ご案内のように学校に来られないお子さんにはタブレット等で学習対応しておりますので、物理的に可能です。特別支援学校に在籍され、そして都立学校の学校とまた私どもの教育委員会で丁寧に対応して、一番最適な形を模索していきたいと考えております。","id":"exchange-097"},{"speaker":"せお委員","kind":"提案","question":"１年前の一般質問でオンライン授業もＯｒｉＨｉｍｅの活用もご提案しましたけれども。以前から要望していたので大変喜ばしいですとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"１点目ですが、現状、既に就学前にお子さんとご家庭と学校とで連絡を取ってありますが、お入りになる予定の方は２名です。２点目の看護師が入ることで当然今まで自分ではできない、特別支援学級に来られる、というような安心感を持って幅を広げられたと理解しております。","id":"exchange-098"},{"speaker":"せお委員","kind":"質問・要望","question":"さらに、研修を修了して認定されれば、医療行為のうち５項目の実施ができる認定特定行為業務従事者を積極的に取得していただきたいと要望します。このことは以前にも質問させていただいたのですが、状況も変わってきていますので、いま一度見解を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"ぶら下げて対応することもありますので、個々に応じて努めてまいりたいと思いますが、看護師がつくようなお子さんへのケアについては十分慎重に行いたいと考えていますので。","id":"exchange-099"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、何より本人の未来のためにご家族、保護者から離れる時間というのを増やしてほしいと求めました。就学相談ですが、医ケア児のように支援が比較的必要なお子さんやご家庭の事情がある方などに関して、もっと早期にできるよう要望いたします。","respondent":"矢部教育総合支援センター長","answer":"６月からスタートしていますので、これまでの個別の教育支援計画等をいただきながら、前年度にお願いしたいと考えております。毎年３００件以上の就学相談を受けてありますので、体制のこともご配慮いただけるとありがたいです。","id":"exchange-100"},{"speaker":"せお委員","kind":"質問・要望","question":"本来であれば、同じ学校の一員であるので、みんな一緒にいることが当たり前になってほしいです。そして、今お伝えした好事例を区教委が積極的に情報収集し、区教委が情報発信をして全学校に取り入れてほしいと求めましたが、見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"ただ、実態としてはどうしても特別支援学級でお伝えしたい連絡が朝にある場合は難しいということとか。好事例はそれぞれ活かしていると聞いてありますので、今後も特別支援教育全体を推進していきたいと考えております。","id":"exchange-101"},{"speaker":"せお委員","kind":"質問・要望","question":"通常のクラスに名前があれば、保護者はみんなと同じように考えてくれているのだと、それだけでも全然うれしく思います。そのような保護者の気持ちも考えて取組んでいただくよう要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"くにば委員","kind":"質問・要望","question":"オンライン化についての要望の声は非常に大きく、特に欠席届については区民からもさまざまなお困りの声が届いています。令和２年１０月２０日、教育委員会等においては学校が円滑にデジタル化等に移行できるよう、必要な支援をするようにと教育委員会に対して求めました。","respondent":"工藤指導課長","answer":"具体的には今１人１台のタブレットで、全学校に配布し、今検討を進めているところです。全学校でさまざま運用を検討しながら、できるところから進めていきたい、運用していきたいと考えています。","id":"exchange-103"},{"speaker":"くにば委員","kind":"質問","question":"できれば、今お伺いしたスケジュールについてもう少し詳しく説明を求めました。","respondent":"工藤指導課長","answer":"試験的に運用を始めている学校もありますし、今後４月のタイミングで始める学校もあります。時期としては来年度４月以降に導入をしていき、できるだけ運用のほうを図り、全学校で取組んでいきたいと考えています。","id":"exchange-104"},{"speaker":"くにば委員","kind":"質問","question":"保護者に配付するプリントのデジタル化、こちらについてもお伺いします。区教委の方針や実現可能な時期などを説明を求めました。","respondent":"工藤指導課長","answer":"先般行われた９年生の思い出作り事業の中では、その場で学年便りを作成し、そこから保護者に向けて発信したという事例もあります。そういった取組みについて各学校でも周知を図りつつ、そういったできるところから進めていきたいと考えています。","id":"exchange-105"},{"speaker":"くにば委員","kind":"意見","question":"これらを集約して、さらに各学校でスピーディーに周知、情報共有していくことが区内全学校での導入を加速させるためには不可欠だと考えます。この点の取組みやお考えについて説明を求めました。","respondent":"工藤指導課長","answer":"回答については随時各学校にお返しするというところで、時間を置かずに、そういった問い合わせについてもさまざま対応できるようにしています。タブレットのＴｅａｍｓの機能を使いながら、各学校の好事例についてはその場で共有し…","id":"exchange-106"},{"speaker":"くにば委員","kind":"質問・要望","question":"オンライン化が進められるよう教育委員会から力を入れて各学校に取組みを求めることを強く要望します。全学校での学校、保護者間の連絡のデジタル化の取組みに向けて、目標と意気込みを説明を求めました。","respondent":"工藤指導課長","answer":"できるものについては全学校で取組むという姿勢で学校のほうに指導しながら、またさまざまご意見もいただきながら、検討しながら運用していきたいと考えています。","id":"exchange-107"},{"speaker":"くにば委員","kind":"質問","question":"続きまして、図書館運営費のティーンズ世代サービスについてお伺いします。は令和２年度の事業内容と令和３年度に向けた取組みを説明を求めました。","respondent":"横山品川図書館長","answer":"蔵書の入替えに伴いまして、ティーンズ専用のコーナーを設置するということで区内６館において増設や移設を行っているような状況です。品川女子学院の図書館展示と協力し、コロナ禍でビブリオバトル等の事業が中止されたことに伴いまして…","id":"exchange-108"},{"speaker":"くにば委員","kind":"意見","question":"幼児への読み聞かせにしても、大切さを体感して積極的に手を取っていた大人の層では、やはり読み聞かせの頻度にも差が出ます。親世代の読書習慣の向上についての施策も子ども世代の読書習慣定着にとっては重要だと考えますけれども、お考えや取組みを説明を求めました。","respondent":"横山品川図書館長","answer":"昨年策定いたしました子ども読書活動推進計画の取組みとして家読というのがあります。親に向けては、絵本を子どもに読んでいただくことで親世代も読書に目覚めていただくというような取組みとして捉えてあります。","id":"exchange-109"},{"speaker":"塚本委員","kind":"質問","question":"３６５ページ、３５３ページの、多子家庭給食費補助をお伺いしたいと思います。令和２年度にできなかったさまざまな事業やこういったものをフォローするような、そういうものを何か考えられているのかをお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"部活動ということに特化しますと、品川ケーブルテレビが全１５校の部活動紹介番組を制作し放送するということで、こちらのほうを推進したところです。６年生、９年生を中心に思い出作りということで、校外学習をやっているです。","id":"exchange-110"},{"speaker":"塚本委員","kind":"質問・要望","question":"これをぜひ区教育委員会として検討していっていただきたい、このように強く要望させてほしいと求めましたので、よろしくお願いいたします。どういう施設が必要なのかとか、教員の体制とか、こういうことについて説明を求めました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"今わかり得る範囲でお答えします。東京都のほうから正規教員が配置されますけれども、現状は細やかにお子さんを見ていくという面ではなかなか足りないということも聞いてあります。 ですので、例えば体育館が必要であるとか、そういった一定程度の要件は通常の学校の設置と同様にあります。あるいは９８０時間で可能にする、空いた時間は心のケア…","id":"exchange-111"},{"speaker":"塚本委員","kind":"質問","question":"分教室の形の不登校特例校というものを東京版不登校特例校というふうに位置づけて、そこの設置を促進しているというふうになっております。品川区のほうでどういったやりとりがあったのか、なかったのか、東京都と区とのこれまでの経緯ということについてお伺いしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"マイスクール八潮では体験活動を中心に、不登校特例校にも匹敵するような環境を整えているというふうに考えております。家庭と学校の連携事業や不登校の加配教員の配置などによって効果が現れていると捉えておりますので、また考えていないです。","id":"exchange-112"},{"speaker":"塚本委員","kind":"質問","question":"品川区ももちろん不登校対応ということではいろいろと対応されていると思いますけれども、こういった二つの道みたいなものを設けていくねらいとか意味、こういうことについてはどのようにお考えか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"ほかの区と同様にはちょっと考えられないところがありますので、また先ほどの施策なども評価しながら、これから不登校の施策について丁寧に考えていきたいと思っています。","id":"exchange-113"},{"speaker":"塚本委員","kind":"質問・要望","question":"区の認識を伺いますというふうに質問させていただいて、区のほうからは効果的な授業の展開モデルや実践例をまとめた授業改善の資料を作成、配付する。これは来年度に向けてどのような形で今進められているのか確認をさせてください。","respondent":"工藤指導課長","answer":"実践例をまとめた授業改善の指針となる教員向けの資料につきましては、既に作成しまして、令和２年１１月に配付したところです。それらを使いながら、また指導教諭あるいはＩＣＴ推進リーダーが行った先進的な授業についても、ＩＣＴ通信という形で教員に周知を図ったところです。","id":"exchange-114"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういうところについて特段何かしらのガイダンスみたいなことが行われているとかがあれば教えていただきたいというのと、どうしてもなかなかうまく使えないみたいな、その点について何か今少しずつ進めている中でわかっていることがあれば説明を求めました。","respondent":"工藤指導課長","answer":"必要に応じて児童・生徒の指導に当たりながら、その方たちに使い方について指導いただくことがあっても大丈夫なように体制を組んでいるところです。やはり先ほどの学習支援員等、また教員とチームを組みながら、きちんと丁寧に指導していきたいと考えています。","id":"exchange-115"},{"speaker":"塚本委員","kind":"質問・要望","question":"すみません、時間がない。そうなので頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"質問","question":"３５７ページ、今お話の出た３５９ページ、マイスクール運営費関係からお聞きしたいと思います。どのぐらいの人数が不登校で、マイスクールに通っているお子さんは何人ぐらいいらっしゃるのか、その辺から説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"後ほど、数字が出ましたらすぐにご報告します。すみません。","id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先ほど品川区ではいじめがないというお話だったのですが、傾向的なものもわかれば教えてもらいたいなと思います。それから、当然学校で頑張っているので復帰していると思うのですけれども、その辺の確認をしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"１回出てくるのですけれども、ちょっと復帰率を単純にはお伝えできないのですが、戻ってくるお子さんもいます。それと、先ほどは失礼いたしました、わからなかったところですが、令和元年度の品川区立小学校の不登校のお子さんは１２１人、中学校が１９５人です。","id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"質問","question":"浜川とありますが、さっきもお話がありましたけれども、それぞれ特色を持った形でやっていらっしゃる。五反田、ちょっとその辺は判断がつかないのですけれども、これから何か充実してやっていく方法というのは考えていらっしゃるのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"今後指導員を少し増やしまして、五反田のほうは今まで月曜日がお休みだったのですが、開室をします。曜日を分けてできるだけいろいろなお子さんが来られるようにというふうに考えております。","id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから、このマイスクール、三つから選ぶ中で、これは自分で選ぶのですか。学校側でここがいいのではないですかと勧めているのか、その後どういうふうにうまく進んだのか、その辺も説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"進路です。おかげさまで中学生は全員進路が決まりました。","id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それから、これはやはり不登校という関係が出てくると思うのですが、教育委員会の事項別説明資料を見ていくと中身が出ていなかったのですよね。それはたしか東京都の事業ということからかと思うのですが、なぜそれが出ていなかったのかとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"学校と家庭の連携推進事業は、東京都からも補助を受けているです。中身については、支援員とスーパーバイザーが入るという費用です。","id":"exchange-121"},{"speaker":"鈴木（真）委員","kind":"質問","question":"５校と事項別説明資料には出ているのですが、この５校というのは５人という意味なのか、それともその学校の中でまた何人かいるのか、その辺を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"学校に来られるのだけれども、ほかのお友達と勉強できない人が別の教室で勉強するのを一緒に付き添ったりという、支援員という名前がついています。５校で実施しています。","id":"exchange-122"},{"speaker":"鈴木（真）委員","kind":"質問","question":"時間がなくなってしまったので帰国子女関係の教育ということでお聞きしようと思ったのですが、例えば中学生の交流という部分です。来年度に向けて、どう考えていらっしゃるのか、まず考え方だけ説明を求めました。","respondent":"工藤指導課長","answer":"今委員からご指摘いただきました国際友好協会が実施している青少年語学研修派遣事業におきましては、各中学校長の推薦枠をいただいておりまして。そういったところで、学校のほうでは派遣生のところというのは実施する上で、現状は派遣調整を行っているところです。","id":"exchange-123"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今度そういうときにそういうお子さんが手を挙げたときには、教育委員会で何か推薦してあげることはできないのかなということを、これは要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-124"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこはぜひそろえるところはそろえて、かつ情報を公開してほしいと求めましたが、いかがでしょうか。教師と保護者がフラットな関係でＩＣＴ活用を模索するプラットフォームも視野に入れてはいかがかと思いますが、いかがか尋ねました。","respondent":"工藤指導課長","answer":"下半期に分けて、必要なステップを学校に示しておりますので、各学校で活用を推進するように進めたいというふうに考えてあります。そういった協力も得ながら推進のほうを図っていきたいと考えています。","id":"exchange-125"},{"speaker":"あべ委員","kind":"質問","question":"元防衛医科大学教授の、『教師にできる自殺予防子どものＳＯＳを見逃さない』という書籍を出版された高橋聡美先生のお話を伺う機会がありました。ＳＯＳの受け止め方研修、これを積極的に展開されてはどうかと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"これまでも管理職はゲートキーパー研修、また教育総合支援センターのほうでは生活指導主任と養護教諭を対象にゲートキーパー研修をしております。内容は今の受け方も大事にしていきたいと思いますので、また今後研修のあり方について、内容をちょっと協議していきたいと思います。","id":"exchange-126"},{"speaker":"あべ委員","kind":"質問","question":"これについて改めてお考えをお伺いしたいと思います。それから、校庭整備についてもお伺いします。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"４年生の保健の学習で男女ともに月経、その際に養護教諭のほうから、また先ほど答弁を申し上げました移動教室の前にも生理用品の説明をしています。恥ずかしいというのはよく納得できるところですので… 例えば排水口のところに、メッシュのものを置いたりして、目に見える形でそういうところを確認しています。今後検討していきたいと考えております。","id":"exchange-127"},{"speaker":"あべ委員","kind":"質問・要望","question":"子どもたちに命や体を大切にするという気持ちを育むことができるのかということをゼロベースから組み立てていただければと考えています。最後は要望にして終わりますが、どうぞ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-128"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから３６１ページの特別支援教育費、医療的ケア関連経費と特別支援教育の推進計画をぜひ作っていただきたいという思いで質問をしたいと思います。品川区の飲酒、薬物依存防止の教育の取組みについてもお聞かせほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"体に悪いということで、禁煙とか禁酒ということではなく、その害について指導をしているということです。薬物については、薬物乱用はいけないということで、そこでも同じ指導をしています。","id":"exchange-129"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこのコマーシャルの規制に対しても、教育の現場からぜひ意見を上げてほしいと求めましたが、いかがでしょうか。薬物乱用防止教育というのはたった１回きりではなく、内容ともに継続してやっていくということが大事だと思うのですが、その点についても伺います。","respondent":"矢部教育総合支援センター長","answer":"時間としては５、６年生の間に１時間程度、８年生の間に１時間程度と把握しています。それを生徒自身が、私たちもそうですけれども、自身で考えを持って判断していくということにつながるのかと考えております。","id":"exchange-130"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"中学校でも１時間だけ、これを本当にここで食い止めるということが大きな効果になっていくと思いますので、その点の拡充を求めたいと思います。次に、医療的ケア児についてお伺いしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"小学校が主だと認識しています。〔同日後刻に「小学校が３人、ほぼ都立の特別支援学校と認識しておりますので、いらっしゃらないと把握しております。","id":"exchange-131"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"学校にいる間は家に帰ることができたと、人工呼吸器をつけている子どもは見てもらえない、受け入れられないということなのでしょうか。親が付き添って通うしかないと、今回そういう医療的ケア児への対応なのでしょうか、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"医療的ケア児の対応については、就学相談で決まらないことはお伝えできないようなところでございました。どこの学校がご本人にとって、また保護者の意向に沿って適切なのかということを一緒に考えてまいりたいと思います。","id":"exchange-132"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことになっていくのか、それとも人工呼吸器までは行かないというふうなことで考えているのか、その点について伺いたいと思います。看護師２名の配置ということですけれども、これは学校看護師ということで確保されることになるのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"ですので、今後就学相談全てにおいて対応してまいりますけれども、人工呼吸器をつけていらっしゃるお子さまは対象外にしています。手すり等をつける費用は若干予算として計上していますので、そういった処置はできるかと存じます。","id":"exchange-133"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"人工呼吸器の方は受け入れないということですが、今回やってみて、ぜひなるべく早急に人工呼吸器の方も受け入れるよう強く要望したいと思います。区としてもぜひこの計画、特別支援教育推進計画を作っていただきたいと思うのですが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"特に義務教育学校の特別支援学級は前・後期ともに全て設置されたということで、一つこれが節目だったと考えています。ご存じのように人口の増加もありますので、今後も見通しを持って計画的に進めてまいりたいと存じます。","id":"exchange-134"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３７１ページ、３７５ページ、学校改築推進経費の中の源氏前小学校について質問します。その研修の精度についてお伺いしたいと思います。","respondent":"工藤指導課長","answer":"教員向けについては、各校に１名おりますＩＣＴ推進教員向けに行って、そのＩＣＴ推進教員が各学校で伝達するということをまずは進めてあります。使いやすいところ、さまざまな年齢層もおりますけれども、使いやすいところから始めるというところで研修を組んでいるところです。","id":"exchange-135"},{"speaker":"高橋（伸）委員","kind":"質問","question":"学校によっては１年生から５年生とか、今小学校、中学校でもさまざまな外国人の保護者の方がいらっしゃる。そういった中の対応というのはどうされているのかをお伺いしたいと思います。","respondent":"工藤指導課長","answer":"その中の１ページには、そこは学校のほうでカスタマイズしていただいて、ぜひ学校で必要な情報を上げてくださいと。ただ、そういった意味では、学校でカスタマイズを自由にしていただけるようにしています。","id":"exchange-136"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"平成２５年からは飲用牛乳を除く給食１食分、１週間をまとめて大体４校ですか、放射性ヨウ素の検査を実施しています。指示というのがあるのかどうか確かめていただきたいのと、ぜひとも検査自体を再来年度にはやめていただきたいというのが私の要望です。","respondent":"篠田学務課長","answer":"目黒区のお話をいただきましたけれども、私どもは専門の検査機関に出して検査をしてもらっているという状況です。再来年度以降につきましては、状況を見ながら判断してまいりたいというふうに考えているところです。","id":"exchange-137"},{"speaker":"高橋（伸）委員","kind":"確認","question":"そうすると、まだ再来年度というのはわからないということでよろしいのでしょうか。確認です。","respondent":"篠田学務課長","answer":"これまで１０年にわたって給食の食材の検査をしてまいりまして、これまで一度も検査で数値として上がってきたことはないということもあります。したがいまして、来年度どういった形になるか、その結果を踏まえまして…","id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最後に、３７５ページ、源氏前小学校の改築のことで、来年度に敷地測量委託がついていまして、今年度は改築の計画検討というのがございました。具体的にどういった内容だったのかお知らせほしいと求めました。","respondent":"小林学校施設担当課長","answer":"令和元年度に改築等の検討をしたところですが、これにつきましては、まず改築にするのか、増築にするのか、そちらのほうを比較検討したところです。学校の敷地の中に一部国有地がありますので、まずは国有地を購入するための敷地測量を行っていきたいという考えです。","id":"exchange-139"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"源氏前小学校も第４地区の防災訓練があったりとか、ぜひ改築の際はそういうことを踏まえて検討してほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-140"},{"speaker":"田中委員","kind":"質問","question":"給食の放射能測定について関連質問します。は検査方法を今の時期、子どもの健康を守るという区の姿勢を示すことにつながると考えますが、区教委の見解を伺います。","respondent":"篠田学務課長","answer":"一つは、都の数値に関するものですけれども、私どもから東京都の下限値についてコメントするのは差し控えたいというふうに考えているところです。それで、これまでずっと実績を積み重ねてきているということがありますので、来年度も同じ方法で実施することを想定しているもので…","id":"exchange-141"},{"speaker":"田中委員","kind":"質問・要望","question":"しかし、実際には自治体が検査をしており、しかも国が検査を求めている自治体は１７自治体のみです。これからも安全を確認するためにも検査の継続と単品検査への転換を求めますが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"基本的な取組みとして一定の成果もあるというふうに考えておりますので、今のところ変更する予定はございません。今後の継続につきましては、また、そういうことを踏まえまして判断をしてまいりたいというふうに考えているところです。","id":"exchange-142"},{"speaker":"田中委員","kind":"質問・要望","question":"安全を確認するために検査を継続していただきたいです。単品検査も出やすい食材というのはわかっているので、ぜひそういった食材の検査に切り替えていただきたいと強く要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-143"},{"speaker":"西本委員","kind":"質問・要望","question":"それから、３６９ページの教室等照明ＬＥＤ化工事費、これは何％くらいまで処理できていますかということを確認させてください。この学校選択の現在の目的は何か尋ねました。","respondent":"篠田学務課長、有馬庶務課長、工藤指導課長、小林学校施設担当課長","answer":"来年度の実施状況にもよりますけれども、終了ということも視野に入れた判断というのは、あり得るのかなと考えているところです。… 現在残っている小学校４校ですが、山中小学校、延山小学校、宮前小学校、源氏前小学校です。そのうち延山小学校と源氏前小学校については… 保幼小連携につきましては、５歳児の保護者向けにリーフレットを作成いたしまして、就学前教育から小学校への円滑な接続を図っておるところです。… 学校のＬＥＤ化の状況ですが、進捗率は約７０％です。","id":"exchange-144"},{"speaker":"西本委員","kind":"質問・要望","question":"検出していないわけですから、これから冷静に考えて対処していただけると信じておりますので、よろしくお願いいたします。なので、ここで、これからどういう教育にしていくのかということをお示しほしいと求めました。","respondent":"篠田学務課長","answer":"地域との連携につきましても、小学校の選択ができる制度に変えてきて、地域とつながりのある形に変えてきております。まずは重要だろうと考えていますので、少しでもよりよい形になるように、教育委員会としても取り組んでまいりたいと考えているところです。","id":"exchange-145"},{"speaker":"西本委員","kind":"意見","question":"学校選択制については、地域での教育ということも含めて、やはり見直しをすべきときが来るかと思いますので、お考えいほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-146"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３６１ページ、特別支援教育費、３６５ページ、書籍除菌機、同じページで会計年度任用職員給与費、この３点を伺いたいと思います。こういうお子さんに対しての品川区の対応、お考えについて、お聞きしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"幼稚園、保育園等を含めて関係機関と連携を取りながら、適切な学校をご紹介するということになります。もちろん保護者とも十分に相談を繰り返してまいります。","id":"exchange-147"},{"speaker":"こんの委員","kind":"質問","question":"区は、こうした医療的ケアが必要な肢体不自由児のお子さんにおける登下校の実態について、どのように捉えますでしょうか。こうしたご相談を直接受けたときには、どのような対応が考えられますでしょうか、説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"現状ですが、本区ではこのように重要で、かつ丁寧な対応が、なかなか困難な体制です。学校はもとより関係機関とも連携しまして、その時期ですとか条件についてご紹介するところはセンターができることかと認識しております。","id":"exchange-148"},{"speaker":"こんの委員","kind":"提案","question":"都に対して特別支援学校における医療的ケアの保護者の付添い期間の短縮化を求めて、都議会においてその課題を挙げて短縮化を求めたところ、東京都は。あるいはタクシー利用に対する補助の創設など、障害者福祉課とも連携して検討することを提案したいと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"ご事情は十分分かりましたけれども、都立学校ですので、今、進捗が都でもあるですので、そちらにお願いすることになって、現状を変えることはできません。","id":"exchange-149"},{"speaker":"こんの委員","kind":"提案","question":"この医療的ケア児の学びの保障として、登下校における支援策を要望したいと思いますが、もう一度ご答弁をお願いいたします。これまで何度か、区立図書館全館に配備をと提案し、要望してきましたとの意見を述べました。","respondent":"横山品川図書館長、矢部教育総合支援センター長","answer":"来年度５館に導入することによりまして、区立図書館全てに配備する予定になってあります。新年度になりましたら、入札を経て、できるだけ早く配備する予定です。 先ほどの医療的ケアのお子さんの送迎についてですが、基本的には、都立学校ですので都立の方針を注視してまいりますが、区としてできることがあるのか、ないのかというところも含めまして、障害者福祉課とも連携して研究してまいります。","id":"exchange-150"},{"speaker":"こんの委員","kind":"質問・要望","question":"これは要望で終わります。１校について何人ぐらい配置されているのか、配置された学校の職員の方から、配置されてどうだったのかという声などがありましたら説明を求めました。","respondent":"工藤指導課長","answer":"区内の現状では、全校合わせて７５名のスタッフに働いていただいておりますので、１名ないしは２名とお考えいただければと考えています。本当に困ってしまうという声も聞いていますが、教員からは、働き方改革の面でも非常に助かっているという声を聞いているところです。","id":"exchange-151"},{"speaker":"本多委員","kind":"質問","question":"３６７ページのルネサンス推進事業と、先ほど質疑が出ていましたグローバル給食について、重ならないように質問したいと思います。令和３年度予算の内容、規模も説明を求めました。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"私からは、サントレの予算関係についてお答えいたします。サントレが予算化されているのが４校ございまして、この１,９９９万９,０００円のうち４６５万８,０００円がサントレの教材費になってあります。 控えて実施し、また映像を配信して各教室で見られるなど、工夫しています。個別の発表をビデオに収めて、後日ほかの児童が視聴するようにしているということでございました。","id":"exchange-152"},{"speaker":"本多委員","kind":"質問","question":"４校全てで実施されているのですかね。ＹｏｕＴｕｂｅに撮って配信するのに、その撮り方というのはどういう規模で撮っているのか、その辺を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"各学校、現状は多分、クラスでやられていることが多いと認識しています。タブレットでもきっと記録できると存じますけれども、まだ入ったばかりですので、どこまで実践できているかは確認しておりません。","id":"exchange-153"},{"speaker":"本多委員","kind":"質問・要望","question":"この点に対する対応、対策、教育方法について教えてほしいと求めました。そういう暗唱とかをされているのが４校ということなので、必要なのかなと思っているのですが、その点について説明を求めました。","respondent":"工藤指導課長","answer":"いわゆるスマホ脳等の様々な心配に対する対応です。特に自分の考えをまとめ、自分の言葉で説明し発表する、いわゆる暗唱も含めてです。","id":"exchange-154"},{"speaker":"本多委員","kind":"質問","question":"それで、そのグローバルな視点について学ぶ機会がなくなってしまうのかどうなのかと思いまして、その点を教えてください。２０１９年より設けてスタートしておりますが、２０２０年は、カカオに触れる取組みができたとのことです。","respondent":"工藤指導課長","answer":"現状は緊急事態宣言下ですので、オンラインによって実施しているというのが、今年度で言えば多いところではあります。この３月に入りまして感染状況が落ち着いているところですので、一部実地ということで、来ていただくことを予定している学校もあります。","id":"exchange-155"},{"speaker":"本多委員","kind":"質問","question":"それぞれの国の、ピーナッツでも何でも題材になるのではないかなと思って、質問いたしました。テーブルマナーとか、そういった実用的なことを教えていくのも大事なことかなと思うのですが、その視点はいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"女性から贈るのは日本だけというような、海外での慣習や取組みについては、日本と異なる場合も多いと認識しています。委員ご例示のバレンタインデーを含め、発展的に他国の生活について自らの考えを持つことができるような指導を、継続してまいりたいと考えております。","id":"exchange-156"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"令和２年度予算の測量実施校は城南第二小学校、令和３年度予算では基本設計が城南第二小学校だけで、そのあたりの経緯はどうでしょうか。その場合は各学校でどのように対応されているのか尋ねました。","respondent":"有馬庶務課長、工藤指導課長","answer":"結果としては、鈴ヶ森小学校につきましても、引き続き内部でボリューム検討等をしていきたいと考えております。もう１点、念のため試掘調査を行う経費ということで、計上させていただいたものです。 クロス分析を予定していましたけれども、予定どおりに行われた場合は、それらの分析をしていこうと考えているところです。例年でいえば、夏季休業で分析をして、夏季休業後にはホームページにアップする予定です。","id":"exchange-157"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ところで、特別支援教室の教員の休職については、手当が行われているのでしょうか。あるいは産休代替教員の確保、病休代替教員の確保の仕組みは、都と一緒になっているのか尋ねました。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"区のほうで代替教員等の配置、また、見つからない場合は講師ということで対応するところです。加えまして、特別支援学級、また特別支援教室もありますけれども、そういったところも講師で対応しています。 いじめの条例等ですが、これは就学前の方も、公立の幼稚園ではないお子様もいらっしゃいますので、こちらで研究していきたいと考えています。","id":"exchange-158"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"特別支援教室のほうは手当が都のほうから来ないで、いるメンバーの中で、いろいろな学校を回っていくというようなことはないのでしょうか。都教委から来ているリストを使えるように、ぜひ都に働きかけていただきたいのですが、その点はいかがか尋ねました。","respondent":"工藤指導課長","answer":"ご指摘いただきましたように、特別支援教室で休職等が出た場合は、やはりそれまでにいる教員の中で、分担校を増やすなどして対応しています。区独自で進めておるところですので、東京都がありますけれども、区のほうで尽力して進めていきたいと考えています。","id":"exchange-159"},{"speaker":"大倉委員","kind":"提案","question":"３７５ページ、第四日野小学校改築、３５１ページ、クラブ・部活動指導員経費、３６５ページ、学校ＩＣＴ活用経費を伺います。現在の部活動指導員で結構なのですが、どのような経緯でなっている方が多いのでしょうか、説明を求めました。","respondent":"小林学校施設担当課長、工藤指導課長、矢部教育総合支援センター長","answer":"移植についてはかなり難しいという答えが出たので、ではどうしようかという検討を行いまして、その芽を接ぎ木できないかと。… 私どもで、タブレットの配布を今開始していますが、やはり学習で活用するというのを前提として、配布しています。家庭の連絡を含め… 今後、１５校全部の配置を目指して進めてまいりたいと考えております。タブレットの相談窓口については２つほどご紹介させていただいたとおりですが…","id":"exchange-160"},{"speaker":"大倉委員","kind":"質問・要望","question":"１５校全部にということで、さらに進めていってほしいと求めましたし、ぜひよろしくお願いいたします。新しい気づきとかもできますし、学習指導の質の向上にもなっていくのかなと思いますので、ログについてどのようにお考えか尋ねました。","respondent":"工藤指導課長","answer":"委員ご指摘のログの部分でありますが、効果検証につきましては、令和３年度にそういった効果検証を行う委員会を立ち上げて、ログも含めて効果の検証を行う予定です。","id":"exchange-161"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は３５２ページ、教育指導費についてお聞きしたいと思います。この学校にはどの程度の学力の子が何人いるのか、そういうことをしっかりと把握するべきだと思うのですが、ご見解を説明を求めました。","respondent":"工藤指導課長","answer":"その中で私どもは、区全体の集計を行う際に、各学校の状況も同時に把握をしています。その各学校に在籍する児童・生徒の学力の状況等を把握しながら、授業改善に活かしていく、そういった状況を私どもも同時に把握しています。","id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"個々人の、例えばこのぐらいの学力のレベルの子はこの学校に何人ぐらいいるとか、そういうことを各学校で管理されていた。では、今は、教育委員会もしっかりと把握しているということでよろしいか尋ねました。","respondent":"工藤指導課長","answer":"今年度はコロナ禍で一斉の実施がなかったものですから、その集計等の公表は見送ってありますけれども、各校の状況は把握をしています。Ｄの４つの層に何名ぐらいいるのかというのを、Ｄ層、Ｃ層の改善が見られるなどの報告をいただいているところです。","id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"例えば２クラスで別々に習熟度別のクラスをつくっても、それは、なかなか指導というのは難しいではないですか。そういうのはどういうふうに底上げしようとしてやっているのか尋ねました。","respondent":"工藤指導課長","answer":"確かに算数、数学におきましては、例えば少人数指導、習熟度別の指導を行ってあります。授業以外の場面でも、補充学習が必要な場合は、各学校で補習、また品川地域未来塾で確実に定着を図るような取組みも行ってあります。","id":"exchange-164"},{"speaker":"須貝委員","kind":"意見","question":"学校の勉強がよく分からない子や、学校より進んだ内容や難しい内容を学習塾で学んでいる子が、それぞれ全体の３割ぐらいいるようです。そのように大きなものになっていると思うのですが、その辺についてご見解を説明を求めました。","respondent":"工藤指導課長","answer":"そういった様々な取組みもありますけれど、私どもは、やはり学校教育の中でしっかりと力をつけていきたい。そのために、教職員含めて、努めているところです。","id":"exchange-165"},{"speaker":"須貝委員","kind":"質問","question":"それがこれだけ、６割、７割の子が学習塾に行かざるを得ないということは、やはりそこに何か問題があるのではないでしょうか。何が問題なのか、私には分からないのですが、その辺についてのご反省というかご見解というか、その辺について何か見解がありましたら説明を求めました。","respondent":"工藤指導課長","answer":"私どもは学校教育の中で、しっかりと力を育むべきところを進めているところです。そこでこそ学べるものをしっかりと教育していく、この品川区で一貫教育を進めていくです。","id":"exchange-166"},{"speaker":"須貝委員","kind":"質問","question":"もう一度お聞きします。その保護者の方がおっしゃっていたように、今の学校では進路指導ができないということですか、説明を求めました。","respondent":"工藤指導課長","answer":"私立の学校についても、教職員がデータであるとか資料をしっかりと把握し、それで進路指導を十分に行っているところです。予定にない高等学校が上がった場合であっても、その時にある手元の資料で十分な説明をし、真摯に向き合って対応しています。","id":"exchange-167"},{"speaker":"須貝委員","kind":"質問","question":"それとも、やれると言うなら、どこにその資料があるのですか。何が根拠で、あなたはこの学校に合格できる可能性が高いと言えるのか尋ねました。","respondent":"工藤指導課長","answer":"進路指導のお尋ねですけれども、私どもは、合格可能性を伝えることを、９年生時点の三者面談と捉えているわけではございません。入試相談等を私立の高校と中学校、義務教育学校の教員が行いますので、そういった資料を基にしながらお話をしています。","id":"exchange-168"},{"speaker":"須貝委員","kind":"質問","question":"親御さんも一緒に来て、できればここへ向かいたいのだと、受験をしたいのだという気持ち、それを受け止めるのが学校の対応ではないですか。それが何もなかったら、何もできないではないか尋ねました。","respondent":"工藤指導課長","answer":"あるいは８年生、７年生から、そういった体制で前向きな面談をしています。そういった進路変更をする場合がありますけれども、変更した場合であっても、三者面談等を行っているです。","id":"exchange-169"},{"speaker":"須貝委員","kind":"質問","question":"それが今、おっしゃっていることは違うから、そんなことがまかり通るのでしょうか。データが先ではないか尋ねました。","respondent":"工藤指導課長","answer":"データ等というお話ですが、またその学校でのそれまでの実績でありますとか、そういうのを勘案しているものです。それが間違いかどうかというのは、私のほうで今、判断することはできないところです。","id":"exchange-170"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり子どもたちは人が育てる、教員が育てるのではないですか。それで、何とか品川区に教員の人事権を持ってこられないか尋ねました。","respondent":"工藤指導課長","answer":"委員ご指摘のように、制度上３年で異動する教員もいれば、通常、原則として言われている６年の年限を超えて残りたいという教員も、もちろんおります。ただ、その辺の制度につきましては、東京都に従う中で、私どもは教員の育成をしっかりと図っているところです。","id":"exchange-171"},{"speaker":"須貝委員","kind":"質問・要望","question":"それが私は大事なことだと思います。ぜひ人事権を取ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-172"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私は、３５２ページの教育指導費から、性教育について伺いたいと思います。遅れた性教育をぜひ前進させていただきたいと思うのですけれども、そうでなければ子どもを守ることはできないと思いますけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"性に関する正しい理解と、適切に行動を取れるようにすることという性指導の目的に基づいて、指導をしています。ここに変更はございません。","id":"exchange-173"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"前回の質問で答えていただいているのですけれども、国連からも勧告を受けるような状況では守れないという立場に立っていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"状況はこちらのほうでよく理解して、国の方針に基づき、注視して、進めてまいります。","id":"exchange-174"},{"speaker":"石田（ち）委員","kind":"質問","question":"何がよくて、なぜ駄目なのか、子どもの心と体の変化に合わせて教えることが大切です。区は、性教育は人権との立場でしょうか、伺います。","respondent":"矢部教育総合支援センター長","answer":"委員ご指摘のユネスコの包括的性教育には、８つの視点が示されております。人権にとても関わるところですので、人権教育の１つと考えております。","id":"exchange-175"},{"speaker":"石田（ち）委員","kind":"質問","question":"なぜ中学校で性交渉について教えないのか、伺います。おかしいと思わないのか、伺います。","respondent":"矢部教育総合支援センター長","answer":"なぜかというお問い合わせですが、以前もお話しさせていただきましたが、中学校の学習指導要領に、妊娠や出産が可能となるような成熟が始まるという観点から、受精、妊娠までを取扱うものとし、妊娠の経過は取扱わないものとするという示しがありますので、これに準じたものです。","id":"exchange-176"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"中学校で性交渉を教えない、受精とか妊娠については教えるのに、その経過を全く教えないというのはなぜなのでしょうか。歯止め規定をなくすように国に求めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"外国の事情ですとか成果というのは、私どもも存じております。一人ひとりのお子様や保護者についても考え方は違いますし、現状、日本国につきましてはこの学習指導要領に準じて指導しています。","id":"exchange-177"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、教育の場から包括的性教育、科学的に、子どもたちの未来を守るために、人権として学ぶということが必要だと言われているわけです。本当にこの性交渉が淫らな行為、不純だと言っているのと同じではないでしょうか、伺います。","respondent":"矢部教育総合支援センター長","answer":"性教育について、人権教育に関わるものだということは否定しませんので、そのとおりだと存じます。国の有識者会議でも、あくまでも日本中がよりどころとしている学習指導要領の方針を我々は踏まえて、指導をしていきたいと考えています。","id":"exchange-178"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国がそうだからうちもそうだではなくて、やはりこの遅れた状況を、ぜひ現場から告発してほしいと思うのです。ぜひトイレに生理用品を置いてほしいと求めましたけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"生理用品の件につきましては、答弁が重複しますが、区でできることを検討していきたいです。","id":"exchange-179"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ポジティブに教えていくこの包括的性教育を進めていただきたいですし、そして人権であるということを基本に、改めて考え直していただきたい。そして、包括的性教育の立場に立って、品川区の今の立場の改善を求めたいと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"私が小さな頃よりもはるかに今は理解が進んでいると考えておりますので、やはり少し時間がかかるというふうには理解しています。１つの事実を取って進めるということではなくて、全体的に、教科であれば横断的に進めていくことが重要だと考えています。","id":"exchange-180"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"５歳から、子どもたちは自分のことも相手のことも大事だと、命なのだと認識することができます。ですので、日本でも早い段階から、包括的性教育の立場で実施してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-181"},{"speaker":"大沢委員","kind":"質問","question":"３５１ページの就学事務費、そして３５３ページ、先生方、職員の件、それと３５５ページ、入試について、３点伺います。そこら辺のところを、お分かりになる範囲で結構ですので説明を求めました。","respondent":"篠田学務課長","answer":"１０月１日現在の住民基本台帳登録数が８７名であったところ、申請等につきましては７１名の方が入学の申請をしてきたという状況です。順次進んでおりますので、若干、通学区域の中から外に出られている方が多いのかなという形で捉えているところです。","id":"exchange-182"},{"speaker":"大沢委員","kind":"質問・要望","question":"８７名、後地小学校へ行けるということですけれども、あの距離からかなり近い人ですと、あの周辺は交通の量が非常に多く、過日、後地の交差点でも事故が起こったところで、そこら辺、通学路についての検討はもうされていると思いますけれども、通学路についての検討状況を教えていただきたい。","respondent":"有馬庶務課長","answer":"まだ学校に直接確認はしてございませんけれども、学区が変わるということで、通学区域の見直しは、当然学校のほうで行っていると考えているところです。","id":"exchange-183"},{"speaker":"大沢委員","kind":"質問・要望","question":"これでこの質問は終わります。３５５ページ、その旨の質問をさせていただきましたけれども、それを振り返ってみてどのような状況であったのかを説明を求めました。","respondent":"工藤指導課長","answer":"本区の９年生の指導状況ですが、指導内容につきましては、十分学習が進んでいたところです。本区の９年生の学習状況は、一定程度これまでどおりの入試の対応が、各学校ともにできていたと把握しています。","id":"exchange-184"},{"speaker":"大沢委員","kind":"質問・要望","question":"１０月、子どもさんたちも不安になっている、塾もどういうふうに処していいか分からない部分がありました。あるいは、身分が東京都でありますから東京都のほうに行かれるのか、そこのところを教えていただきたい。","respondent":"工藤指導課長","answer":"副校長を合わせた管理職が職員の状況を把握して、万が一トラブルがあった場合には、そういったものを解決していくと思います。例えば全体の服務的な処分等になりますと、東京都教育委員会で行うことになりますので、そういった流れがあろうかと存じております。","id":"exchange-185"},{"speaker":"大沢委員","kind":"質問","question":"そこで第三者が入った場合、例えば訴訟沙汰が起きた場合はどのように対処されているのか、説明を求めました。","respondent":"工藤指導課長","answer":"仮に訴訟があった場合の対応ですが、その訴状も、例えば個人が訴えられる場合、また自治体が訴えられる場合、それぞれあろうかと思いますけれども、教育委員会におります訟務員にも相談しながら、対応しています。","id":"exchange-186"},{"speaker":"大沢委員","kind":"質問","question":"要は情報を出す場合に、４つか５つぐらいの要件があったと思います。個人に関わるものとか様々あると思うのですが、そこの情報の出し方について、どのような方法、どのような形で情報を出されているのか説明を求めました。","respondent":"工藤指導課長","answer":"例えば教職員の服務的な処分事例等ですが、それにつきましては東京都教育委員会が処分を公表するところです。東京都がプレス発表を行っておりますが、そういったものに関して区教育委員会としてプレスをするということは、処分事例についてはないです。","id":"exchange-187"},{"speaker":"大沢委員","kind":"質問","question":"東京都のほうですけれども、やはり知り得た情報を出す判断、出さない判断、有益な情報、それと、また区にとって不利益な情報、情報の出し方にもいろいろとあるわけですけれども、そこら辺の判断基準はどのようにお考えか尋ねました。","respondent":"工藤指導課長","answer":"マスコミ対応等を私どもが行う場合は、特に個人情報等を一番慎重に取扱うべきだと思いますので、その事案によって検討するものであると認識しています。","id":"exchange-188"},{"speaker":"大沢委員","kind":"質問・要望","question":"別の委員会でも少しこれを質問させていただきましたけれども、先生方、現場に不利益がないような情報の提出をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-189"},{"speaker":"たけうち委員","kind":"質問","question":"ばらばらではないでしょうかということを少し指摘させていただいて、きれいになっていまして、必要事項が項目としては統一されていると。そういうことについて、しっかりとそういうところの研修というか、どういうふうにやられているのかというのをお聞きしたいと思います。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"例えば今般の３.１１の話などは、「３.１１を忘れない」という東京都から出ている資料を使って説明しています。この３年間では、人権教育については十分理解して進めなくてはならないと考えておりますので… 私からは、学校のホームページについてお答えいたします。そうすることによりまして、校務の効率化も図れるだろうということで、現在の形になっているものです。","id":"exchange-190"},{"speaker":"たけうち委員","kind":"質問・要望","question":"１つの例で言うと、もしかするとそれは何か違うのかなという、何かそういうことなのですか。その辺のことも含めてぜひご指導をお願いしたいと……、やっていただきたいと思うのですが、もう一言お願いします。","respondent":"矢部教育総合支援センター長","answer":"そのとおり、人権教育に気をつけてまいりたいと思いますし、教員の苦労も分かっているつもりですので、校長会等でそういった配慮も気をつけていくようにと、併せてお話ししていきたいと思います。","id":"exchange-191"},{"speaker":"石田（秀）委員","kind":"質問","question":"緊急事態宣言が延長されましたけれども、当初３６校だったと思いますが、何校で実施できたのかを伺います。学校の教員の長期休暇も増加していると伺っています。","respondent":"有馬庶務課長、工藤指導課長","answer":"残念ながら１月に緊急事態宣言が発出され、これから行く学校も４校程度あり、それらを含めて２９校が実施という状況になっております。それ以外にも、学校独自でというところでは、それぞれの学校が実施している状況です。 それがやはりストレス解消の１つのポイントにもなろうかと思っていますので、継続していく、この緊急事態宣言下であっても気をつけて行っています。笑顔を交わしながら学んでいくことというのは、非常に大切であると思いますし…","id":"exchange-192"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"少しつらさが入ってもいいのかなと考えていますけれども、こういうことをぜひ増やしてほしいと考えています。今、ぎりぎりまで待って検討してほしいと思ったりもしているのですが、この３点をぜひ教えてほしいと求めました。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"先ほど指導課長が申しましたけれども、子どもたちと一緒に学び舎で楽しんでいるということが、１つの思い出になるのかなと考えております。お弁当を作らなくてよかったというのも聞いておりますので、様々な保護者や地域との間で… 本当に行ってよかった、すごい思い出になった、私が読んで本当にうれしくなるような感想文を児童・生徒からいただいております。引率した先生からも、本当に連れて行ってよかったという意見をたくさんいただいておりますので…","id":"exchange-193"},{"speaker":"石田（秀）委員","kind":"質問","question":"教員が一体となって、品川区に住んでいてよかったと思われる教育が実行できると、私は信じております。最後にその決意だけを伺って終わりにします。","respondent":"工藤指導課長","answer":"品川区において進めている一貫教育、また品川区立学校教育要領に基づいた教育は、日本、また東京の中で随一というふうに、私どもは自負しています。その教職員等を指導しつつ、また地域の方とともにコミュニティ・スクールを進めつつ、子どもたちを育んでいきたいと考えておりま…","id":"exchange-194"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/309623?Template=document&Id=1138#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":131064,"voices":436}},{"id":"r03-20210317-3","meetingId":"r03-c-budget","date":"2021年3月17日","dateIso":"2021-03-17","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を129件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西村副委員長","kind":"質問・要望","question":"「区長の英断に感謝する」、「生活資金として大切に使っていく」など、感謝の声が８割を超えると伺い、大変感動しております。子どもたちには、プロ・アマを問わずスポーツの定期的な観戦ツアーを実施してほしいと求めましたが、いかがか尋ねました。","respondent":"山崎文化スポーツ振興部長","answer":"区応援３競技につきましては、ブラインドサッカーの体験会や観戦ツアーを実施いたしまして、機運醸成に努めてまいりました。区ではただいまスポーツ推進計画を策定し、この４月から１０年間の、今後の区のスポーツ推進の方針ということで定めてまいります。","id":"exchange-001"},{"speaker":"西村副委員長","kind":"質問・要望","question":"ビーチバレーボールに関しましては、会派からも要望しています品川オープンの継続を、ぜひともご検討いただきたいと考えています。この予算をしっかりとつけていただきまして、子どもたちの記憶に残る機会を品川区から提供することはできないか尋ねました。","respondent":"山崎文化スポーツ振興部長","answer":"それから一般区民の方を対象にした教室を開くといった、ターゲットを幅広く捉えてしっかりと普及を、より一層推進する取組みを考えているところです。あるいはビーチバレーボールそのものの大会の実施についても…","id":"exchange-002"},{"speaker":"西村副委員長","kind":"質問","question":"３点伺います。担当係長が設置されると伺っておりますが、マイナンバーカードの普及に向けてどのように取組みを強化していくのか、説明を求めました。","respondent":"堀越企画部長、久保田地域振興部長","answer":"ただ一方で、やはり情報格差が生じないよう、ＩＣＴ化の推進と並行して対応していく必要があると認識しております。環境の整備に努めていくのも区の役割ですので、高齢者地域支援課で予定しているスマホ教室など… その荏原第一地域センターでも、マイナンバーカードの業務を開始する予定です。今後も受付施設のさらなる拡大などを検討いたしまして、カードの普及・啓発に努めてまいります。","id":"exchange-003"},{"speaker":"西村副委員長","kind":"質問・要望","question":"こちらも既に進めていただいているということですけれども、具体的にどのように進めていくのか伺いまして、少しイメージができてまいりました。例えば各地域センターで受付をしてほしいというような区民の方の声もありまして、どのように計画されていらっしゃるのか、伺えればと思います。","respondent":"堀越企画部長、久保田地域振興部長","answer":"地方税のシステムの標準仕様書が国から示される予定となっていますので、その内容の確認を行いつつ、関係課と検討していく予定です。その際、例えばクラウド関係のシステムを使うといった課題についても整理していきたいと… 他の地域センターでもとのお尋ねですが、今後、他の地域センターに拡大していくかどうかについては検討を進めていきたいと考えているところです。その計画に見合った…","id":"exchange-004"},{"speaker":"西村副委員長","kind":"質問","question":"続けてオンライン申請について伺います。現在、区が行っている行政手続き、例えば保育、住民票、助成金、出産手続きなど、庁内に約８００種あると伺っております。","respondent":"堀越企画部長","answer":"オンライン申請のニーズが非常に高まっていると考えてございまして、区としてもスピード感を持って対応していかなければならないと考えています。オンライン化の方針やロードマップ的なものについて準備を進めまして…","id":"exchange-005"},{"speaker":"西村副委員長","kind":"質問・要望","question":"そして子育て支援センターについて、これまでも何度かお伺いしておりますが、改めて役割の違いを教えてください。最後に、以前、名称が似ているために分かりづらく、相談機関の名称の変更を要望しましたが、検討状況を説明を求めました。","respondent":"柏原子ども未来部長","answer":"子ども家庭支援センターにつきましては、令和２年度、子どもに関する様々な相談に対応するといったところです。名称については検討していますが、児童相談所が設置された際に、検討しているといった状況です。","id":"exchange-006"},{"speaker":"西村副委員長","kind":"質問・要望","question":"もし１か所ということであれば、品川区の真ん中にある区役所にあれば非常に便利ではないでしょうか。もう一度ご答弁をお願いいたします。","respondent":"柏原子ども未来部長","answer":"我々としても、どういったところに相談したらいいのか、そういったところを分かりやすくするというのが非常に大切なことだと思ってあります。ゆくゆくは児童相談所を設置といったところもありますので、そういった体制整備をきちんと行っていきたいと思ってあります。","id":"exchange-007"},{"speaker":"西村副委員長","kind":"質問・要望","question":"３部１０課の連絡会を実施し、来年度には３つの機能をさらに掘り下げ、有効的な包括支援策を整備していくと伺いました。３点伺ってまいります。","respondent":"伊崎福祉部長","answer":"その中で、教育、医療、警察など、課題解決に必要だと考えられる多くの機関との連携・協力体制について検討を進めていく予定でおります。さらに、必要な人材についても、今後の検討の中で議論を進めてまいります。","id":"exchange-008"},{"speaker":"西村副委員長","kind":"意見","question":"担当する職員を配置して取り組んでいただくことが、品川区で生まれてから高齢になるまでを支援できる地域包括ケアになると考えます。最後に、設置についてお考えを説明を求めました。","respondent":"堀越企画部長","answer":"重層的支援体制の構築は地域包括の部分です。全庁的な対応が必要と考えていますので、いろいろな会議体の設置や、しっかりと取り組んでまいりたいと考えているところです。","id":"exchange-009"},{"speaker":"西村副委員長","kind":"質問","question":"引き続き、どうぞよろしくお願いいたします。私の質問は以上で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問","question":"保健所と医師会とで毎週、対策会議が行われていますが、この人員不足について、どう把握し、どう対応されているのでしょうか。区として、どう把握し、どう考えていくのか尋ねました。","respondent":"福内品川区保健所長","answer":"国や都と共に有効な支援策を講じることで、十分な人員体制の下、新型コロナウイルス感染症の対応を確実なものにしていきたいと考えております。医療につきましては広域であることから、今後も医療関係者のご意見を伺いながら、有効な支援策について検討してまいります。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問・要望","question":"広域的なことですから、さらに東京都に働きかける、あとはクイックプラン、期間限定など、その点に着眼してほしいと求めました。若者に対する就業支援を説明を求めました。","respondent":"福内健康推進部長、柏原子ども未来部長","answer":"先ほどの医療人材の確保に関する質問ですが、都の保健医療計画に基づく取組みにより、人材が適切に確保されるよう、区としても協力してまいります。状況に応じまして、広域的な対応を、区としても要請していきたいと考えております。 新たに子ども・若者支援についての事業を展開するところですが、１つは、居場所づくりということでフリースペース事業を行ってまいりました。若者に対する就業支援ですけれども、１回５０分程度ですけれども…","id":"exchange-012"},{"speaker":"本多委員","kind":"意見","question":"大学生のおよそ８３％がアルバイトをしていたのですが、それもままならない状況です。しかし、狭き門、氷河期などの点をどのように捉えていくのか、区としての方向性を説明を求めました。","respondent":"柏原子ども未来部長","answer":"その支援策については、より多様な視点といいますか、そういったところが必要であるというのは認識してきているところです。広域的な動きもありますので、そういったところも十分に見ながら、区としての具体策というところについて検討してまいりたいと思ってあります。","id":"exchange-013"},{"speaker":"本多委員","kind":"質問・要望","question":"次に、２つ目の項目、ふるさと納税の流出対策について伺います。特別区長会として、これまで国へ制度の見直しを求め、様々なご尽力を頂きました。","respondent":"品川財政課長","answer":"したがいまして、区が独自に発行するということができない状況です。他の自治体の事例も参考にしながら、創意工夫を凝らしまして、歳入増に努めてまいりたいと考えています。","id":"exchange-014"},{"speaker":"本多委員","kind":"質問・要望","question":"法改正を求めるなど、この質問をしておりますので、その点だけ教えてください。一昨年の令和元年１１月１３日、文化プログラムの調査項目で、品川区で最も歴史のある品川寺に伺いました。","respondent":"品川財政課長、山崎文化スポーツ振興部長","answer":"二の矢、三の矢ですが、今後も２３区で連携して、引き続き国等への要望を続けていきたいと思います。新たな発想という点でも、いろいろ創意工夫を含めながら、今後も考えていきたいと考えています。 こうした映像の力をもって品川区の魅力を発信していくことは、非常に効果的な手法ということで、区としても認識するところです。動画配信につきましては、引き続き様々、連携に努めまして…","id":"exchange-015"},{"speaker":"本多委員","kind":"質問・要望","question":"空海聖人より水月観音を授かった品川氏が、６００年近くの長きにわたり領主だったことを取り上げて、品川区の魅力発信をしてほしいと求めました。流出対策を中心に質問いたしましたが、区への寄附の一助となりますよう、しながわ水族館に着眼する点について説明を求めました。","respondent":"山崎文化スポーツ振興部長、榎本総務部長","answer":"既に昭和４７年に教育委員会で編さんしました『品川の歴史シリーズ地名編』というようなものもあります。観光あるいはシティプロモーションで参考にさせていただいて、取り組んでまいれるところで頑張ってまいりたいと思うところです。 その後、オリンピック・パラリンピックの区応援３競技をモチーフにしたものを、今現在も継続しています。それから、ほかに、しながわ水族館の年間パスポート等も検討しておりまして、そういうものを返礼品にすることで…","id":"exchange-016"},{"speaker":"本多委員","kind":"質問・要望","question":"では、３番目の項目、町会・自治会支援について伺います。区民・事業者に対して町会・自治会の活動への参加協力を求めるなど、この５年間、条例制定の効果や理解などについて説明を求めました。","respondent":"久保田地域振興部長","answer":"区民全体への周知については、知らないという方が７割いるというところが課題ですので、一層の周知に努めてまいりたいと考えているところです。いろいろな課題を捉え、研究していきたいと考えているところでございまして、引き続き積極的に進めていきたいと考えているところです。","id":"exchange-017","title":"町会・自治会支援"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひ、１３地区対抗のスポーツ大会を品川区主催で行ってほしいと求めました。","respondent":"久保田地域振興部長","answer":"次に、地域の運動会の状況ですが、１３地区のうち７つの地区で運動会を実施しているという状況です。そして、１３地区の町会・自治会の協力等も必要というところがありますので、実施に向けての調査・研究を進めていきたいと考えています。","id":"exchange-018"},{"speaker":"つる副委員長","kind":"質問","question":"初めに、新型コロナウイルス感染症対策についてお尋ねいたします。ワクチン接種等に関する現状と体制整備、情報提供について伺います。","respondent":"秋山保健整備担当部長","answer":"対象を絞って接種を開始するよう検討を進めておりまして、４月２６日の週以降に、高齢者施設より接種を開始する方向で現在調整を進めております。３月１日号の広報しながわ、チャットボットでも対応しておりますし、新しい情報が載るように努めているところです。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"質問・要望","question":"厚生労働省から、障害特性に応じた合理的配慮の提供を求めています。接種時等における会場などでの合理的配慮等に加え、接種に際して公的な福祉サービスによる支援を円滑・柔軟に受けられることが求められます。","respondent":"秋山保健整備担当部長","answer":"接種に関わる支援策として、接種会場において同行援護や移動支援など福祉サービスによる支援を、対応について配慮していきたいと考えております。こうした支援策について、接種の通知等の際に周知をしてまいりたいと考えております。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"提案","question":"品川区では、私が提案し、２０１６年３月から、行政サービスの取組みとしては全国初のＹｏｕＴｕｂｅ動画によるバリアフリー情報を提供しています。アナログ・デジタル双方の情報発信の専門家の採用やインフルエンサー等のご協力など…","respondent":"堀越企画部長","answer":"それから、ご提案のありました若い世代の方への広報ですが、専門家の活用なども検討していきたいと思ってあります。接種会場の、障害をお持ちの方も安心して来ていただけると思いますので、大変有効な手段の一つとして検討させていただきたいと考えています。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問・要望","question":"紙の商品券発行にも支援するよう求め、紙の商品券も認めるとの答弁を引き出し、事業の拡充を図りました。事業周知や、発行の時期や期間を整理し、都の予算を活用した商品券の発行を求めます。","respondent":"久保田地域振興部長","answer":"こうしたことに対応するためにも、個店のデジタル化を効果的に進めていく手法を検討していかなければならないと認識しています。こうした点を踏まえまして、引き続き品川区商店街連合会と協議しながら検討していきたいと考えているところです。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"質問・要望","question":"款別審査の会派の質疑で確認しましたが、パソコン・タブレット教室に加え、次年度はスマホ教室も新規事業として実施する予定です。教室内容の工夫や、都の補助事業も活用し、実施箇所の拡大も検討してはいかがか尋ねました。","respondent":"伊崎福祉部長","answer":"来年度は、ご紹介いただいたとおり、高齢者向けのスマホ教室を新たに行う予定としております。まだ詳細は示されておりませんが、高齢者がデジタルに親しみを持てる教室内容の工夫や実施場所の拡大等を検討していきたいと考えております。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"提案","question":"昨年の第３回定例会の一般質問で、多胎児家庭をはじめとする子育て相談などの、オンラインの活用を提案しました。コロナ禍の中で窓口まで伺う手続きには困難を感じる」との声を受け、Ｚｏｏｍなどの画面共有などで対応するべきと、保育課に求めました。","respondent":"柏原子ども未来部長","answer":"そうしたところの今後の拡大の考え方ですけれども、オンライン、こちらについては導入に向けての検討を進めていきたいと思ってあります。添付していただく書類、そうした部分を整理しながら、この部分についても実現に向けた検討を進めていきたいと思ってあります。","id":"exchange-024"},{"speaker":"つる副委員長","kind":"質問・要望","question":"昨年の第３回定例会の一般質問で、コロナに関連する差別・偏見等の防止のために、人権啓発動画の制作を教育委員会に求めました。品川区としても、コロナに関わる差別・偏見を防止する取組みが必要だと思いますが、ご所見を説明を求めました。","respondent":"齋藤教育次長","answer":"次に、ワクチン接種により集団免疫を獲得することがコロナ終息への近道であり、接種を勧奨する必要性はあると認識しております。今後、接種は任意であることを区民の皆様に丁寧に説明いたします。","id":"exchange-025"},{"speaker":"つる副委員長","kind":"提案","question":"２０１３年の決算特別委員会で紹介・提案し、２０１５年の予算特別委員会で提案したものとして、利用者の喜びの声とともに高く評価いたします。利用者の声に応じて再度の研修を実施し、産後ドゥーラとしての適性を確認するなど…","respondent":"柏原子ども未来部長","answer":"利用しやすいサービスにつながると考えてございまして、２２人ということで助成を計上していますが、継続した形で続けられればと思ってあります。区民の方が選択しやすい環境を整えるといったところで、こういったところが活躍の場につながるのではないかと考えているところです。","id":"exchange-026"},{"speaker":"つる副委員長","kind":"質問・要望","question":"来年度、多胎児家庭を含む産後ドゥーラの利用助成もさらに大きく拡充されます。拡充内容と併せてお知らせいただくとともに、予約や助成申請に際しては改善など工夫が求められるところですが、ご所見を説明を求めました。","respondent":"柏原子ども未来部長","answer":"１時間当たりでは７００円分の自己負担が軽減されるですが、先ほど申しましたように、負担についても大きく軽減できるのではないかと見込んです。具体的なところを幾つか検討していますが、そういったところが具体的にきちんと周知できるような形で、今検討を進めているところで…","id":"exchange-027"},{"speaker":"つる副委員長","kind":"質問・要望","question":"昨年の第３回定例会の一般質問で、同事業に積極的に取り組むことを求めました。同事業の検討に併せて、国の予算を活用した自殺対策の強化、孤独・孤立を担当する部署の創設を求めますが、併せてご所見を説明を求めました。","respondent":"伊崎福祉部長、堀越企画部長","answer":"モデル実施自治体として整備例を５パターン提示し、既存機関に併設して実施している愛知県豊田市や、情報収集に努めてまいりたいと考えております。令和３年度を検討期間と位置づけて、これはモデル実施となる可能性もありますけれども… 今、福祉部長からも答弁がありましたけれども、コロナ禍において浮き彫りになったこの課題にどう対応していくかというのが必要なことと考えています。国の動きも見ながら、関係部署と一層連携して…","id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問","question":"これを願って、私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問","question":"質問の１点目は、品川区強靭化地域計画および品川区災害廃棄物処理計画について伺います。今後決定される廃棄物の仮置き場の場所や使用方法等の、区民への周知徹底を平常時に図る必要があると考えますが、ご所見を伺います。","respondent":"滝澤災害対策担当部長","answer":"品川区の特性に応じた強靱化の目標設定、脆弱性の分析・評価、対応方策の検討と優先順位などについて具体化いたします。技術的支援や各種調整を行い、計画の具体化に伴い、それぞれの役割分担も明確にしてまいりたいと考えております。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点目は、新たな防災ラジオについて伺います。現機種を所持している前回購入者に対し、周知の徹底と割引購入制度の導入を要望しますが、いかがか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"避難情報などの緊急情報のみに限定するとともに、月に１度程度の定期的な、自動起動を確認できる試験電波の発信を考えております。販売におきましては、高齢者や障害者など避難行動要支援者と前回購入者に対し、割引制度を適用することも併せて周知してまいります。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"提案","question":"平成１９年の決算特別委員会で公明党の三上委員が初めて導入を提案して以来、浅野委員が導入の必要性を強く求めたことに対する答弁で。加えて、空き住戸を緊急避難先として活用することを可能にする協定の締結も要望しますが、ご所見を伺いますとの意見を述べました。","respondent":"滝澤災害対策担当部長","answer":"覚書締結後、同意が取れた住棟につきましては、区として緊急避難施設として指定してまいりたいと考えております。避難施設として利用時の被災者支援要領などを研究した後、協定の締結については検討してまいりたいと考えております。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問・要望","question":"４点目は、火災発生時の支援体制について伺います。災害時宿泊費助成事業、そして充実した内容の援護物資の交付を要望しますが、ご所見を伺います。","respondent":"滝澤災害対策担当部長","answer":"公共料金についての減免制度はありませんが、固定資産税や特別区民税などにつきましては、条件付での減免措置があります。緊急セット、この中にはタオルや歯ブラシセットも含まれております、この救援物資の有効活用による被災者支援を充実するよう検討してまいります。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"提案","question":"令和元年第３回定例会の一般質問で、品川区防災区民憲章の制定をご提案したところ、制定については長期的な視点で検討する」とのご答弁でした。東日本大震災から１０年を迎えた今だからこそ、防災区民憲章策定の検討着手の時期を明らかにしてほしいと求めましたが…","respondent":"滝澤災害対策担当部長","answer":"特に令和３年度は東日本大震災から１０年の年に当たることから、区としても自助・共助に係る啓発活動に力を入れてまいります。様々な施策や訓練、区民の自助・共助の意識が一定程度以上高まった段階で、防災区民憲章の制定について具体的に検討してまいりたいと考えております。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問の１点目は、町会・自治会の感染症対策の支援について伺います。総会シーズンに間に合うよう、いま一度、全ての町会・自治会へ、利用可能な補助金メニューの周知を要望しますが、ご所見を伺います。","respondent":"久保田地域振興部長","answer":"空気清浄機などの備品購入については、町会・自治会からの要望も多かったため、令和３年度からは補助対象といたします。そして、町会・自治会への周知につきましては、４月の町会長・自治会長会議において、感染防止対策などに利用可能な補助金等の説明を行う予定です。","id":"exchange-035","title":"町会・自治会支援"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点目は、後遺症対策について伺います。そして、今後増加すると思われる後遺症への相談対応も、保健所業務として明確に区民へお示しいただきたいと要望しますが、ご所見を伺います。","respondent":"福内品川区保健所長","answer":"区民の感染者数ですが、品川区保健所で対応した区民の感染者は、３月１５日までに３,７００人となっています。今後は、これまでの電話相談に加え、東京都が開設を予定している、都立病院等の後遺症に関する相談窓口も含め、区民に周知してまいります。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"基礎疾患の証明書を求めず、本人による自己申告ですが、予約段階や会場の予診等での申告・確認の手順を教えてください。ぜひ実現してほしいと求めましたが、区の見解と現在の協議状況を伺います。","respondent":"秋山保健整備担当部長","answer":"医師の予診がありますので、その時点で聞き取りを行い、接種の可否は最終的に予診を担当する医師の判断ということになります。かかりつけ医での接種に向けて、かかりつけ医の接種参加の意向の調査など、医師会を通じて各診療機関との協議を現在行っております。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問・要望","question":"次に、４点目は、国のワクチン接種記録システムについて伺います。区保有の接種台帳との関係、互換制、導入に関する品川区の現在の意向、想定される課題について説明を求めました。","respondent":"秋山保健整備担当部長","answer":"ワクチン接種記録システムの導入目的は、接種の円滑な支援のためであり、災害時における接種票の喪失に対応すること。区では、国の接種記録につきまして、区民の接種記録の正確な追跡ができることから大きなメリットがあると考えており、導入を進めてまいります。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問の１点目は、同施設の選定の過程について伺います。当初５年間であった指定管理期間が３年に短縮された具体的な理由を伺います。","respondent":"伊崎福祉部長","answer":"現在の指定管理期間が３年となった具体的な理由ですが、事業者ごとに専有部分の指定管理を行い、現在の形となりました。支援については高く評価されましたが、区の拠点施設として総合的・一体的な管理運営を担えるかどうかについて懸念があると判断されたものです。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"２点目は、指定管理者制度における選定情報の公開等について伺います。は区の直営にする等、一定の手続きを定めておく必要があると考えますが、ご所見を伺います。","respondent":"堀越企画部長","answer":"指定管理議案が否決された前例についてはございません。もし否決された場合の対応に関する規定についてのご質問ですけれども、再公募・業務委託の実施、その中で検討してまいりたいと考えています。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"具体的な評価指標および目標値の設定を選定基準項目へ追加すべきであると考えますが、ご所見を伺います。公の施設である以上、一定の期間ごとの公募と審査を行う必要があるのではないでしょうか」とお尋ねしたところ、具体的な検討内容を説明を求めました。","respondent":"堀越企画部長","answer":"次に、ＳＤＧｓに関してですが、こちらにつきましては、他自治体の実施状況や、その効果などについて研究してまいりたいと考えています。施設の設置目的から引き続き指定することが合理的と判断される場合においては、継続していますけれども…","id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３点目は、今後の障害者福祉について伺います。確実かつ早急に進めていただきたいのですが、相談後のフォロー体制のできる専門家を充てていただくよう要望しますが、ご所見を伺います。","respondent":"伊崎福祉部長","answer":"さらなる相談機能の強化や、障害の重度化や多様化に対応する専門的機能の強化が必要だということは、区としても認識はしております。事業者と協議をしながら進めるとともに、区全体の児童発達支援の体制についても検討を行い、整備を進めてまいりたいと考えております。","id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"身分の継続ができるよう、品川区も法人の間に積極的に入って丁寧にあっ旋してほしいと求めましたが、ご所見を伺います。障害者当事者、今後は民間事業者の数を積極的に増やしていただきたいと要望いたしますが、ご所見を伺います。","respondent":"伊崎福祉部長","answer":"勤務の継続を希望される職員の方が、次期指定管理者の職員として応募できるよう、機会の確保を図ってまいります。当事者やご家族の方が障害福祉サービスを選択できる機会を増やせるよう、引き続き民間事業者の増設に努めてまいります。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"第１回定例会の大沢委員の代表質問にもありましたけれども、ワクチン接種の現状についてお伺いいたします。区内の輸送体制や、接種会場において同様の事案が発生する可能性をゼロにするための区の取組みをお伺いいたします。","respondent":"秋山保健整備担当部長","answer":"今回、接種会場への輸送や配送についても、今まで以上に柔軟な対応が可能と考えております。不具合によるワクチンの廃棄等が発生しないように、設置に際しては電気容量を確認するとともに専用の配線とするよう、設置施設に徹底してまいります。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問","question":"次に、接種会場における通訳等の配置についてお伺いいたします。区内在住の外国人の方々も、ワクチンの接種については不安に感じておられると思いますけれども、どのように接種を促していくのか、お伺いいたします。","respondent":"秋山保健整備担当部長","answer":"外国人への対応ですが、コールセンターでは英語と中国語に対応し、接種に関する問い合わせや接種の予約の対応も英語・中国語にて行います。集団接種会場では、１３か国語対応の通訳タブレットの配備を検討しているところで…","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして、高齢者等の移動支援についてお伺いいたします。高齢者の接種会場への移動について、区として後押しする仕組みを検討してみたらいかがかと思いますが、ご見解をお伺いいたします。","respondent":"秋山保健整備担当部長","answer":"品川区は、委員お示しの自治体に比べまして総面積が小さく、区内の交通手段も発達しておりますが、高齢者の方の接種を進めていくためにどのような支援が必要なのかについては、現行のサービスの活用や他都市の状況の調査をしながら検討してまいります。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問","question":"建物のみの町会・自治会を除く区内１８８町会・自治会のうち、公園を持たないのは何町会・何自治会でしょうか。お伺いいたします。","respondent":"藤田防災まちづくり部長","answer":"お示しされました１８８の町会・自治会のうち、１５９の町会・自治会が公園を持ち、公園のない町会などは残り２９になるものです。公園用地の確保を最優先に努めるとともに、公園のない町会などに対してもこれからも積極的に用地の確保をしてまいりたいと考えています。","id":"exchange-047","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今回その一つが解消されることになったことは何よりであり、今後もできるだけ多くの町会・自治会で公園整備が進むことを要望いたします。住民からは主にどのような要望が出され、どのような点で案に反映していったのか、また案に対する区としての基本的な考えをお伺いいたします。","respondent":"藤田防災まちづくり部長","answer":"様々な防災施設の設置や、防災活動のできる広場、こうした意見については案の中に反映していったものです。区の基本的な考え方といたしましては、加えて地域住民にも配慮した公園というもので、案を取りまとめているところです。","id":"exchange-048","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問","question":"次に、公園のトイレ設置についてお伺いいたします。常設トイレの設置については賛否があったとお伺いしていますが、トイレ設置については今後どのようにお考えになっているのか、お伺いいたします。","respondent":"藤田防災まちづくり部長","answer":"トイレの設置に関しましては、委員ご指摘のとおり、様々な意見を頂いたところです。それから地域の環境などから、今回のケースでは、今回は設置について見送る考えとしたものです。","id":"exchange-049"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"町会の方々の声をお伺いしますと、このような複雑なゾーニング、そして避難所運営が本当にできるのか、不安の声もかなり聞かれます。本マニュアル作成から既に８か月が経過しますが、この間の区民への周知方法や周知状況についてお伺いいたします。","respondent":"滝澤災害対策担当部長","answer":"５２か所の区民避難所のうち４６か所が避難所連絡会議を開催しましたので、同マニュアルの説明を行い、内容について議論させていただきました。個別に３か所の避難所連絡会議でコロナ対応の避難所訓練を行っていただきましたので…","id":"exchange-050"},{"speaker":"高橋（伸）委員","kind":"質問","question":"避難所となる小・中学校の準備状況をお伺いしますと、追加的な準備を行っていない学校もあり、温度差があるようです。各避難所の準備状況の把握と、準備の具体化を促すことも重要と考えますが、ご見解をお伺いいたします。","respondent":"滝澤災害対策担当部長","answer":"取組みに温度差があることは事実でありまして、自助・共助の大切さについてさらなる啓発活動を実施していきたいと考えております。訓練を実施して明らかになった問題点や課題について、少しでも避難所ごとの温度差を少なくできるよう努めてまいりたいと考えております。","id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問","question":"最後に、避難所ごとの連絡会議や、避難所訓練への区職員の参加についてお伺いいたします。避難所ごとに決まっている担当職員の連絡会議や、避難訓練への参加の徹底についての見解をお伺いいたします。","respondent":"滝澤災害対策担当部長","answer":"区の情報伝達拠点や物資集積拠点としての運用実施をするとともに、平素は防災課の職員と共に、避難所連絡会議の運営支援を実施しております。災害時の連携強化に直接貢献することから、防災区民組織との顔の見える関係を構築するよう努めてまいりたいと思います。","id":"exchange-052"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本当に、地震・有事はいつ起こるか分からないので、ぜひとも連携を取っていただき、防災訓練のことも徹底してほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"松澤委員","kind":"質問","question":"令和３年度施政方針、長期基本計画における超長寿社会に対応する視点から、介護人材不足、認知症対策に対する取組みについて質問いたします。一般質問でもお聞きしましたが、介護離職者をいかになくしていくのか、これが一番大切なことだと思います。","respondent":"伊崎福祉部長","answer":"さらに今年度は、外国人職員の採用についての法人支援に着手するとともに、住宅支援事業も行う予定でおります。それが実現可能となりますように、引き続き効果的な人材の定着や確保の方策について検討し、支援を行ってまいります。","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問・要望","question":"一般質問では、品川ケア協議会で、介護の資格取得を行っていると答弁がありましたが、この品川ケア協議会とはどのような法人なのでしょうか。国の影響が大きいので、この場では、処遇改善加算制度をしっかり周知するよう施設に働きかけることを要望いたします。","respondent":"伊崎福祉部長","answer":"最後に、基本的には各施設でリーダーや看護師などに対応していただき、必要に応じて産業医の方に対応していただくものと考えております。しかしながら、各施設でご努力を頂いておりますけれども、区に相談があった場合は丁寧に対応してまいります。","id":"exchange-055"},{"speaker":"松澤委員","kind":"質問・要望","question":"東京都の若年性認知症の相談窓口も東京全体で２か所しかありません。品川区の若年性認知症に対するご見解と、この大田区との連携なども視野に検討してほしいと求めましたが、ご見解を説明を求めました。","respondent":"伊崎福祉部長","answer":"７つの柱の一つに若年性認知症が打ち出され、普及・啓発をはじめ、支援策を進めてまいります。基本的には在宅介護支援センターとなりますが、必要に応じて東京都の専門相談窓口をご案内するなど、関係機関との連携を図ってまいります。","id":"exchange-056"},{"speaker":"松澤委員","kind":"質問・要望","question":"来年度、多胎児家庭支援として要望していた移動助成がつき、タクシーでも使える品川区内共通商品券が配布されることになりました。先ほど一定期間、約３年ぐらいというお話がありましたけれども、何年か品川区で活動するということでよいのか尋ねました。","respondent":"柏原子ども未来部長","answer":"今のところ一定期間で３年間というところを考えてありますけれども、３年間程度ということでの活動期間を付させていただきたいと思ってあります。まずは担い手の確保というところに努めていきたいと思ってありますけれども…","id":"exchange-057"},{"speaker":"松澤委員","kind":"質問・要望","question":"その人に合う・合わないがあったり、その人に合ったエクササイズなど、そういった体のケアの部分に助成するなども考え方の一つではないでしょうか。ぜひ、産後の体のケアも、新しい母親支援として、品川区から全国に発信してほしいと求めましたが、ご見解を説明を求めました。","respondent":"福内品川区保健所長","answer":"子育てや身体の回復などへの心配も含め、不安が高まる時期であり、産後の心と体のケアは重要であると認識しております。今後も、利用者の個別の状況に合わせ、相談支援を実施し、産婦の方の心身の負担が軽減するよう、産後ケアの充実に努めてまいります。","id":"exchange-058"},{"speaker":"松澤委員","kind":"提案","question":"しかし、何より大切な視点は、そこに困っている人がいたら、当たり前のように助けてあげる、手を差し伸べてあげることではないでしょうか。自民党の芹澤委員が提案しました、安心を与えるすばらしい取組みかと考えますので、そこについてもご答弁をお願いいたしますとの意見を述べました。","respondent":"齋藤教育次長","answer":"ご提案のオンラインを活用したカウンセリングは、学校に来づらい児童・生徒への対応として有効性が期待されます。ＨＥＡＲＴＳの専用電話やアイシグナルと並ぶ新しい連絡ツールとして活用を検討してまいります。","id":"exchange-059"},{"speaker":"松澤委員","kind":"質問・要望","question":"生理の話でもありましたが、言葉にして伝えることができないというアンケートの回答に目を向けてほしいと求めました。多様な角度から、子どもたちの声に出せない声をしっかりと聞いていただきたいと要望して、質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"高齢者・障害者施設職員へのＰＣＲ検査は区独自に行ったのですから、区として積極的な感染防止対策に踏み出すべきです。区は、国の方針に基づいた対策を実施すれば、新型コロナが収束する、リバウンドしないと考えているのか、伺います。","respondent":"福内品川区保健所長","answer":"国民への注意喚起の継続、モニタリング検査の実施、保健所の積極的疫学調査の実施を挙げています。無症状者に焦点を当てた検査を実施するとしていることから、その動きを注視し、区としても必要な検査については実施してまいります。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"区も都も自粛を求めるばかりで、感染拡大防止のまともな対策を示せていません。区としても、リバウンドさせない対策を考えるべきですが、いかがか尋ねました。","respondent":"福内品川区保健所長","answer":"感染の再拡大の防止のためには、やはり、区民お一人おひとりにさらなる感染予防対策の徹底をしていただくことが必要だと考えています。検査につきましては、現在も行っております、高齢者施設の従事者のＰＣＲ検査等、今後も実施を検討してまいります。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"も防げないという状況ですから、新たな対策が必要だということで求めておりますので、リバウンドさせない取組みを行っていくべきです。医療機関、高齢者施設、障害者施設、保育園、幼稚園、学校、清掃所の全職員に対して、ＰＣＲ検査を定期的に行うことを求めますが、いかがか尋ねました。","respondent":"福内品川区保健所長","answer":"高齢者施設では現在、検査を実施しており、今後の定期的な検査については検討してまいります。そのほかの方々を対象とした検査につきましては、感染予防に資する適切な時期に、必要な対象に実施してまいります。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほど求めた施設の定期的な検査を行うことを、改めて求めます。なぜ定期的検査をしないのか、伺います。","respondent":"福内品川区保健所長","answer":"やはり、感染状況に応じた検査が必要だと考えております。ですので、それぞれの状況に合わせて検査を実施してまいります。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問・要望","question":"２３区で既に１１区が申請していますが、なぜ品川区は踏み出さないのでしょうか。いかがか尋ねました。","respondent":"福内品川区保健所長","answer":"６５歳以上の高齢者等、かかりつけ医等に相談していただき、必要に応じ実施されることが望ましいと考えております。東京都でも同様に実施される予定であることから、状況を注視し、必要に応じて協力してまいります。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"区が、商店や工場など中小零細企業の現場に足を運び、実態調査をすることを求めます。その調査を基に支援策を行うべきと考えますが、いかがか尋ねました。","respondent":"久保田地域振興部長","answer":"商店街の役員の方々をはじめ、店主の方から直接お話を伺うとともに、区が推進する支援策の周知に取り組んできたところです。区民・中小企業者に身近な支援であるというような評価も頂いておりますので、引き続き、区内中小企業の支援に努めてまいります。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"現在の支給件数と金額、予算額を伺います。新たに区に入る第３次臨時交付金の金額を伺います。","respondent":"久保田地域振興部長、品川財政課長","answer":"家賃支援給付金ですけれども、２月２６日現在、支給件数は２,７４２件、支給金額は約１億２,０００万円です。予算額につきましては、約７億４,５００万円です。 新型コロナウイルス感染症対応地方創生臨時交付金の第３次の額ですが、おおむね７億円程度となっています。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"緊急小口資金、総合支援資金などの延長を国へ要望することを求めます。いかがか尋ねました。","respondent":"久保田地域振興部長、伊崎福祉部長","answer":"それでこの間、先ほどもご説明しましたように、品川区としても独自の上乗せ助成ということで取り組んできたところです。これらのものについて延長するという考えは、今、私どもは持ち合わせてございません。 緊急小口資金および総合支援資金ですが、こちらは社会福祉協議会で対応している制度です。延長についても、国および社会福祉協議会で適切に判断されるものと認識しております。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"６月でコロナが収束する見通しが立たないわけですから、コロナが収束するまで延長するよう求めていただくよう要望いたします。持続化給付金、家賃支援給付金の第２弾の実施を国に求めていただきたい。","respondent":"久保田地域振興部長","answer":"国のほうで判断するべきものということでございまして、品川区として直接、国に求める考えはございません。消費税等につきましても、これまで答弁してきましたとおり、国が検討すべき事項でありますので、区として国に求める考えはございません。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"一番身近な自治体である品川区が、区内業者の支援のための要望さえ求めずして、どうして地域経済の回復が最重要などと言えるのでしょうか。改めて、感染拡大防止のために、抜本的な検査の拡充、暮らしや営業への補償を行うことを強く要望し、私の総括質疑を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"中塚委員","kind":"提案","question":"住民無視・住民犠牲の羽田新ルート運用中止を求めて、相次ぐ航空機事故について、大きく２点を伺います。国に、羽田新ルートの運用中止を直ちに求めるべきだと思いますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"３月１０日にも国土交通省を訪問しまして、再度申し入れを行っております。ご意見が何を伝えたいのかといったことで分類する方法を一般的に行っていますので、区としては、やはりそれが一般的な方法なのかと考えております。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"国に、住民の声は真摯に受け止めるよう求めるべきだと思いますが、いかがでしょうか。区民に事故が起きてからでは遅いと思いますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"即日、国からの報告と対応が示された中で、区も速やかに確実な対応を求めたです。ただ、新ルート全てを中止ということではなく、やはり原因究明と再発防止が最も大事なことであると考えているところです。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"直ちに羽田新ルートの中止を求めていただきたいと、強く要望したいと思います。ずばり品川区上空を回避するルートを検討しますと、国土交通省は言っているのか伺います。","respondent":"中村都市環境部長","answer":"国からの説明では、新飛行経路について、騒音軽減等の観点から見直しが必要な方策がないか検討を行うことというものを目的としています。それから、国の説明では、今年度、技術的選択肢のメリットとデメリットを整理するとしております。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問","question":"メリット・デメリットで固有名詞は出ていないということですが、つまり国は、品川区を飛ばないルートを検討しますとは言っていない、固有名詞は言っていないということでよいのか、改めて伺います。","respondent":"中村都市環境部長","answer":"国としては、技術的選択肢において、飛行経路の再検討を、固定化回避の検討を行うと言っているところで、品川区その他の自治体についての話は一切触れておりません。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"いずれも、どう考えても品川区の上を飛ぶと思いますけれども、いかがでしょうか。それとも、このチラシにあるＡ、Ｂ、Ｃ、Ｄ、Ｅの中で、どれか一つでも品川区の上を飛ばないルートがあるのか、伺います。","respondent":"中村都市環境部長","answer":"この図では、長さや高さといった数値が、まずここには記載されていないです。詳しい数字もないチラシの中の絵だけでは、区としては正直に言って判断が困難と考えております。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺います。いずれも品川区の上を飛ぶと思いますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"やはり現在、国が専門家を交えて検討中という事柄に対しまして、何かを断定するというのは非常に難しいというところが正直な考えです。国において固定化回避検討会の検討が、これをより一層進めていただいて、国には申し入れていきたいと考えております。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問","question":"これは、どう考えても品川区の上を通るじゃないですか。なぜそれをかたくなに認めようとしないのか、改めて伺います。","respondent":"中村都市環境部長","answer":"検討を進める必要もないわけですし、品川区の上を飛ぶ・飛ばないといった判断については、差し控えるべきと考えております。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問・要望","question":"そして、品川区を飛ばないルートを国に求めるべきです。いかがか尋ねました。","respondent":"中村都市環境部長","answer":"これまで国が主体となって進めてきている首都圏空港の機能強化におきまして、騒音・落下物、それぞれの対策を進めてきていると認識しております。区としましては、それに対して可能な限り、安全対策・騒音対策を万全に行っていただくよう、これからも求めていくという考えです。","id":"exchange-078"},{"speaker":"中塚委員","kind":"質問・要望","question":"そもそも、なぜ午後３時過ぎ、Ａ・Ｃ滑走路に変更するのかを伺います。Ａ・Ｃ滑走路に進入する際、なぜ長い距離を真っすぐ飛ぶ必要があるのか、伺います。","respondent":"中村都市環境部長","answer":"現在の新ルートに至る検討状況が、たしか１７種類近くのパターンの検討を経まして、現在のルートになったと説明がなされているところです。４本の井桁状の配置というところでございまして、やはり交差部分で時間的な重なり…","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問・要望","question":"何が固定化回避ですか。計画容認は撤回し、都心品川区の上を飛ぶルートの変更を国に求めるべきだと思いますが、改めていかがか尋ねました。","respondent":"中村都市環境部長","answer":"区としては認識しているところでございまして、これに対する十分な対策がなされた上で、新ルートの対策をしっかりと行っていただくということ。引き続きこれを求めてまいります。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問・要望","question":"計画撤回を強く求めて終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"筒井委員","kind":"質問","question":"品川区では、他の特別区の経済状況の把握はしているのでしょうか。このような経済状況の悪化は、特別区長会で認識の共有や議論はされているのか尋ねました。","respondent":"堀越企画部長","answer":"他の特別区の経済状況についてですが、品川区と同様に、景況調査を実施したところがあります。コロナ禍での状況の認識の共有・議論は当然されておりまして、各区が様々な新型コロナウイルス感染症対策を行っているというものです。","id":"exchange-082"},{"speaker":"筒井委員","kind":"質問・要望","question":"各種給付金の再給付など、実効性ある経済的支援を継続的に求めるべきと考えますが、区のご見解はいかがでしょうか。令和２年度の支援策と比べて特筆すべき点はありますか尋ねました。","respondent":"久保田地域振興部長","answer":"令和３年度の支援策につきましては、新型コロナウイルス感染症対応中小企業支援特別助成、助成率５分の４で上限２０万円。そのほかに、経営相談体制の拡充やオンライン申請の導入など、令和２年度の補正予算で拡充したものを継続するといったところが挙げられます。","id":"exchange-083"},{"speaker":"筒井委員","kind":"質問・要望","question":"特筆すべき点の一つとして、経営変化対策資金２０２１で、この趣旨や目的についてお伺いいたします。換気と、ＣＯ２測定器の購入費用は、今回の新型コロナウイルス感染症対応中小企業支援特別助成の対象経費に含まれるか尋ねました。","respondent":"久保田地域振興部長","answer":"次に、ＣＯ２測定器についてですが、こちらにつきましては、対象経費の事業の対象になると考えています。売上げの増につながるものと考えておりますので、こうしたものも対象といたしまして、本支援策を積極的に活用していただきたいと考えております。","id":"exchange-084"},{"speaker":"筒井委員","kind":"質問・要望","question":"正確で客観的な科学的な情報提供を適宜迅速に行ってほしいと求めましたが、区の具体的な対応はいかがでしょうか。この点、管理システムの開発会社として、品川区ではどの会社のシステムを採用されるのか尋ねました。","respondent":"秋山保健整備担当部長","answer":"入電したお問い合わせ全てに対応できておりますが、対応回線の増強など、適切に対応してまいります。日本コンピューター製のシステムを採用しており、新型コロナウイルスワクチン接種の区民の情報は、引き続きこのシステムにて管理いたします。","id":"exchange-085"},{"speaker":"筒井委員","kind":"質問・要望","question":"５－アミノレブリン酸（５－ＡＬＡ）による新型コロナウイルスの感染抑制効果が判明し、区はこの情報を把握されていますでしょうか。治療薬の情報にも注目していってほしいと求めましたが、いかがか尋ねました。","respondent":"福内品川区保健所長","answer":"新型コロナウイルスに対する抗ウイルス薬や、その症状に応じた様々な治療薬の開発が進められており、有効性の高い治療薬が期待されるところです。今後、患者を対象とした臨床研究が開始される段階と聞いており、これらの治療薬についての情報も注視してまいります。","id":"exchange-086"},{"speaker":"筒井委員","kind":"質問","question":"今後、収束を早めるため、さらに一歩踏み込んだ対策が必要だと考えますが、いかがでしょうか。例えば、飲食店利用者へのマスク飲食の徹底、もしくは飲食フェイスシールド着用の徹底を区民に呼びかけるべきと考えますが、いかがか尋ねました。","respondent":"福内品川区保健所長","answer":"相手の飛沫による自分の目の粘膜からの感染を防ぐためのものであり、感染を広げないためのものではないことにご留意いただきたいと思います。いわゆる密集・密接・密閉の３密を避けることや、ホームページ等を通じ、継続的に普及・啓発してまいります。","id":"exchange-087"},{"speaker":"筒井委員","kind":"質問","question":"このため、区民の身近なところに電気自動車用充電スタンドを多く設置するべきと考えますが、いかがでしょうか。東京都が令和３年度予算で、従前設備の設置費等の補助を行うということですが、都の補助の活用はいかがお考えか尋ねました。","respondent":"中村都市環境部長","answer":"は事業所用のＬＥＤの照明設置助成、そして低公害車への買い換え支援といった民間への支援、区も自ら取り組んでまいりました。区の基本的な取組みの方針としまして策定した品川区環境基本計画に、目標について検討して、引き続き取り組んでまいりたいと考えております。","id":"exchange-088"},{"speaker":"筒井委員","kind":"質問・要望","question":"東京２０２０大会開催いかんに関係なく、この事業はぜひ進めていってほしいと思いますが、いかがでしょうか。今回、五反田バレーと連携し、舟運とＩＴ技術を融合させた新たな取組みも模索するとありますが、これはどのようなものになりますか尋ねました。","respondent":"藤田防災まちづくり部長","answer":"舟運通勤社会実験ですけれども、こちらは都と連携し、今、オリンピック等の開催中に実施する計画です。こうしたことから、７月から９月の平日２０日間に実施する計画としているものです。","id":"exchange-089"},{"speaker":"筒井委員","kind":"質問・要望","question":"その中で、舟運の活性化も進めようとしており、ベイエリア対岸の品川区、そこに東八潮を有する品川区も、この状況を注視し、連動すべきと考えます。東京国際クルーズターミナル近くの青海小型船発着所浮桟橋の活用を以前より提言しておりましたが、今の状況と今後の活用予定をお知らせください。","respondent":"藤田防災まちづくり部長","answer":"来年度につきましては、東京２０２０大会舟運事業において、青海と天王洲を結ぶ航路も検討されているところです。今後も、管理者であります東京都と連携・協力し、進めてまいりたいと考えております。","id":"exchange-090","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問","question":"次に無電柱化について伺います。重要なところから先行して計画を前倒しで進めることも考えられるかと思いますが、その可能性など、区のご見解をお知らせください。","respondent":"藤田防災まちづくり部長","answer":"これらを効果的・効率的に解決しながら、無電柱化を進めていく必要があると考えています。工事に取りかかってからの時間を少しでも短くして、工事完了の前倒しになるように、つなげていきたいと考えています。","id":"exchange-091"},{"speaker":"筒井委員","kind":"質問","question":"無電柱化に係る費用を抑えるために、低コスト手法が取られることかと思いますが、それは大地震発生時に耐えられるものなのでしょうか。都の区市町村無電柱化補助が再び令和３年度予算でつく予定ですが、活用の予定はありますか尋ねました。","respondent":"藤田防災まちづくり部長","answer":"１つ、実施する際のコストの縮減も大切ではありますけれども、また災害時のメンテナンスや復旧あるいは復興といった点も考慮しないといけません。東京都では無電柱化チャレンジ支援事業や、防災に寄与する補助メニューを拡充する予定だと聞いてあります。","id":"exchange-092"},{"speaker":"筒井委員","kind":"質問・要望","question":"次に、デジタル化推進について伺います。デジタル化の過去の取組み状況、そして新規の取組み、これからの取組み予定をそれぞれお知らせください。","respondent":"堀越企画部長","answer":"さらに今後の予定といたしまして、加えてテレワーク、様々あります。セキュリティ対策をしっかりしながら、全庁的・分野横断的取組みを強化してまいりたいと考えているところです。","id":"exchange-093"},{"speaker":"筒井委員","kind":"質問・要望","question":"なるべく多くの人たちに集まっていただくということが必要だと思いますけれども、周知方法の工夫というのはどう取られるのでしょうか。高齢者以外にも低所得者世帯への対策というのはいかがお考えでしょうか、お知らせください。","respondent":"堀越企画部長","answer":"今ご紹介がございました高齢者への対応などとして、スマホ教室、それから従来から行っているパソコン教室などもあります。様々状況を見ながら、それぞれ検討し、進めていきたいと考えているところです。","id":"exchange-094"},{"speaker":"筒井委員","kind":"質問・要望","question":"このデジタル認知症の対策をいかにお考えでしょうか。子ども、若年層、中年成人層、高齢者層といった世代別にお答えください。","respondent":"堀越企画部長","answer":"この、年齢に関わらず発症する可能性のあるもので、デジタル機器の普及が進んだ現代ならではの症状であると考えています。幅広い年代の方にどのような対策をしていくかというものにつきましては、国の動向等を見ながら、研究していく必要があると考えています。","id":"exchange-095"},{"speaker":"筒井委員","kind":"質問・要望","question":"次に、施設予約方法の改善について伺います。洗練されたものに改善すべきだと考えますが、この点、ご見解をお願いします。","respondent":"堀越企画部長","answer":"施設予約システムですが、平成３１年３月に新システムに移行いたしました。現時点では残念ながらスマートフォンの対応を行っていないため、来年度中には対応できるように、事業者と調整しています。","id":"exchange-096"},{"speaker":"筒井委員","kind":"質問・要望","question":"今、もう令和３年度から見直しをかけて、そのリニューアルが完成する見込みというのは大体どのくらいになると考えておられるでしょうか。お答えください。","respondent":"堀越企画部長","answer":"先ほどご答弁申しましたとおり、令和３年度中、来年度中の展開ということで、今、予定をしておりまして、事業者等と調整しています。","id":"exchange-097"},{"speaker":"筒井委員","kind":"質問","question":"調整ということで、見込みの、大体、何年かかるとか、そういう時間的なものは分かるでしょうか。お分かりになるなら説明を求めました。","respondent":"堀越企画部長","answer":"令和３年度内にはという意味で、今、考えてあります。先ほどご答弁申し上げましたとおり、令和３年中には実際に新しく、スマートフォンでの対応の展開ができるように準備をしていきたいと考えています。","id":"exchange-098"},{"speaker":"筒井委員","kind":"質問","question":"このデイキャンプ場の予約方法を、デジタル化に沿った、区民にとって利便性が高いものに改善すべきかと考えますが、いかがでしょうか。先ほどご答弁のあった品川区施設予約システムの予約方法に、いかにして組み込んでいくかというご予定はあるのか尋ねました。","respondent":"藤田防災まちづくり部長","answer":"これによりまして、グループで、必要なものを事前に確認し、忘れ物をなくすという、１つの考えです。利用者の立場に立つことも非常に大切なことだと考えていますので、施設予約システムの利用も含め、検討してまいりたいと考えています。","id":"exchange-099"},{"speaker":"筒井委員","kind":"質問・要望","question":"まず確認ですが、スケーターなど関係者の声をどこまで取り入れたのか、制作過程をお知らせください。完成から４年目ということを踏まえて、そして改修するところは改修すべきと考えますが、いかがか尋ねました。","respondent":"藤田防災まちづくり部長","answer":"八潮北公園のスケートボード場の建設費用についてですが、おおむね６,０００万円です。公園内の限られたスペースの中で設置した施設であり、利用者の皆さんのご意見や、様々なアドバイスを頂くよう努めてまいります。","id":"exchange-100"},{"speaker":"筒井委員","kind":"質問・要望","question":"そして、このスケートボード場がより進化し続けて、区民にとってよりよいスケートボード場を造っていただきたいと考えております。以上で私の質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-101"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど部長も、これでは分からないとご答弁されましたし、区としても、正確な、地図に落とした図を国に求めるべきと考えますが、見解を伺います。そして、固定化回避検討会は、いつまで検討し続けるのか、期限を正確に示すよう、区は国へ求めるべきです。","respondent":"中村都市環境部長","answer":"区長が、固定化回避の検討会を開いていただきたいという意味で、固定化を回避する検討をしていただきたいといった要望を出したところです。しかしながら、専門家が検討していく中ですので、注視していくことはできても、期限を切ることは困難と考えます。","id":"exchange-102"},{"speaker":"田中委員","kind":"質問・要望","question":"そして、目処について、国がこのまま検討会を先延ばしにすることがないように、区としてきちんと期限を強く求めるべきです。発達障害など、ほかの障害がある方たちとの協議や対応がなされたのかを伺います。","respondent":"伊崎福祉部長","answer":"お申し出を頂ければ、国の基準はあくまでも基準ですので、必要に応じてそちらのほうは対応しています。具体的に、イヤーマフという日常生活用具がありますので、そちらの支給をするなどして対応できると考えています。","id":"exchange-103"},{"speaker":"田中委員","kind":"質問・要望","question":"羽田のところで、目処、区としての期限はいつ頃かというのを強く求めるべきだと言ったのですけれども、いつ頃までという期限を、見解を伺いたいです。見解を伺います。","respondent":"中村都市環境部長、伊崎福祉部長、品川財政課長","answer":"羽田新飛行経路の固定化回避検討会の期限についてですけれども、専門家が技術的な検討をする中で、区から期限を切ることは困難だと考えます。しかし… 障害のある方への対応についてお答えいたします。先ほど申し上げました支援につきましての周知、団体の方からのヒアリングを行っているほか… それから福祉部につきましては、光熱費や備品購入費が主なところです。それから、予算全体の委託料のところですが、全体としては約１６％となっています。","id":"exchange-104"},{"speaker":"田中委員","kind":"質問","question":"委託内容を決定し、その内容に適した委託事業者を選択すべきだったと考えますが、見解を伺います。以上、３点伺います。","respondent":"藤田防災まちづくり部長、滝澤災害対策担当部長","answer":"区でも考えておりますので、契約する考えで、進めているところです。もちろん、その中で、区の脆弱性などに関しても熟知した事業者であると考えているところです。 ７月から関係機関や庁内調整を実施、１０月以降、原案を作成予定であります。区民による分別・排出要領を周知・徹底する必要があることから、区民に対する意見聴取については具体的に検討してまいりたいと考えております。","id":"exchange-105"},{"speaker":"田中委員","kind":"確認","question":"新庁舎整備基本構想の委託内容６項目では、区民や議会の意見を聞き、区が作成すべきではないでしょうか。以上、２点伺います。","respondent":"榎本総務部長","answer":"今現在行われている庁舎機能検討委員会の中でも、もう大分浮き彫りになってきておりますので、そういうものを基につくっていくという形です。庁舎の改築・改修についての新計画について検討してきて、それから求められる新庁舎の機能検討、連続的につながっているものです。","id":"exchange-106"},{"speaker":"田中委員","kind":"確認","question":"ここまで委託すべきなのでしょうか、伺います。以上、３点伺います。","respondent":"榎本総務部長","answer":"今回考えているのは、庁舎機能検討委員会のまとめができた段階で、ワークショップを行っていくということが１つ。基本構想・基本計画の検討委員会は、地域団体の方に入ってもらって、意見を聞きながらやっていくというものです。","id":"exchange-107"},{"speaker":"田中委員","kind":"提案","question":"これについても区民や議会との議論が必要かと考えますが、見解を伺います。以上、３点伺いますとの意見を述べました。","respondent":"榎本総務部長","answer":"その前のたたき台は７月ぐらいに出さないと、庁内内部での検討もできませんので、そういったスケジュールで示しているものです。そういう制約があるという中での検討になりますので、きちんとつかんでいただかないと、全然制約がない中での検討をされても困るという形です。","id":"exchange-108"},{"speaker":"田中委員","kind":"提案","question":"そして最後に、子ども・若者支援の充実を求めて質問します。伺いますとの意見を述べました。","respondent":"榎本総務部長、齋藤教育次長、柏原子ども未来部長、福内品川区保健所長","answer":"委員がご覧になっている実施要領の中にきちんと書いてありまして、選定会議が３月２９日ということで、まだ決定しておりません。… ＨＥＡＲＴＳなどが支援を行っておりますし、ネグレクトなど深刻な事例については、子ども家庭支援センターに連絡して対応してまいりました。… 子ども家庭支援センターで直接相談を伺ったりということもありますし、広いチャンネルを持って、そういった声を伺っているという状況です。… 保健部門でも、若年者・女性の自殺が増加しており…","id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"区民の財産ですので、ちゃんと区民にも意見を聞いてほしいですし、「どうしますか」と投げかけてほしいです。伺います。","respondent":"榎本総務部長、柏原子ども未来部長","answer":"「区が」というのは、区が所有しているという意味での、扱いをどうするかを、まず第１段階で決めるという形です。最終的に案がまとまれば、それをそれぞれ議会に報告して、それからワークショップ等をして… 情報のやり取りというのは必要な部分であろうかと思いますので、やり方については幾つか検討が必要だろうと思ってあります。新年度に居場所スペースと、それから学習支援といったところを統合して…","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"「区が」や「議会が」ではなくて、区民の声を聞くという立場に立っていただきたいと強く求めます。例えば子どもオンブズマンの設置を含め、声を聞く機会と関係団体との十分な連携体制を、改めて構築していただきたいと求めますが、見解を伺います。","respondent":"柏原子ども未来部長","answer":"そういった視点というのは大切な部分であろうかと思います。様々な手法が考えられると思いますので、関係機関とも連携しながら、どういったことができるかというのは検討していきたいと考えています。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"様々な手法の中に、ぜひ子どもの声を聞くということ、子ども自身、若者自身の声を聞く機会というのを広く捉えてほしいと求めました。そして、子どもオンブズマンの設置についてご答弁がなかったので、ぜひ前向きなご答弁を頂きたいと思うのですが、いかがか尋ねました。","respondent":"柏原子ども未来部長","answer":"先ほど申し上げたいろいろな関係機関と連携している中で、何ができるかということを含めて、検討させていただければと思います。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"ですので、子どもの声を聞くという機会は、必ず設けてほしいと思います。子どもオンブズマンについて強く要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-113"},{"speaker":"大倉委員","kind":"質問","question":"これまでの取組みについて、区としてどのような方針で、このシティプロモーションを行ってきたのか、伺います。やはり、最初は外向けの発信が多くあったのかと思いますが、どのように重点を置いて行ってきたのか、伺います。","respondent":"堀越企画部長","answer":"それから、訪れた方が区の魅力に触れ、住んでみたいと感じていただくこと、これが１つです。ご紹介いただきました様々な取組みを進めてきたところでございまして、今、人情に訴えるような形でのシティプロモーションを展開してきたところです。","id":"exchange-114"},{"speaker":"大倉委員","kind":"質問・要望","question":"こうした点を踏まえて、品川区の行ってきたシティプロモーションの取組みに対して、区ではどのような評価をされておりますでしょうか。区内へのアピールと区外へのアピール、それぞれの評価についてもお知らせほしいと求めました。","respondent":"堀越企画部長","answer":"それからどちらかといえば感じているという方の合計が、８割を超えておりますので、こちらも一定の成果があったものと考えています。ＩｎｓｔａｇｒａｍやＦａｃｅｂｏｏｋといった、シティプロモーションのツールの認知度については、やはり強化が必要だと考えているところです。","id":"exchange-115"},{"speaker":"大倉委員","kind":"質問","question":"私も生まれ育ちが品川区ですから、品川区には、区民にとって役立つ取組み、魅力的な点というのが、非常に多いと考えています。改めてシティプロモーションの戦略策定をすべきと考えますが、区のご所見を伺います。","respondent":"堀越企画部長、久保田地域振興部長","answer":"現在までは、東京２０２０大会を目指しまして、コロナ禍の状況にありますが、イベント的なものも数多くやってまいりました。併せて、先ほどの繰り返しになりますが、Ｉｎｓｔａｇｒａｍ等もいろいろ使いながら… 地域活動の活性化と発展にとって重要と考えておりまして、地域活動課または地域センターの職員が直接お話を伺いしまして、個別に対応しております。区民活動情報サイト「しながわすまいるネット」の活用も有効と考えておりまして…","id":"exchange-116"},{"speaker":"大倉委員","kind":"質問","question":"こうした流れを品川区はどのように捉えているのでしょうか、伺います。ｅスポーツについて、現在、区で取組みがあればお知らせください。","respondent":"堀越企画部長、山崎文化スポーツ振興部長","answer":"戦略的な考え方といたしまして、「つなごう品川」という冊子を作ったり、それからそのウェブ版を展開してきております。実施したことをまとめて、区のシティプロモーションに対する考え方を発信していくなど… １つ、貢献活動の一つとして、そのメーカーが保有している「ぷよぷよ」という名称のゲームがあります。こういったプログラミングソフトなどを試行的に提供していただいて…","id":"exchange-117"},{"speaker":"大倉委員","kind":"質問","question":"ｅスポーツの活用について、区のお考えを伺います。こうした課題解決に向けた取組みとして、ｅスポーツの活用ができると考えますが、併せてお知らせください。","respondent":"山崎文化スポーツ振興部長","answer":"ｅスポーツの効果という意味では、スポーツ振興に資する部分といったものもあるかと考えています。様々、ｅスポーツの活用・研究を、区としては行っていく必要もあるかと考えているところです。","id":"exchange-118"},{"speaker":"大倉委員","kind":"質問・要望","question":"品川区で独自に区民大会のような、区民参加型のｅスポーツ大会を開催してはいかがかと考えますので、ご所見を伺いたいと思います。社会参加の促進なども、こうした大会を開くことで進んでいくのかと考えておりますので、ご所見を伺いたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"まちのにぎわいづくりなど、地域振興あるいは地域の活性化といったような産業分野の効果も含めまして、期待できるかです。区としましては様々、今後の動向も注視しつつ、研究してまいるという考えです。","id":"exchange-119"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に、再犯防止推進計画について伺いたいと思います。品川区内におけるここ数年の犯罪検挙数と再犯率はどの程度なのか、把握されていれば、数値が分かれば教えてほしいと求めました。","respondent":"久保田地域振興部長","answer":"国全体としまして、再犯率は４８.８％となっています。出所された方への支援についてですけれども、既存の福祉施策などで支援をしているものでございまして、支援を行っております。","id":"exchange-120"},{"speaker":"大倉委員","kind":"質問","question":"伺います。今後こうした制度の周知と協力の体制づくりを企業に向けて行っていくなど、今後の体制・支援について区のお考えを伺います。","respondent":"久保田地域振興部長","answer":"出所後の住宅支援を行っている団体との具体的な連携は現在進めておりませんが、更生保護対象者もその支援の対象としている団体が６団体あります。刑期を終えた方々の支援は、どのような支援が可能か、今後調査・研究をしてまいります。","id":"exchange-121"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に、品川区でも、地域特性に合わせた独自の再犯防止推進計画の策定について検討してほしいと求めましたが、ご所見を伺います。","respondent":"久保田地域振興部長","answer":"２３区の中でも４区で策定していますが、引き続き２３区の動向を注視しながら、調査・研究を進めてまいりたいと考えているところです。ＢＢＳ会等と連携しながら、社会を明るくする運動を通しまして、再犯防止に努めてまいります。","id":"exchange-122"},{"speaker":"石田（秀）委員","kind":"提案","question":"私たち会派が地域の皆様や各種団体から頂いた声を基に要望や提案した施策であり、着実に具体化されることを望みます。そして、本日の総括質疑や款別審査において我が会派の委員からの要望・提案も事業実施されることを要望しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"国・都の手の届かない事業所や商店街デジタル化支援、指定管理者選定や行政デジタル化等は、喫緊の課題として対応されるよう強く求めます。そのために、事業執行では一層の倹約に努め、財政基盤を整え、年度途中であっても諸課題に対応する施策を果敢に実行する区政運営を求めます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-124"},{"speaker":"大沢委員","kind":"提案","question":"専門的見地から、コロナ感染予防対策、ワクチン接種の速やかな体制の確立やインクルーシブ教育の推進等を提案いたしました。本委員会で各会派議員より質問・提案した内容は、それらの課題を円満に解決する糸口を見いだすものであると考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-125"},{"speaker":"石田（ち）委員","kind":"提案","question":"消費税の減税や支払い猶予などを国に求めよと質問しましたが、これも求める考えはないと、区民の苦境に背を向ける冷たい答弁です。東京２０２０大会は、中止を求めますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問・要望","question":"今は感染拡大を回避し、区民の命と健康と生活と雇用を守る対策を優先し、収束まであと４年かかる道のりを乗り越えていただきたい。終わりに、世界中で多くの犠牲者が出ているさなか、今年の東京五輪は中止し、再度延期するべきです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-127"},{"speaker":"吉田委員","kind":"提案","question":"生活者ネットワークは、今からでも計画の中止を国に対して求めるべきと主張します。その他、各款別審査で生活者ネットワークが指摘・提案させていただいた意見を、予算執行に活かしていただくことを要望し、意見表明といたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-128"},{"speaker":"大倉委員","kind":"提案","question":"東京２０２０大会、多様性の推進など、各課題への積極的な取組みも求めます。今回の予算特別委員会において我が会派の所属議員が質問の中で指摘・提案した各項目を真摯に受け止め、予算を執行することを強く要望してとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-129"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/309623?Template=document&Id=1140#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":123737,"voices":294}},{"id":"r03-20210322-10","meetingId":"r03-cm03","date":"2021年3月22日","dateIso":"2021-03-22","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5404#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":9597,"voices":43}},{"id":"r03-20210416-10","meetingId":"r03-cm04","date":"2021年4月16日","dateIso":"2021-04-16","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"芹澤委員","kind":"提案","question":"特に妊婦とかも含めて、避難施設でもありますけれども、どういった支援策が今後求められるのかを議論したいと考えています。以上、提案とさせていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"答申が出ていますので、ここについての確認。１回しか議会に対して報告がなかったというところで、この策定委員会が開かれたときに、議会に報告をしていただきたいということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"松澤委員","kind":"意見","question":"７月、８月で東京２０２０大会の総仕上げとして、最後の総括的なものでやれたらいいなと考えております。レガシーに関しては、ボランティアレガシーも含めたレガシーの活用を、いかに継続していくかというのを考えていきたいと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"提案","question":"共産党からは４つの特別委員会の設置を提案したいと思います。区民の関心は高いですし、まさに第４波と言われる事態ですから、それに見合った議論が必要かなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"５つの常任委員会の審議時間を増やし、集中的に各所管、各事業部の議論をするべきだと思います。品川区の喫緊の重要課題に対し、各常任委員会でしっかり議論するべきだと思いますので、特別委員会を設置することは反対しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"提案","question":"私の会派からは２つの特別委員会を提案しています。この１年間を考えたときに、状況的に１年間は無理ではないかということで、災害対策・環境対策特別委員会という形で提案していますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"意見","question":"私どもは４項目挙げてはおりますが、あともう一つについては、また協議をすると。数としては２つというところで、議論を進めていただけるとありがたいなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"提案","question":"行財政改革特別委員会とオリンピック・パラリンピック特別委員会を提案させていただきました。２つの特別委員会ということで、との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"意見","question":"今年の開催も、区民の代表としての我々の議論の中では、設置するのはこれで終わりにしようという議論もありました。これまで何年か設置してきましたけれども、今回は設置しなくてもよろしいのではないかとなったことは付け加えしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"特別委員会の設置ということですから、区民の期待に応える区議会でありたいという思いで、強調させてほしいと求めました。率直に言って、開催は難しいと私は思っておりますので、今期については設置する必要はないという意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"本多委員","kind":"意見","question":"各会派の調査項目を見ると、かなり同じ項目があるなと思っていますので、集約できるものは集約して、例えば災害に関することや、行財政改革の調査項目としているものとか、集約ができるのかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"提案","question":"今、委員長もお話ありましたが、２つでまとめて、委員は現在と同数でいけばどうかなと考えています。清掃、リサイクル、その辺もやっていったらどうかと提案しておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"中塚委員","kind":"意見","question":"環境対策を入れるのであれば、昨年も指摘しましたけれども、ＣＯ２の削減。リサイクルに特化するのではなくて、ＣＯ２の削減は調査項目として加えるべきではないかと意見を述べたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"意見","question":"なぜ環境なのかというところで、今、そういう観点を入れていただけるとありがたいなと考えています。環境を入れることには当然、賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党としても、清掃、リサイクルに特化しないで、環境全体ということで、先ほどＣＯ２削減とありましたけれども、ＺＥＢを入れた上で、ＣＯ２削減も含めた調査もできると思いますので、考え方としては同じだと思っていますとの意見を述べました。","respondent":"石田（秀）委員長","answer":"特別委員会は２つ、正副委員長も１人ずつで前回と一緒、暫時休憩します。○午後 １時３６分休憩 ○午後 ２時１０分再開","id":"exchange-015"},{"speaker":"あくつ委員","kind":"確認","question":"確認ですけれども、文言のことで、１の避難計画に関することの備考の、括弧の中に要配慮者とあるのですけれども、要支援者か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"議論があったのは分かりました。ただ、今の説明だとよく分からないので、また後で説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"こんの委員","kind":"確認","question":"これも確認なのですけれども、行財政改革特別委員会の調査事項の１番です。そういうところを確認していくということですが、具体的なところは委員会が始まって、そこの中で出していくということでよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"ちなみに、元芝のところの都有地というのもあるかなと思ったので、そういったところを出していけばいいということか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]},{"id":"topic-02","title":"その他の(1)政務活動のあらましおよび年度収支報告書等の公開","agenda":"その他の(1)政務活動のあらましおよび年度収支報告書等の公開","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"複数の議員からの開催を要望する声も伺っていますので、この議会改革推進会議というのを、ぜひ早期に開くべきなのではないかと思います。議会改革推進会議のリーダーも兼務されていらっしゃいますので、委員長のほうで、もし見通しとか考えがあれば伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"安藤委員","kind":"意見","question":"分かりました。お考えを聞けたので、議会改革を活発に進めていけたらと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5406#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":19526,"voices":89}},{"id":"r03-20210419-6","meetingId":"r03-cm04","date":"2021年4月19日","dateIso":"2021-04-19","committee":"区民委員会","time":"午後 １時００分～午後 ３時３１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件整理しています。","topics":[{"id":"topic-01","title":"令和元年請願第２１号、選択的夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願","agenda":"令和元年請願第２１号、選択的夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願ということで、要は、実現させていただきたいと思っています。さらに取り組まれていることだったり、そして、夫婦別姓制度の現状を今どうご覧になられているか伺いたいと思います。","respondent":"木村戸籍住民課長","answer":"それから、現状認識としては、この意識調査のほうでも、かなり最近、報道のほうでもこのような形で出されてきているところもあります。今のところはそういう状況を把握しています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国で審議をされるべきものであるというところでは、本当に国に早く進めていただきたいと思っています。それを国でしっかり審議を進めるというのは、これだけ求められていることなので、当然だと思うのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"松本委員","kind":"確認","question":"やはりどう不便性をクリアしていくかというところは、そこを区議会のレベルで一応確認した上で考えていくべきだと考えています。新氏にならざるを得ないという理解でよろしいか、確認させてほしいと求めました。","respondent":"木村戸籍住民課長","answer":"金融機関、それから、パスポートの取扱いについては、今、委員ご指摘のとおりです。","id":"exchange-003"},{"speaker":"くにば委員","kind":"質問","question":"令和元年１２月、意見書が可決した自治体、こちらの把握状況をお伺いしたい。現在の進捗状況、現在の状況というのを、把握している範囲でお教えください。","respondent":"木村戸籍住民課長","answer":"現在の状況です。３月末現在で、東京都内では１４区２２市、全国では２０７の議会で意見書の提出がされているです。","id":"exchange-004"},{"speaker":"くにば委員","kind":"質問","question":"住民の方々からこのようにしてほしい、この１年４か月の間に増えたとか、把握している状況を説明を求めました。","respondent":"木村戸籍住民課長","answer":"現場の窓口、あるいはお電話という形での具体的なご相談というのは正直受けておりません。旧姓、そのようなご要望、本来はそうしたいのであろうという方がかなりいらっしゃるのではないかという推測はしておるところです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"確認","question":"「いわゆる」というのはどういう意味ですかということが１点と、３１自治体で提出しているみたいな、たしか朗読の中にあったような。３１というのは、日本全国の自治体の中の３１かということのまず確認。","respondent":"木村戸籍住民課長","answer":"いわゆる別姓制度という形、同じことを言っているというところなのですけれども、そういう部分でのご説明です。それから、３１は、この当時の全国の自治体の中での３１という形です。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"括弧書きで、（いわゆる別姓制度）とかいうのなら分かるけれども、一番最初にいわゆる別姓制度という形で、ほかの案件でも出てくるではないですか。やはりこれは国会でもっと議論していただいて決めていっていただきたいという思いが私はあるのですけれども、その辺についてはいかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"もう少し分かりやすく誤解のないような形で表現すべきであったかと考えていますので、今後、気をつけてまいりたいと思います。それから、国で決めてもらえばいいかということは確かにおっしゃるとおりでございまして、そちらのレベルで議論されるものであると考えております。","id":"exchange-007"},{"speaker":"つる副委員長","kind":"確認","question":"今、もう一度確認なのですけれども、意見書として受けましたというところの部分で確認をしていただいた中で１４区２２市ということなのですね。全国だと数が幾つ、もう一回すみません、確認で。","respondent":"木村戸籍住民課長","answer":"私の説明が悪くて、なかなかうまく伝わっていないようで、申し訳ございません。お答えできないという形で、先ほどお答えいたしましたのは、集計して出されている数です。","id":"exchange-008"},{"speaker":"つる副委員長","kind":"質問","question":"直接的に窓口が違うのかもしれないですが、この課題についての質問だとか問合せというのは、区のほうにはこの間どの程度来ているものなのですか。区としてどういう今考え方にあるのかとか、そもそも論みたいなところの問合せというのは、区のほうにあるのか尋ねました。","respondent":"木村戸籍住民課長","answer":"繰り返しになりますけれども、現時点では、私ども、それからほかのセクションからこういう声があったというところは、正直、把握をしておるところではありませんが、直接的なお問合せという形では、私は今のところは聞いていないところです。","id":"exchange-009"},{"speaker":"小芝委員","kind":"意見","question":"先にそれをもくろんでいるのかどうか分かりませんが、マイナンバーカード、パスポートにも旧姓の併記が認められるようになってきているわけですから。ただ、これは国政とも連動するものですので、国の状況を鑑みながら、品川区としても対応を考えていかなければならないと思いますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"つる副委員長","kind":"確認","question":"先ほど質疑のところで、党としてのスタンスは確認させていただいたところでありますし、中心となっている団体からのお声を伺って。ただ、先ほどいろいろな自治体の一覧も確認させていただいたのですが、マイノリティーにならないようにしていかなければいけないのかというところで。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"様々、通称が使用できるからいいでしょうという問題ではないのが夫婦別姓の問題だと思っていますし、その改正を求める大きな声かと思います。議会としてはそれを後押しする採択をしたいと思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"国のほうでも議論を進めていく中で、それをしっかり注視していきたいと考えています。区議会で進めながら取り組んでいっていただきたいというところでは、注視をしっかりしていきたいと考えていますので、継続でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問・要望","question":"国会で審議を推進するかどうかに対して請願が上がっているもので、それに対して我々がどう意見をするかということだと考えております。私は選択的夫婦別姓に関しては導入を求めるものですけれども、そことはまた論を別にして、こちらの請願に関しては採択すべきと考えます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"松本委員","kind":"質問・要望","question":"これは団体の方からもお伺いしているので、これからこの品川区の中で、本当にキーとなるのは公明党の皆様だと考えています。意見書ですから、ぜひ皆様にも引き続き考えていただきたいというところで、私の意見を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]},{"id":"topic-02","title":"令和３年度町会・自治会に対する補助制度","agenda":"令和３年度町会・自治会に対する補助制度","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"先ほどの説明の中で、助成制度が７つだったのが１７になったとおっしゃったかと思うのですけれども、増やしたものはどれなのかというのと、あと、補助制度を増やした経緯だったり、そういうのが分かれば説明を求めました。","respondent":"川島地域活動課長","answer":"先ほどもご説明申し上げました、そういった関係を明確にした上でしっかり支援していくということで、補助を拡充してきたものです。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"補助制度ができるまでどれぐらい、結構すぐできるのでしょうかという言い方はあれですけれども、それぞれ違うと思うのですが、どういった経緯と時間で大体できるものなのか尋ねました。","respondent":"川島地域活動課長","answer":"１２番から１６番までがもともと補助の制度だったということで、そのほかの支援制度、それ以外の部分を拡充してきたです。それから、区政協力委員会の場などでお聞きしまして、それを予算化していくという作業の中で今のような形になってきたと認識しています。","id":"exchange-017"},{"speaker":"つる副委員長","kind":"確認","question":"この際確認なのですけれども、もしかしたらどこかの予算特別委員会とか決算特別委員会で伺ったことがあったかどうかなのですが、東京都とか。自治体の土地を活用した町会会館、自治会会館の設置というのは、全国で事例はあるのか尋ねました。","respondent":"川島地域活動課長","answer":"全国まで私も承知しておりませんが、現状、品川区については、土地は自治体のものということではなくて、土地を取得しているところが会館を持っているという形で把握しています。","id":"exchange-018"},{"speaker":"つる副委員長","kind":"質問","question":"それは条例上、無理なのか、可能なのかどうかというそもそも論のところを教えていただけますか。具体的には、東京都の土地。","respondent":"川島地域活動課長","answer":"それから、現状の土地の取得に関して、代行したり仲介するということも行っていないところです。ご要望が出てきた場合は、その都度考えていく形になると思いますが、なかなか難しい問題もあるのかと考えているところです。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"質問・要望","question":"町会の方たちで、東京都だったら東京都に直接そういう要望等をすることによって、そういう活用ができるのかというところです。別の機会でいろいろ確認できればと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]},{"id":"topic-03","title":"春季プレミアム付区内共通商品券発行事業への助成","agenda":"春季プレミアム付区内共通商品券発行事業への助成","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"区商連からは１０％に戻してほしいというお話が出たのか、もしくは、また今回も３０％のままで行ってほしいという意見はなかったのか。あったけれども１０％に決めたのだったら、１０％に落とした理由を教えていただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"昨年の９月、１０月ぐらいに商店街連合会と話をしたところですので、とりあえず春については１０％でやらせていただきたいと。状況を見ながら、予算としては１０％でいただいているところではあるのですけれども、また改めて秋に相談しますと言われているところです。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"プレミアム率が、私は前回の３０％、同じぐらい今回もつけてくださいという要望が出ていると思ってしまったのです。だけど、区商連のほうから１０％でいいですという要望があったということを聞いたら、それではそうですよねと言うしかないですものね。","respondent":"遠藤商業・ものづくり課長","answer":"商店街連合会としては、１０％をずっと続けてもらうことをすごく頼りにしているところがあるみたいですので、とにかくこれを継続してもらいたいと。ですので、一時的に上げるというのではないところに重きを置いているということで、今回も１０％という話が出てきたところです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"意見","question":"３０％をもう一回打って、１０％という利率をずっと続けてもらいたいから、そんなにたくさん３０％などしないでいいですよと。その代わり１０％をずっと続けてくださいということなのですねとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"基本が１０％という流れがあるというところから考えて、それが商店街連合会の考えとしてのベースになるところです。３０％という話が出てくる可能性はありますけれども、ベースは１０％ということで、今回はそのベースでやろうという形で話がついたところです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"意見","question":"すごく消費喚起できると思っていたけれども、区商連の方は、そんなにつけないで１０％をずっと続けてくださいというものなのですね。すごく勉強になりましたとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"昨年秋に３０％でやらせていただいて、前回３０％やっているという頭もあるかと思うのですけれども、今回は１０％で大丈夫ですと。２０％、３０％でやっていただけないかという話もあろうかと思いますので、商店街連合会と連携して取り組んでいければと考えています。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"３０％から１０％に落ちることによって、１０％しか出さないのだったら今回はいいというような、まずそこについて伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"商店街連合会のほうで見込んで数字をいただいているところですので、３０％から１０％に落ちる形になるのですけれども、恐らく抽せんになるだろうという見込みです。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問","question":"把握している範囲で構わないのですけれども、前回３０％のときに、申込口数というのでしょうか。１０口申し込もうとした方が、３０％にしてどれぐらい申込みが上がったのかという数字をお持ちであれば、伺いたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"１６万冊、申込みとしては２３万５,０００ほどありまして、結果としては１人７冊ぐらいまでしか購入ができなかったという形になっております。１人８冊までにさせていただいているところですけれども、商店街連合会のほうでは、これでいけるだろうという形で見込んでおります。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問","question":"先ほど藤原委員から質問があったときに、私も伺ってみたいと思ったのですけれども、受け身の立場であるのか。施策としての後押しみたいなもの、それとも、ただ単に受け身での助成という形になってしまっているのか、そこに関しての関わり方について伺いたい。","respondent":"遠藤商業・ものづくり課長","answer":"１０％で予算はいただいていたのですけれども、３０％でできないかというのは、こちらからお話をさせていただいたところです。区のほうで３０％はということでお話ししたところ、商店街連合会のほうも、そういうことでしたらぜひやらせてほしいという話がございました。","id":"exchange-027"},{"speaker":"くにば委員","kind":"提案","question":"今、どういったセクションが話合いをされて、１０％から３０％にしましょうと前回なったのか。そこに関してどういった話合いが区のほうでなされていて、それでパーセンテージを提案するのかという、そこの仕組みとプロセスを伺いたいですとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"一義的に案を決めるのは商業・ものづくり課でいろいろな形で検討させていただきまして、すりあわせていくという形になろうかと思います。そのときには、今回とりあえず１０％でやらせていただいて、そういうところで検討していきましょうという形でさせていただいたところです。","id":"exchange-028"},{"speaker":"くにば委員","kind":"質問","question":"内部のプロセスを伺いまして、一義的に商業・ものづくり課で前回３０％を決めたという中で、秋のプレミアム率についても、商業・ものづくり課のほうで大体いつぐらいに情勢を見極めて、最終的にこのパーセンテージでいこうと区商連に申入れをするのかという、時期に関して伺いたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"今回、また事情が変わりましたので、もう少し早めに商店街連合会に、そういうのを考えておいてというような投げかけは今もやっております。これが落ち着くぐらいのときには、かなり細かい話というか、担当者レベルで意向を確認しながら進めるようになるのかと考えています。","id":"exchange-029"},{"speaker":"くにば委員","kind":"質問・要望","question":"最後は要望になりますけれども、プレミアム率３０％を大変高く評価しておりまして、大変有用な施策だったと考えています。夏、プレミアム率を上げる場合には判断していただきたいと考えていますので、ぜひとも柔軟に前向きに取り組んでいただきたいと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"利用可能店舗のところに、大型店は除くと書いてあるのですけれども、大井町のイトーヨーカドーとか、ヤマダ電機で使えると思うのですけれども、大型店は除くというのはどういう定義なのか、伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"こちらのプレミアム付区内商品券につきましては、先ほどお話のあった店舗では使うことができないようになっております。そのときの商品券は、イトーヨーカドーなどの大型店で使えたことがありますけれども、今回は対象外になっております。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"確認","question":"２０１９年のときにも、国のもの、今課長が説明した商品券という形でいいのですね。そうしたら、品川区のプレミアム付区内共通商品券は、イトーヨーカドーやヤマダ電機は使えないということで、確認させてください。","respondent":"遠藤商業・ものづくり課長","answer":"委員のおっしゃるとおりでございまして、今回は使えないという形になっております。","id":"exchange-032"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後どのようにしていくのかというところを教えていただきたいのと、または、していないのか。どういう人たちがどういう利用をしているというのも、商店街連合会が持っておくというのも、その辺の把握について教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの事業の継続についてのお話ですけれども、こちらは品川区にとっても、商店街連合会にとっても大事な事業だと考えています。以前もご説明させていただいているかもしれませんが、今後もいろいろな形で統計、あるいはアンケートなどを取っていきたいと考えています。","id":"exchange-033"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ検討していただきたいと思うので、考えているのかどうかも含め、ご意見があれば伺えればと思います。","respondent":"遠藤商業・ものづくり課長","answer":"キャッシュレス決済につきましては、商店街連合会でもいろいろ議論されていて、また、私どもも商店街連合会と意見交換をする機会が結構あります。なかなか各店舗の考えとか、あるいは使われる方の考えだとか、いろいろ研究させていただければと考えているところです。","id":"exchange-034"},{"speaker":"大倉委員","kind":"質問・要望","question":"今お話を聞いていて、紙と電子という形で、両方あっていいと思うのです。より利便性の高い、いろいろな人が利用できるプレミアム商品券にしていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"つる副委員長","kind":"質問・要望","question":"１つ確認ですが、４,０００万円分のプレミアム分助成に対して、約半分ですよね。これがプレミアム率が２０％で８,０００万円になったときに、この辺の事務経費がそのまま大体２倍になるのか、この辺りを説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"事務経費につきましては、単純に倍ということではなくて、広告宣伝費はそれほど変わらないかというところでございまして、印刷経費とか、あるいは抽せんを委託しているところがあると聞いておりますので、その辺の管理経費が上がってくるかと考えているところです。","id":"exchange-036"},{"speaker":"つる副委員長","kind":"質問","question":"９掛けというのですかね。そういう考え方なのかどうか、そこを説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"郵便局の販売委託手数料につきましては、こういう形での販売の委託をする場合、全部の郵便局で一律に決まっていると聞いております。最近、値上げなどもあったのですけれども、それにあわせてお支払いするです。","id":"exchange-037"},{"speaker":"つる副委員長","kind":"質問","question":"今回、たまたまプレミアム分が４,０００万円分というだけの話であって、取扱手数料は同じという考え方でよろしいのでしょうか。今回、２０％で８,０００万円だとしても、取扱手数料というのは同じという考え方でいいのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"販売委託に対しての割合という形で聞いていますので、プレミアム率が上がればその分増えるという形になります。","id":"exchange-038"},{"speaker":"つる副委員長","kind":"質問","question":"分かりました。郵便局等取扱手数料になっているのですから、商店街連合会事務局としても販売して、自分のところにも手数料が入るという理解でいいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"商店街連合会でも、発行に関して、別の経費はお店が準備しなくてはいけないので、それに関する経費は区のほうで調整させていただいているです。","id":"exchange-039"},{"speaker":"つる副委員長","kind":"確認","question":"では、もう一回確認しますと、プレミアム分が上がれば、金額に比例して取扱手数料も上がるという。掛け率は同じなので１０％ぐらいということですかね。","respondent":"遠藤商業・ものづくり課長","answer":"今、プレミアム率ですから、販売額の１％という形でやっていただいて……。","id":"exchange-040"}]},{"id":"topic-04","title":"プロスポーツチームの品川区への移転","agenda":"プロスポーツチームの品川区への移転","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"こうしたプロスポーツチームが品川区に移転される経緯、目的を説明を求めました。","respondent":"中元スポーツ推進課長","answer":"この２つのチームを取得といいますか、ぜひ区のほうでも支援をしていただけないかというご相談があったというところ、少し見えてきております。ぜひ品川区としても支援をしてほしいとお申出がございまして、できる範囲でご支援、ご協力をするという経緯です。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"所在地が大井一丁目というのは、もともとここだったチームが、今までは多摩とか柏でやられていたということか尋ねました。","respondent":"中元スポーツ推進課長","answer":"こちらの住所の会社の社長がこの２つのチームをそれぞれ取得されて、また、登記上も品川区内にこのチームの住所を移転するという手続を取られました。それぞれのリーグ側にも届けが必要で、そちらのリーグの理事会で承認がされて、ホームタウンとして移転されたというものです。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。区としては、こうしたプロスポーツチームを積極的に受け入れていくという姿勢や方針があるのかどうなのか、説明を求めました。","respondent":"中元スポーツ推進課長","answer":"その中で基本目標として、誰もがスポーツに親しめる機会づくりということを掲げてあります。様々、区民の方にとってメリットが大きいのかというところで、できる限りの協力をするというお返事をしています。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"今回はこの社長様が買ったというのですか、そういうことになったということですけれども、区としてそういう方向も進めていくということか尋ねました。","respondent":"中元スポーツ推進課長","answer":"社会貢献的な活動をしていただけるのかということで、本拠地が品川区であるというところと両方総合的に勘案いたしまして、その案件ごとに判断をしていくことになります。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういったところでのプロスポーツチームが区内にあるということと、その施設の整備というところでは、区としてはどうお考えか尋ねました。","respondent":"中元スポーツ推進課長","answer":"観客席３００席ということなのですが、総合体育館の観客席は３００席、十分総合体育館で対応ができるです。何しろ今現状の施設でできる限りのことをやらせていただくというお話です。","id":"exchange-045"},{"speaker":"大倉委員","kind":"質問","question":"練習場所も提供しながらやっていくのかと思ったのですが、その辺のお話合いはどうなっているのか。区民のスポーツの利用と併せて、その辺の状況、考え方について教えてほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"戸越体育館も９０％近くいっているところだというお話の前提から始まっております。資料にも書かせていただいておりますが、区と協議を進めていくという、まだスタート地点に立ったです。","id":"exchange-046"},{"speaker":"くにば委員","kind":"意見","question":"Ｆリーグ、そのままではＦ１のライセンスを満たせない状況なのかと思うのですが、そこに関して区ではこのチームとどういう話合いをされているのか。今後、実際にホームゲームを行っていく競技場に関して、どのような話合いになっているのか、お教えくださいとの意見を述べました。","respondent":"中元スポーツ推進課長","answer":"ただ、実際、仮設席を置いてやるにしても、総合体育館は日程が本当に難しいところがあるのです。その辺のところの調整とか、様々課題があるというところは区としても認識しておりますし、それは相手のチームにもはっきりお伝えをしております。","id":"exchange-047"},{"speaker":"くにば委員","kind":"質問・要望","question":"仮設席を含めて１,５００席という部分に関してなのですけれども、１,５００席つくることができるという意味合いなのでしょうか。品川で続けていただきたいという思いがあるので、そこに関してどの程度区のほうで前向きに捉えているのか、お伺いしたいのですけれども。","respondent":"中元スポーツ推進課長","answer":"実際、仮設席を入れて大丈夫かどうかというところの安全性、そちらはもちろん確認した上で、やれそうかというところまでは来ているのです。できる限りの支援ということで考えておりますが、応援をしていただければ…","id":"exchange-048"},{"speaker":"くにば委員","kind":"意見","question":"資料の今後の活動の(2)に書いてあるとおり、そういったメリットはあると思うのですけれども、さらにこういったメリットも生じることがあり得ると。こういったデメリットが生じることがあり得る、そこに関しての見通し、見解を説明を求めました。","respondent":"中元スポーツ推進課長","answer":"やはり施設が競合してしまうというところだと考えていますので、そこで皆さんがそれを超えて、それはメリットに変えていけるのかと考えております。大変多いですので、子どもたちにとっても間近でプロの選手の技術を見ることができるので…","id":"exchange-049"},{"speaker":"くにば委員","kind":"意見","question":"八潮に都内最大級の５面あるフットサルコートがあって、区での成功事例というか、そういったものになり得るのではないかと。品川区の関わりとして力を入れたらどうかと思うのですけれども、そこに関して何かご見解がありましたら、お答えくださいとの意見を述べました。","respondent":"中元スポーツ推進課長","answer":"大人の方でもフットサル人口が実は結構多いと聞いておりますので、そのような方々にもメリットが出せるように取り組んでいきたいと思っているところです。","id":"exchange-050"},{"speaker":"くにば委員","kind":"質問","question":"区内のプロスポーツチームが誕生するに当たって、区のほうと折衝をする必要がマストとしてあるかどうか。そこについて伺いたいです。","respondent":"中元スポーツ推進課長、山崎文化スポーツ振興部長","answer":"今Ｂ３になっていらっしゃるかと思うのですが、練習場所として工場を改造した体育館をお持ちなので、その方々はそこの体育館で練習をされています。全日本代表の選手がキャプテンとして入っているチームがあったりとか… やはりプロスポーツの進展というのは、ほかの例でもそうですけれども、地元の企業との確固たる連携というのが必要になります。一口で言うと活性化ですとか、産業の活力だとか、そういった多方面の効果が非常に見込めるかです。","id":"exchange-051"},{"speaker":"くにば委員","kind":"質問・要望","question":"大井町のリーディングカンパニー、非常に資金力があるチームになったということで報道を拝見しております。Ｕ－２０の経験者のキーパーであったりとか、品川区の名前を全国に売り込むためにも、そこに関してさらに強く推進してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"大倉委員","kind":"確認","question":"確認なのですけれども、応援してもらう土壌づくりというところでは、そういった販売とかはどうしていくのか。その辺の考え方が分かれば、説明を求めました。","respondent":"中元スポーツ推進課長","answer":"支えるという方針が出たときに、見るスポーツということを意識して、既に体育館条例の改正が何年か前に完了しています。そういう形に条例改正をさせていただいてありますので、主競技場に伴うものであれば規定上は物販もできるというところはクリアできているです。","id":"exchange-053"},{"speaker":"藤原委員","kind":"質問","question":"加藤製作所というお名前が出ていたので、今回、この２つのチームを取得された会社の名前はどこですかということです。そういう意味において、なおかつ企業という意味において、どういうつながりでこのようになったという辺りをもう少し詳しく伺えれば幸いです。","respondent":"中元スポーツ推進課長、山崎文化スポーツ振興部長","answer":"１点目で、その方々をやはりできる限りで支援しますというご報告が委員会でされていたのかと思っていたのですが、すみません。平成２８年頃だったかと思うのですが、それほど大きなつながりがなかなか難しかったので… そして、先ほど来課長が説明した経緯をたどって、現在に至ったというようなところです。先ほどのオリンピックのホッケーなども含めて、見るスポーツの充実というところもこういう時代ですが、しっかりやっていこうと思ったところです。","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういったプロスポーツの方々に来ていただいて、そういったところでは、区民が気軽にスポーツを親しめる場が必要になってくると思うのです。気軽に親しめる場所が必要になってくると思うのですけれども、そういうところでの区の考えをお聞かせほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"ただ、教育委員会のご理解もあって、学校の校庭や体育館も一般開放が進んでいるところです。そのときにまた区民の皆さんの様々なニーズやご要望の盛り上がりによって、区としても考えていまいりたいです。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、気軽に子どもたちも大人も高齢者もみんなが使える場所と料金という考えで、ぜひ今後も進めていっていただけたらと思います。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"くにば委員","kind":"確認","question":"１点だけ確認したいのですけれども、こちらに関して予算が約６００万円、品川区として費用が発生する部分というのはあるのか尋ねました。","respondent":"篠田文化観光課長","answer":"こちらに関しましては、実施までの準備等の経費がありますので、仮に中止になった場合には、その時点で使った経費分、こちらのほうをきちんと精査した上で、精算をしていくということになってくるかと思います。","id":"exchange-057"},{"speaker":"くにば委員","kind":"質問","question":"行政としてリスクを考えて、事業者はやりたいけれども、区が今回はやめましょうという形で強く言っていける立場なのかどうか。そうではなく、一方的に品川区の財政としても費用が出てしまう部分があると思うので、そこに関しての事業者の関わりに関して伺いたいのですけれども。","respondent":"篠田文化観光課長","answer":"今回の催物につきましては、区と財団とが共催という形で、両方とも主催者の立場であるです。きちんとした整理をしながら、協議をしながら、考え方を整理していきたいと考えているところです。","id":"exchange-058"},{"speaker":"くにば委員","kind":"質問・要望","question":"そこの見極めで中止をするのであれば、中止という判断は難しい中、きっぱりと区民の安全というのを第一に考えてほしいと求めました。以上、要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2894#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":41957,"voices":152}},{"id":"r03-20210419-7","meetingId":"r03-cm04","date":"2021年4月19日","dateIso":"2021-04-19","committee":"厚生委員会","time":"午後 １時００分～午後 ３時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"結構重度の方も受け入れて、今現在、実際に重度の方が入っていらっしゃるのでしょうか。その辺の現状を、ほかのところも含めてお伺いしたいと思います。","respondent":"松山障害者福祉課長","answer":"実際に何をもって重度という定義をするのかというのが一つありますけれども、区立の中でも、愛の手帳２度の方の受入れをしているところはあります。それから、金子山の状況ですが、現在も愛の手帳２度の方はお一人いらっしゃるという状況です。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"金子山は今も１人ということですけれども、ほかのグループホームでは今、例えば愛の手帳２度ということでいえば、何人ぐらいなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"愛の手帳につきましては、１０人弱ということになっております。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"基本的なところを教えていただきたいのですが、重度の受入れというものの制度的な仕組みを教えていただきたいのと、区の区分の実態ということについても教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"平成３０年４月１日から重度化・高齢化に対応できるグループホームの新たな類型として、日中サービス支援型というグループホームが創設されました。その中で重度の方に対応しているグループホームもありますので、今現在、研究しているという段階です。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"日中サービス支援型というのは１８２ということで、ただ、重度の方を受け入れるというのは経営的にすごく大変だという話も伺ったのです。例えば夜間とか、その辺りの重度の方を受入れる場合の課題というのを、どのように考えられているのかについてもお聞かせいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"実はこの４月の報酬改定で、重度の方に手厚くということで、国も少し日中サービス支援型の報酬を見直したというところがあります。日中サービス支援型では経営が成り立たず、日中サービス支援型の、状況について調査をしている段階です。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"３対１から５対１まで、重度の方のグループホームができたというのを伺ったのですが、そういう他区の状況とかも併せて教えていただけたらと思います。これを見ていたら、支援区分４以上の方を重度ということで考えるとか、そういう考え方というのがあるのかについても教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"夜勤対応、あるいは、重度の方であれば支援の程度が高くなるということがあります。逆に軽度の方であっても、利用を見送ったりすることもあるですので、一概に区分で全て判断するというところは難しいかなと考えています。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは１９床ということで、そのうちショートステイが３床ということなので、せめてそういう形が必要なのではないかと。区が関わって運営していくというのが必要になってくるのではないかと思うのですけれども、その辺の考え方についてもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"運営法人の支援の程度の状況等々もありますので、その方々を安定して支援するというのをまず第一に考え、申し上げられない状況です。それから次に、西大井三丁目ですけれども、区が土地を取得していくということで、こちらは指定管理の方法を考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"西大井三丁目のところは指定管理ということで、よかったなと思います。この１か所だけではとても足りないというのが実態だと思いますので、そういう方法で重度の方も入れる、今後ぜひ増設をお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。引き続きお願いしたいと思いますが、本陳情に関しましては、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"意見","question":"先ほどの質疑のやり取りを聞いていて、重度障害者の方も入居対象になっていると。数の多寡というところはあると思うのですけれども、そこについてはなっているという現状も承知いたしましたので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問・要望","question":"今の説明で、むしろつくっていただきたいという観点から、このような陳情を採択する意義は非常に大きいと思います。積極的に採択したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"今の説明をお聞きして、総合的に判断して、民間事業者で受入れているということで説明がありました。ということですので、重度の方も入っていらっしゃる例も聞きましたので、この陳情に関しては、不採択ということでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]},{"id":"topic-02","title":"生理用品を配布「優しさをかたちにプロジェクト」","agenda":"生理用品を配布「優しさをかたちにプロジェクト」","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"一つは周知方法ですけれども、ホームページやツイッターなどでということですが、広報でも周知はされたのでしょうかということが第１点。いかがお考えでしょうかというか、その２点、お願いいたします。","respondent":"菅野高齢者地域支援課長","answer":"その後急ピッチで作業を進めて、４月６日から配布開始としたところなので、広報の掲載に間に合わなかったというところが実情です。今回は緊急での対応ということで、そこが終わり次第終了という形になっております。","id":"exchange-012"},{"speaker":"おくの委員","kind":"質問","question":"あるいは、お考えになっているのではないでしょうか。いかがか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"今回、生理用品の配布ということで、３月の予算特別委員会でもいろいろと取り上げられ、社会的な大きな問題として報道されたと認識しております。日々在庫の管理とかもさせていただいて、その状況とかも確認しながら、今後どうしていくかを検討させていただいている次第です。","id":"exchange-013"},{"speaker":"おくの委員","kind":"意見","question":"そうなれば、それこそ広報での周知とか、そういうことも併せてお考えほしいと求めました。お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"今回、今ご答弁のあった課長がリーダーとなってやられているのでしょうか、これはプロジェクトチームも解散してしまうということなのでしょうか。そこのところは今後、どのようにお考えになっているのか、伺いたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"違うところに事務局として置かせていただいて、こういった事業を進めていくのかについても含めて、検討していくことになるのかなと思います。今は生徒の様子とか、その辺りについても今後、続けていくかどうかということは検討課題となっていくのかなと認識しております。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回可視化されて、今後行政として支援すべきものなのかというところも、しっかり検討してほしいと求めました。取りに行かれた方のお話も伺いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どう取組むべきものなのかというところで、プロジェクトとしてどのような議論がされているのかという点についてもお聞かせほしいと求めました。スコットランドでは今年１月から、私は本来、プロジェクトとしてはどんな議論がされているのかということについてもお聞かせいただけたらと思います。","respondent":"菅野高齢者地域支援課長","answer":"集まった際には、プロジェクトの名前を考えようというところから始めまして、こちらの名前もメンバーのみんなで出し合って考えさせていただきました。プロジェクトのメンバーの１人がロゴを考えまして…","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"引き続きやっていただきたいと思うのですけれども、必要な人には学校でいつでも無料で配布するという体制を取ることが必要なのではないかと。そういうところの解決までしていただけたらいいのではないかと思うのですけれども、その点についてもお聞かせほしいと求めました。","respondent":"菅野高齢者地域支援課長","answer":"学校側から、今回のプロジェクトで学校のトイレに生理用品を設置することに当たっての手紙を、保護者の方にも出しているとは聞いております。少しでもそういった、担任の先生に話したりということにつながればいいのではないかということで…","id":"exchange-018"}]},{"id":"topic-03","title":"を再度、聴取いたします。 冒頭に申し上げましたように、取り上げる順番を変更し、(3)新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"を再度、聴取いたします。 冒頭に申し上げましたように、取り上げる順番を変更し、(3)新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今年に入ってからのクラスターの発生というのは、どこでどのくらい発生しているのでしょうか。１番の（６）高齢者等施設へのＰＣＲ検査ということで、たしか、新規入所者の方への実施というのは予定されていないということなのか尋ねました。","respondent":"鷹箸保健予防課長、宮尾高齢者福祉課長","answer":"これまで昨年の２月から対応させていただいた数で、これまで１１４件、医療機関等の順になってあります。１月以降新たにというところもありますが、継続して対応している施設もあるという状況になります。 ただいまこちらの予算を活用させていただいて、さらに従事者の方の検査をする方向で検討しています。なお、東京都の補助制度等が先週あたりからようやく見え始めてきたというところもありますので…","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"検討するということは、やると理解してよろしいのでしょうか。その趣旨が壊れてしまうと思うのですが、その点、いかがお考えか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"例えばその方がもともと個室に入る予定の方でしたら、健康状況が把握できるまで、ほかの入所者との動線が交わらないようなケアもしています。こういったことも対応させていただいているところですので、従事者をベースに…","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"私からは１点だけです。様々な情報の中で、何かそういう兆候とか傾向とかがあるのか、またそういうのは保健所でつかめるのかどうかというところも含めて説明を求めました。","respondent":"鷹箸保健予防課長","answer":"実はまず国に行きまして、そこから東京都に戻ってきて、検査番号等から品川区の患者と分かった場合には戻ってくるという流れになっております。例えば１日１０人のうち何人といった形の正確なものはありませんが、我々が今、地元の保健所として把握できるところになります。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"第４波ということで言われたりしているわけですが、重症化もしやすかったりということで報道されておりますけれども、まずお聞かせいただきたいと。先ほど５名以上のクラスターというのが３４件ということだったのですけれども、今年の感染の特徴みたいなのがあったら教えてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"あるいはお子さんの感染者は変異株が多いとか、そういったところまでの具体的な内容については、それほど感じていないということになります。５名以上というものは、頻繁に検査をしたりということで、広がらないように適切な対応を保健所では取っております。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"第４波というところで言われるような状況に対して、どういう対応ということで考えられているのかという点についてもお聞かせほしいと求めました。今年の３月までにということで国から求められて、７,０００人にされたと思うのですけれども、その点についてもお聞かせほしいと求めました。","respondent":"鷹箸保健予防課長、宮尾高齢者福祉課長","answer":"クラスターに関してのお尋ねですが、委員が先ほどお話しになったとおりで、今年度に入ってから、高齢者施設でのクラスターについては起こっておりません。 ３月に行わせていただきました介護・障害福祉サービスの従事者の方に対するＰＣＲ検査の実施状況ですが、最終的に検査をお受けになった方は４,５１３人、うち陽性となった方が４名です。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"職種も含めて教えていただきたいのと、かなり改善されたという実態になっているのか、その辺の実態も含めて教えていただけたらと思います。今東京都で、そして実態はどんな状況になっているのか、東京都のＰＣＲ検査の方針に対しての品川区の実態について教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長、鷹箸保健予防課長","answer":"２回目のＰＣＲ検査の実施状況ですが、７,０００人ということで、障害サービスに携わる全スタッフの方で想定をしておりました。それから、検査を受けることの趣旨を何回かにわたって説明させていただきましたが… 感染症の対応をしている職員につきましては、これは結核も含めてですが、会計年度任用職員は１人から１人ということで変わりありません。新型コロナを経験していた職員が１人だけだったということもありまして、保健師も含めまして…","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"まだこれから第４波との戦いが来ると思いますので、休みなく夜中までということがない体制を、ぜひ取ってほしいと求めました。東京都が１週間に１回という、第４波をどう封じ込めていくかというところでは、ぜひそういう対応をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]},{"id":"topic-04","title":"東京都特定不妊治療費助成事業の拡充に伴う対応","agenda":"東京都特定不妊治療費助成事業の拡充に伴う対応","exchanges":[{"speaker":"西村委員","kind":"質問","question":"大きな前進だと思うのですが、男性の不妊治療に関して、なかなか進まない。少しずつできないかなと思っているのですが、ご意見はその辺り、いかがか尋ねました。","respondent":"高山健康課長","answer":"まさに女性のほうに何か問題があるという誤った認識が実際ございまして、それぞれの割合としては５０％・５０％ということで言われております。区といたしましても、そうした正しい認識が広まるように、広報については様々工夫してまいりたいと考えております。","id":"exchange-026"}]},{"id":"topic-05","title":"東京都の高齢者肺炎球菌ワクチン定期接種補助事業の実施に伴う対応","agenda":"東京都の高齢者肺炎球菌ワクチン定期接種補助事業の実施に伴う対応","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"２番の対象者の高齢者、括弧の中の「ただし」のところは、生活保護受給者ですか。〔「補助になっている」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これまで自己負担は４,０００円ということでしたけれども、４,０００円の自己負担になっていたのかについてもお聞かせほしいと求めました。５歳のところで受け忘れた方のワクチンも、品川区が補助するという仕組みになっていたでしょうか、その確認を教えてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"令和２年につきましては、令和元年度の１.３倍に当たるおおむね２３.６％の接種率になるであろうということを現在見込んでおります。同じ自己負担額で接種できるように、品川区といたしましては、任意の予防接種の助成事業を実施しております。","id":"exchange-028"}]},{"id":"topic-06","title":"新型コロナウイルスワクチン接種","agenda":"新型コロナウイルスワクチン接種","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"封筒まできちんと画像が載っているというところもありましたので、ぜひそれはお願いしたいのですが、いかがでしょうかというところが一つ。予診票に書くところがあったのは確認したのですが、私の中で確認できなかったのですが、そこについての確認をさせてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"同封物等々についてのホームページの公開については、準備・検討を進めさせていただきたいと思いますので、よろしくお願いいたします。画面上で警告というか、基礎疾患がある方のみの予約期間ですというものを１枚入れるか、その辺りで最後の調整を進めているところです。","id":"exchange-029"},{"speaker":"西村委員","kind":"質問・要望","question":"教えていただきたいのと、東京都に確認をしたり、何かしら確認をするようなことはあるのかというのを伺いたいです。２、３と書くのか、その辺りもお伺いさせてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"どちらもゴールデンウィークの対応はできないということで、品川区は対応ができないということでしたので、一つ予想ができたことです。２点目、まずはそこで、こちらから周知を進めていきたいと考えております。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"ちょっと気になったのが、初日の９時から始めるというときに、ネットも初日の９時ですか。お考えがないようだったら、そこをしっかり考えていただきたいと思うのですが、いかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"こちらの予約開始時間は、もちろん広報でしっかりとお示しすることと、電話とウェブの予約開始時間は、ずらして進めていくことを想定しております。検討を進めておりますが、仮に９時から開始とすると、調整と準備を進めているところです。","id":"exchange-031"},{"speaker":"渡部委員","kind":"質問","question":"多分、具体的な数字というのをどういう形かでお示しすることによって、しようがない」と思っていただくような仕組みが必要なのではないかと。そういう努力が必要だと思うので、これは別に答弁は結構ですが、そのような工夫もされてみたらいかがでしょうかということだけ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そもそも１箱が来ることになっていて、品川区としてはその１箱ということで確認のボタンを押した。接種する意欲がどうみたいな誤ったイメージを、そして何箱来るという仕組みなのかということだけ、教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もともとの登録数は、４月２６日の週の分に関しては、品川区は１で登録をいたしました。今後、５月１０日・１７日の週に来るもの、先ほどの４、５０を想定しているというものに関しましては、それ以上の箱数を登録する予定です。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、ご説明いただきまして、先ほどの接種を想定した数を要求していくということを伺いました。これは要望です。","respondent":"秋山保健整備担当部長","answer":"ある程度のワクチン量が見込めるという状態で集団接種を始めるというのを決定しておりましたので、来週から使える２箱、今回こういう形になった。３箱という配分、上が４７で下が３という非常に分かりにくい配分というのは、その辺は今後改善できるのかなと考えています。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"４、５０箱来れば十分間に合うのだということですけれども、５月２４日よりも早く接種が始まるという体制でやっているということなのでしょうか。ほかの区との接種の開始時期の違いというのはどうなっているのか、聞かせてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"区によって開始時期は異なります。全ての区が何月何日からということを、こちらで把握しているわけではございませんが、確かに１週間ほど早く始まるところはあると聞いております。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"５０箱で、４週間にわたって２０箱ぐらいずつ来て、それで７５歳以上の方の接種が終わるというスケジュール感でいくのでしょうか。そういう体制というのは、どういうところからどれぐらいの体制が確保できているのか、その点についても説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"実際は１３日以降に到着するということを見込みまして、まず２５回線の体制を整えようということで、今現在は動いております。調整を進めているところですので、うまく足らないところを補充できればと考えておりまして、調整を進めているです。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"医師会２つは６月以降ですけれども、それ以外のところ、７か所は一斉に５月２４日からやるわけです。１日何人くらいまで１か所でできるのかということで、どういう形で進んでいくのかというのが見えるような形でご説明いただけるとありがたいですとの意見を述べました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"大体ドクター２名ほどを標準の形として現在は考えて、調整を進めておりまして、現在シミュレーションをしております。その辺りは今後の様子を見ながらとは考えておりますが、数を少し調整しながら進めていくのが妥当かなというところで、今お話を進めているところです。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"４月２６日からの高齢者施設で１,０００人分、グループホーム、それから特定施設というところで２,５００人ということになってくるのでしょうか。そして、その体制も、まずは４月１９日、どれぐらいの体制でやっていくのか、その辺りのイメージができるように教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"初めてのことなので、本当に様々なご苦労があるかと思いますけれども、よろしくお願いしたいと思います。一番最後の１２番の、まだワクチン接種になっていないと思うのですけれども、その辺の品川区の見通しというところも教えていただけたらと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"このワクチンは、まず打ちなさいというルールというか指示がありまして、それで各病院が大体打ち終わってきているという話も聞いております。両医師会館に打ちに行くとか、そういったことで来週あたりから準備が進んで…","id":"exchange-039"}]},{"id":"topic-07","title":"出産応援事業（ギフトカード配付）","agenda":"出産応援事業（ギフトカード配付）","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"妊娠した場合の１万円のカタログギフト贈呈というのを、妊娠した場合の事業については、これとは別に継続して行うのかどうか。そうすると、妊娠時と出産後で１１万円ということになるのですけれども、継続されるのか、そこだけ確認させてください。","respondent":"柏木品川保健センター所長","answer":"今行っているカタログギフト１万円分につきましては、継続です。","id":"exchange-040"},{"speaker":"西村委員","kind":"質問・要望","question":"実際にホームページに掲載される際に、里帰りの場合で希望される方ですとか、あと、理由があって配偶者から離れて生活しなければいけない方の場合の申込みの手続きなども、細かくフローを示していただきたいと思うのですが、その辺りはいかがか尋ねました。","respondent":"柏木品川保健センター所長","answer":"こちら、区のホームページは基本的なものでつくりまして、そこから、都のほうに詳しいものがありますので、そちらに飛ぶようになりますが、そちらのほうには里帰りでの配送先の変更ですとか、いわゆるＤＶ避難の関係の申請の仕方等もご案内しています。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"ずっと私たちも提案していたところだったので、私はずっと継続していただきたいと思うのですが、その点について説明を求めました。","respondent":"柏木品川保健センター所長","answer":"２年間の意味というのは、コロナ禍でも子どもを産み育てる家庭を応援、後押しするという部分で設定したものと考えています。すみませんが、都の事業ですので、ここまでしか分かりません。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"都のほうにも継続を求めてほしいと求めましたし、区としても継続していただきたいということで、要望をさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3592#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":43556,"voices":151}},{"id":"r03-20210419-8","meetingId":"r03-cm04","date":"2021年4月19日","dateIso":"2021-04-19","committee":"建設委員会","time":"午後 １時００分～午後 ６時０８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を129件整理しています。","topics":[{"id":"topic-01","title":"(1)から(16)に記載の請願・陳情１６件につきましては、予定表３、報告事項、(1)第３回 羽田新経路の固定化回避に係る技術的方策検討会","agenda":"(1)から(16)に記載の請願・陳情１６件につきましては、予定表３、報告事項、(1)第３回 羽田新経路の固定化回避に係る技術的方策検討会","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"そして区民投票や区民意見の把握の機会を求めるものと、騒音測定装置の設置についての要望といったことなのですけれども、そこら辺について委員長に確認をとりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"要望いたします。先に制度の確認をしたいのですけれども、次の５月の委員会で、もう１回審査がされるのかどうかというところを先に伺ってもいいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"次の５月に継続となった請願・陳情については審査を行わないから、この請願・陳情は流れてしまう、廃案になってしまうということですよね。確認させてもらっていいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"田中委員","kind":"確認","question":"では、継続になった場合に、６月からの新しい委員会で、再度、請願・陳情がまた審査され、賛成・反対をとられるということでよろしいですか。ごめんなさい、確認させてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"６月以降の新しい建設委員会のメンバーで、継続審査になった請願・陳情が審査されるかどうかは、新しい委員長が決定するということでよろしいですか。今、違うといった声も聞こえてきたのですけれども、ちょっとそこがきちんと確認できないとと思っておりまして、確認させてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"次の委員長によってですけれども、きちんと継続されて、委員から求めたりすれば、とにかく廃案にはならないということでいいですか。そこの確認だけさせてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"田中委員","kind":"確認","question":"それとも電話、メールか、国から区への報告の方法について伺いたいと思います。報告を受け、区としてどのような認識を持ったのかということも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"第３回の固定化回避検討会の開催のお知らせですが、ちょっと正確な日付はあれなのですが、本当に直前であったというふうに認識しております。この３回目の結果の区の受け止めですが、当初、国から説明があったとおりの内容の取りまとめが行われたというような受け止めです。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"都市上空、特にこの品川区上空について固定化回避されるかどうかという確認は、区として行ったのかというところを確認したいと思います。ですので、いつまでに結果を出すようにとして、ぜひ区として期限を求めるべきだと思うのですけれども、そこのところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"国の資料の説明の中にありますが、短期・中期・長期に対する対応策ですとか、国としては行っていると。今回の３回目の（検討会の）結果を受けて求めてきているところでありますし、今後も求めていきたいです。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"これまで求めてきているといったことでしたけれども、確認はしていないということですかという確認と、あと。期限についてきちんと示すべきだと思うのですが、そこのところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"そういう意味では、区部で飛ぶ１９区の中でも一番低空で飛ぶわけですから、検討していただきたいということを求めているわけです。それから、第３回の検討会の前に、事前に資料の中身についての説明があったかということでのご質問だと思うのですが……。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"例えば、せめて３か月に１回などの機会でも開いてほしいなどといった要望もできるのではないのかと思うのですけれども、見解を伺いたいと思います。区として、固定化回避されそうだという実感を持ったのか、そこのところについて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"この３回目の結果を受けての区の認識ですが、先ほど説明もさせていただきましたが、各飛行方式の絞り込みが今回行われたです。技術的選択肢となり得るかという絞り込みが行われたということですから、検討は着実に進んでいるというふうな受け止めです。","id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"私が伺ったのは、固定化が回避されるのか、そこのところをお知らせほしいと求めました。確認します。","respondent":"鈴木都市計画課長","answer":"その課題への対応だとか、対応策の検討を行って、更なる絞り込みを行っていくと。さらに今度は次のステップとして絞り込みが行われて検討が進めば、さらにそこで、地上というか。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"今のご答弁だと、では、もう品川区の上空は通過するということは区としても認識しているということでいいか尋ねました。","respondent":"鈴木都市計画課長","answer":"これが固定化しないように検討をしていただきたいというふうには伝えているわけですから、それが固定化しないような検討を、今。今回の検討は、この２つのルートは全く変わりませんと、どういうルートが可能なのかというのはこれからだというふうに聞いているところです。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"やっぱりこの検討会で今検討されている飛行方式について専門家の方にお話を伺ったときに、その専門家の方が国土交通省の前でも質問をしています。最初に求めてきた検討会の形と変わってきているのではないのかと思うのですけれども、そこのところについても伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"この固定化回避に向けて今やっていただいている検討を、最後、これは本当に早く示していただきたいというふうに思っています。地図に、これは常々、３回目の（検討会の）結果を今すぐ地上の図面に落としていただきたいということで申し上げているわけでございません。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"描かないのはなぜですか。品川区の上空を通りますよということを言っているに過ぎないのではないか尋ねました。","respondent":"鈴木都市計画課長","answer":"これから検討を進めていく中で、これは当然ながらないがしろにできるものではなくて、まず第一に考えなければいけない。そうしたところを期待して、固定化しないで検討していただきたいということは、これは言っているです。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"本当に区民の皆さんの安全を確保したいと思うのであれば、はっきりと、この不明確なところは聞くべきではないでしょうか。それはいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"それから検討を進めていく中で、飛行運用の安全性というのは、これはもう第一に考えていただかなければいけない内容です。この資料にあるこうした不安要素といいますか、まだ決まっていないところの対応はしっかりとっていただいた上で検討を進めると国は言っていますので。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"今後の検討方向性という資料５の中に、いいですか、「Ａ・Ｃ滑走路への同時進入時の運用ルール」と書いてあるのです。だったら、品川区民の方たちを危険にさらさないということにするには、区としての意思表示はしっかりすべきではないか尋ねました。","respondent":"鈴木都市計画課長","answer":"ご紹介いただいたように今の２ルートを固定化しない検討ですので、検討会の立ち上げから言っていますので、私がご説明したメリットとして。今後検討していただけるというふうに理解していますので、区としては、この検討の動向を今後も注視していきたいです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"区として、この距離というのは、直線というのはどのぐらい必要なことなのでしょうかという技術的なところが分からなければ聞けばいい話です。ぜひその確認をしていただきたいですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"まさに委員がご指摘いただいた点について、少しでも知りたいところです。今現在、今後こういう方向性で検討を進めていきたいというところで、この先の検討の中で進んでいく内容だというふうな国の回答です。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"要は、品川区の上空を通らないというふうなことも考えた固定化回避という会議として区民の皆さんに紹介しているのだとすれば、大間違いですから。そこをはっきりしていただきたいのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"この都心上空を飛ぶ２ルートが固定化されることがないように、やはり検討を行っていただきたいというところで、区としては求めているです。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"であるならば、固定化回避という意味として、こういうことを区は国土交通省に求めていますよとはっきり提示してください。決して品川区の上空を通らないようにするためのルートを検討するための会議ではないということを明確にしていただくように強く要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"１,０００ｆｔ、高度約３００ｍの直線進入が世界の大型空港では大体必要だということで、実際にそういったことがあるのかどうか伺いたいと思います。先ほど、それはまだ確認されていないということでしたけれども、ぜひそれは私からも確認することを要望したいと思います。","respondent":"鈴木都市計画課長","answer":"一刻も早くこの検討結果について、具体的に地図上で示していただけるような早急な取組みを進めていただきたいというのは、今後も求めていきたいです。技術的選択肢を検討している段階で、地図上でどこを通過するか等の検討の段階ではないというふうに言っていますので…","id":"exchange-020"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"それは先ほどの直線距離等も関係してくる問題だと思うので、ぜひそれは確認をしていただきたいというふうに思います。ぜひ滑走路の変更を行っていくということで、区としても要望していただきたいというふうに思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"現在の滑走路の運用を前提としつつというところで検討が進められているというところで、今後検討が進む中で、今現在のところは考えてございません。このどれが短期で対応できて、どれが中期で対応できて、この短期・中期・長期という形で示しているというような回答でございまし…","id":"exchange-021"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"いかがでしょうかということと、区は求めないということですけれども、区が求めている。ＩＬＳなどで、今飛んでいる飛行ルートで結局飛んでくることになるということになってしまうと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"対応機材の割合ですとか、あるいは訓練実施率ですとか、これは資料５のほうにも今後の検討の方向性として。１００％なのか、どういう課題の対応策への検討が行われるかということにもなってくると思うのですが、区としては注視していきたいです。","id":"exchange-022"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"この固定化回避検討会に滑走路の使い方を求めていくことが、やはり一番現実的に品川区の上を飛ばないルートにしていくということになると思います。私はそれは期待できないと考えていますので、ぜひ滑走路の使い方を変更するように要望していただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"きちんと地図に落とすようにというのを必ず求めていただきたいということと、あと、また。区としても、そのように求めるべきなのではないかと考えますが、伺います。","respondent":"鈴木都市計画課長","answer":"それは、これも検討を早急に進めて一刻も早く示していただきたいというのは、今後も求めていきたいです。検討会を開催している間、これは昨年の５月、今後も新ルートは継続していきたいという回答です。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"検討会の期間中に飛行させないように求めてほしいと言ったときに、それは、今この期間に練習をしているということですか。そこの認識を改めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今現在の３回目の検討結果を示していただくというよりも、区として、この検討結果を研究して地図に示して区民にお示しするということなのでしょうか。これはやはり国の事業ですので、それについていち早く結果を、検討を進めていただきたいと求めるのが今の区の姿勢だです。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"区民を守る、区民の生活、命を守る自治体として、研究はすべきだと考えますが、伺います。検討会についての説明は、今、区民に対してチラシを配布しているだけですので、求めていただきたいと考えますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"やはり区がとるべきことは、その検討をいち早く進めていただいて区民にお示しいただくというところが区の役割だというふうに考えてあります。検討会の内容も含めた説明会の実施については、新聞への折り込みですとか、国のホームページも充実してきたところは見てとれてあります。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"この検討会期間中は飛行させないように求めるべきではないかという、区のご答弁がなかったので、そこについて確認したいと思います。事故に対するの要望書のことなのですけれども、こういった事故が起こらないとは限らないので、品川区も改めて強く求めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"区として、国にもっと、今の期間だけでもせめてやめることはできないかということを強く求めてほしいと求めました。これは強く要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"ご質問がないということであるならば、これから採決というか、これで結論を出すかどうかという話になるのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"西本委員","kind":"確認","question":"ちょっと棚上げになっていることがたくさんあって、どういう考え方でジャッジをしていいのかというのをまず確認したいのです。先ほど、廃案にならないというのは、今期は廃案にならないという意味であるわけですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"西本委員","kind":"確認","question":"改選したら、改選した後も、これは継続ということなのでしょうか。そこをまず確認させてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"今期の私たちの考え方として、次の委員会に継続して審査をしていただきたいということをまとめていくべきなのではないのでしょうか。そこも含めての態度表明であるべきだと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう理由をもって積み上げとしていくのかというのは、建設委員会のメンバーとしての意思表示をまとめるということは必要だと思います。いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"この落下物事故１つをとっても、私は中止にすべきだというふうに思っておりますけれども、落下物ゼロにできるのかというところで伺いたいと思います。随時知らせていくべきだということで求められておりますけれども、住民によく理解してもらうということが必要だと思いますので、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"やはり公共施設に設置すると、無人で設置することになりますから、第三者が触ったりできないような場所への設定ということも考えなければいけない。あるいはオープンハウス型の説明会が開かれましたが、私の認識しているところでは…","id":"exchange-034"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"区としても求めているということですので、さらに求めていただいて、国が示さないところはぜひ区が示していっていただきたいというふうに思います。区として、この区民の安全が区の重大な命題だというふうにお考えなのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"しっかり継続して、さらに取組みを進めていただきたいというところは、今後も強く求めていきたいです。","id":"exchange-035"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"この教室型説明会をこれまで求めてきたということでおっしゃっていましたが、品川区が教室型説明会を求めているのか、伺いたいと思います。こうした意見を聞く場を国につくってほしいと区として要望しているのか、区独自にも実施すべきだと私は思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"ご紹介いただいた教室型説明会が決定前に区として様々な手法の中の１つとして求め、継続して６回目のオープンハウス型の説明会ですとか、２月ですか。今後も区としては、継続して周知、説明を国に求めていきたいです。","id":"exchange-036"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"陳情でも教室型説明会が求められておりますので、それもぜひ求めていただきたいということで、改めてご答弁がありましたら伺いたいと思います。心身への被害もあると思いますが、そういった被害額を計算されているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"住民への説明、周知ですが、再三になりますが、手法を限定せずに様々な手法を活用して、国にはこれからも説明、周知を求めていきたいです。運用開始以前もいろいろな説明資料に目を通しておりますが…","id":"exchange-037"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"区民投票を実施してほしいという陳情も出されておりますけれども、今回、いかがでしょうかということを聞きたいのですけれども。現在の飛行便数とコロナ前との比較、何割減っているのかということが分かれば教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"区民投票条例のお話の、仕組み上、再度できるかというところにつきましては、私の所管外ですので、答弁できないところです。４月からを見てみますと、昨年１２月ですと、当初の想定から約４８％減というような状況です。","id":"exchange-038"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"今こそ、この羽田新ルートに反対を表明して中止・撤回を求めていくべきだと思いますけれども、いかがでしょうか。やはり区議会としても表明していくべきだと考えますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"特にコロナ禍における考え方については、固定化回避に向けた取組みをさらに加速していただきたいというところは、今後も強く求めていきたいです。","id":"exchange-039"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"品川区は最も被害が大きな自治体の１つですので、区として中止を求めていくということが、今こそ必要だというふうに私は思います。そのことは強く要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"これまでも区に寄せられた羽田新ルートに関する意見などについて、毎回報告をしてほしいということを要望していました。なぜ今回、ほかの資料は示されても、区の状況の説明のときに口頭説明だったのかということをお知らせいただけますか。","respondent":"鈴木都市計画課長","answer":"冒頭の説明の中で、今回限られた時間の中で、請願・陳情も継続分を含めると１６件ですか、そうした中で、すべてではございませんが、必要な情報を口頭にはなりますが説明させていただいたです。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"限られた時間ですので、口頭での説明ではなくて、きちんと資料提供してほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"中には３０分ですとか、４０分ですとか、電話でいただく場合もありますが、できるだけそこを要約せずに直接国に届けることを行っているところです。この議会の場等でそうしたすべてをご説明、ご報告するという予定は今のところございませんが、検討。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"２７６件の寄せられた意見について、そういったデータを集めていると思っていたのですけれども、データの蓄積はしていますよね。それについてお知らせいただきたいのと、区議会……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"きちんと、今こういう声が届いていますといったことの公表とかも今後はしてほしいと思うのですが、いかがでしょうか。それについての見解を伺いたいというのと、委員間でもいろいろお話ができればと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"研究ではなくて、区民の関心がとても高くて、わざわざその区民の声に押されて、区もそういう部署を設置したのですから、きちんと毎回報告をしてほしいと強く求めますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"いただいたご質問について、今後研究してまいりたいです。","id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そのときは２４時間になってしまうのではないですかとか、いろいろな議論があったけれども、そのときには、実質３時間ですと。固定化回避、それは我々は決議もしているわけですから、それをもっと固定化回避に向けてやってくださいというお願いもさらに強くしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"若林委員","kind":"質問・要望","question":"改めてこれは確認をして、または確認をしていく、これはずっと続けていっていただきたいということを申し上げておきます。この検討会を立ち上げていただきたい、固定化を回避していただきたい、今はしっかりと注視をしていくということだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"大沢委員","kind":"質問・要望","question":"令和２年５月２０日ということで、「羽田空港の機能強化に関する要望について」、つぶさに載っております。先ほど来の「羽田空港の機能強化に関する要望について」をよりどころにしながらやっていただいているということは。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"私たちも住民の皆さんと共に、国土交通省に様々要望を繰り返してまいりました。以上のことから、羽田新ルートは中止にすべきだと考えますので、採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"令和２年請願第３号は、区が国へ新ルートの撤回を要請するよう求める請願です。思いは一緒だと確信しました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区の上空を飛ばないということは決して言っていないわけですから、そういう期待とかをさせないようにしなければならないのではないでしょうか。私は強くそれを求めていきたいと思いますが、この令和２年請願第３号については、採択という形でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"若林委員","kind":"質問","question":"説明会についてさっきは言いませんでしたけれども、いろいろな手法があって、コロナ禍で、教室型という限定的に言及することも、それは不適切であるというふうに思いますので、結論を出すで、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"説明会を求めるものですので、羽田新ルートが実施されてから１年が経った今、十分に時間をとって住民の声をよく聞くべきだと考えます。採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっと質問したかったのですけれども、改めて確認をさせていただきたいのですけれども、そこも確認をさせていただきたかったと思います。申し合わせ確認事項の中にはなかったのですけれども、そこのこともお知らせほしいと求めました。","respondent":"塚本委員長","answer":"田中委員、その件については、別途、事務局等に聞いていただければ分かると思いますので、この場ではご意見だけで。今は請願・陳情の取り扱いについて議事を進めておりますので、ご協力をお願いします。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"根拠を示してほしいと思ったので言いました。絶対に教室型説明会をするべきだと、区民からの要望はすごく強いので、するべきだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"ですので、やはりきっちりと説明をしていくべきだろうと。その不安にも答えるべきだというふうに思いますので、本日結論を出す、採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"のだて副委員長","kind":"質問","question":"本日結論を出すということで、採択を主張します。同じく教室型説明会を実施してほしいというものですから、理由は先ほどの陳情と同様です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"田中委員","kind":"質問・要望","question":"本陳情は、メディア参加もこの教室型説明会で求める陳情でした。ですので、本日結論を出すで、採択を主張したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。羽田新ルートを撤回すべきだと考えますし、国に求めるべきだと考えますので、採択を主張します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"田中委員","kind":"質問・要望","question":"区議会決議を尊重し、新ルートの撤回を国へ求める陳情です。ぜひ皆さんに、本日結論を出すで、採択を主張してほしいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。これは新ルートの実施の延期と説明会開催を求めるものですけれども、理由は先に述べたとおりですので、採択を主張します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問・要望","question":"感染症の影響により、オリンピックが延期され、国際便の発着が大幅に減少している中で、区から国へ中止を求める陳情でした。ぜひ皆さんに、本日結論を出すで、採択を主張してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"田中委員","kind":"質問・要望","question":"羽田新ルートの一時延期と、また、海から海への本来のルートに変更してほしいといったことを国へ求める陳情でした。これこそ皆さん一致で結論を出せるのではないのかと思うので、ぜひ皆さんと、継続ではなく結論を出すで採択を全会一致でできればと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。理由は、さっきの説明会を求める陳情と同様です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"田中委員","kind":"質問・要望","question":"感染症拡大によって増便が見込めない中で、新ルートを実施することについて、国へ教室型説明会を求めるものです。これもぜひ全会一致で採択をしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。これは新ルートの停止を求めるものですので、理由は令和２年請願第３号と同様です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"田中委員","kind":"質問・要望","question":"区議会から国へ新ルートの飛行停止を要望してほしいといった陳情です。これに関してもぜひ全会一致で、結論を出すで、採択をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"国は住民の理解を得て進めると言ったにも関わらず、区民に一度も賛否が問われないまま実施されていることは許されません。国や区にアンケートなどの実施で区民の意見を吸い上げることを求めるもので、採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"田中委員","kind":"提案","question":"２万３,０００を超える区民投票を求める声が、ぜひ区や区議会から地元の声を聞くアンケートなどの機会を提案してほしいといった陳情です。ぜひ本日結論を出すで、採択を主張してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"そして採択ですが、区民投票に関しては、やはりここに書いてあるように、区民の声を吸い上げる方法をとってほしいという意見なわけですよ。採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"品川区議会が全会一致で羽田新ルートに反対したとありますが、全会一致の決議では羽田新ルートは容認できないと、ルートの再考を求める内容です。国が設置したまやかしの検討会が行われている今、国に要望すべきは羽田新ルートの中止、反対だということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"田中委員","kind":"質問・要望","question":"区議会決議や区としての意見を国へ伝えてほしいとのことでした。これまでも国へ意見、要望をしてきているといった、委員の中でもそのような発言がありましたり、区としてもそういった発言がありました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"西本委員","kind":"意見","question":"やはり明確に反対されている方もいるので、ここは誤解を生じるかなというふうに思います。ただ、趣旨は理解できますので、趣旨採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。住民の被害を明らかにするために、住民の要望を踏まえ、よりきめ細かく騒音測定調査を求めるものですので、採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"田中委員","kind":"質問・要望","question":"騒音測定装置の設置の拡充を求めることと、病院近くなど、区民が求める場所に騒音測定装置の設置をしてほしいと求める陳情です。ぜひ皆さんに採択をしていただきたいと求めます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"西本委員","kind":"意見","question":"本日結論で、採択です。この騒音問題というのは、生活の中でどう影響するのかというのは、やはり分析、調査、測定、これは絶対に必要だと思いますので、採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。理由は、令和３年陳情第１０号と同様で、民意を表明する機会を品川区に求めるもので、実施すべきだと考えますので、採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"田中委員","kind":"質問・要望","question":"区民投票条例が否決されたため、区独自の方法で区民が賛否を示せる機会を設けるよう、区議会から区へ求めるものです。ですので、区民の方たちが本当に賛成・反対を言える機会といったものを求めたいというか、ぜひ皆さんにも採択に回ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"西本委員","kind":"意見","question":"住民投票条例が否決されたということでは、非常に残念に思っております。やはり民意というのは、しっかりと聞いて、それを国に届けるというのが私たちの大きな責務だと考えていますので、採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"のだて副委員長","kind":"意見","question":"区民投票については、令和３年陳情第１０号と同様の理由です。住民にどれだけの被害が出ているのか、区としても把握すべきですし、その結果を住民に返していくことも重要だと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"田中委員","kind":"確認","question":"品川区議会会議規則の第１５条を見たときに、ほかの会期になったときには当たらないといったことになるのかなと確認をしたので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"のだて副委員長","kind":"提案","question":"本日結論を出すということで、採択を主張します。理由は、令和３年陳情第１０号と同様で、議員提案も含めて実施すべきだと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出して、採択を主張します。そして区民意見が言える機会を求めるものですので、ぜひ皆さんにも採択を主張してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"若林委員","kind":"質問・要望","question":"ちょっと一言。標題が「ルート撤回を求める」になっていて、陳情の要旨は住民投票の実施ということで、住民投票の実施かなという理解で、不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"田中委員","kind":"質問・要望","question":"こちらも主張が住民投票条例の制定を求める陳情ですので、区民意見を聞いてほしいといった区民の願いが表れているのだと思います。皆さんにぜひ採択を主張してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"西本委員","kind":"質問","question":"来月１回委員会がありますが、来期に対しての申し送りをまとめるべきだと思うのですが、いかがでしょうか。今年度の建設委員会として、次の年度の方々に申し送りをするということをしたほうがいいと思いますが、いかがか尋ねました。","respondent":"塚本委員長","answer":"そのような前例がございませんし、基本的には、そこに各委員の意見が、継続ということについての議事録もしっかり残るので、必要はないと考えます。","id":"exchange-086"},{"speaker":"西本委員","kind":"質問","question":"しかし、それぞれどういう理由で継続にするのかについては明確にされておりません。次年度に引き継ぐ上で、どういう理由で継続ということをしてしまっているのか、それを明確にしていただければというふうに思っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"石田（秀）委員","kind":"意見","question":"私は、委員長の発言のとおりでいいと思います。会派の中に１回も諮らないでこういう結論を出すなどということはあり得ないと考えていますので、委員長が言ったとおりで私はいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"西本委員","kind":"意見","question":"それはいろいろな状況によってやるかもしれませんが、私が言っているのは、建設委員会としてということです。その内容については、こういう結論に達したのでということのまとめはしたほうがいいのではないかと申し上げているわけですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"田中委員","kind":"確認","question":"再度確認なのですけれども、新しいメンバーで建設委員会が立ち上がったときに、これが本当に継続されるのかということが本当に不安です。必ず廃案にならないといったその根拠がどこに記されているのかということをお知らせしてほしいのですけれども。","respondent":"塚本委員長","answer":"先ほどお答えしたとおりですので、もうこれ以上はお答えする必要はないと思います。継続されますので。","id":"exchange-090"},{"speaker":"田中委員","kind":"確認","question":"では、本当に継続されるということで確認をさせていただいていいですね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"}]},{"id":"topic-02","title":"(2)八潮五丁目地区まちづくりワークショップの実施","agenda":"(2)八潮五丁目地区まちづくりワークショップの実施","exchanges":[{"speaker":"田中委員","kind":"質問","question":"今後の予定のところで、まちづくりワークショップの実施というものがあったのですけれども、この対象と、あと、感染症が広がる中で、ワークショップをどのように開催していくのかといったことも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"現在、自治会あるいは管理組合の方に人選いただいて、開催を予定しています。その３回のうちのそれぞれ１回ずつを２回に分けて、２回に分けて行っていくという形で、そうしたところの対策をとりながら開催していきたいです。","id":"exchange-092"},{"speaker":"田中委員","kind":"確認","question":"まちづくりワークショップに参加したいといった方は参加できるのですか。そういったことはないですよねというところを確認したいというのと、そのとおりだと思うのですけれども、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それぞれの自治会あるいは管理組合の中で人選を、１名程度、ご推薦いただきたいというふうに考えてあります。八潮五丁目地区への全戸配布でのアンケートも実施していますし、この地区内全戸に、この素案についての意見募集を図っていきたいです。","id":"exchange-093"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"こういうことも踏まえて、今後どういうふうにしていくというスパンがあるではないですか。やっぱり１つ大きなことだと思うので、これは要望で終わりにしますが、そういうことを考えてやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"その議論がどういうものであって、これからまちづくりという意味では、全く別の視点でのアドバイスみたいなものも必要になってくると思うのです。その辺の調整はいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"検討を始めたのですが、地域に入って現状などを説明したときに、平成２９年度から検討しておりますが。学識経験者も入っていただいた会議体を設けて検討を進めていくということにはなると思うのですが、まずは今の現状をしっかり認識していただいて。","id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"将来に向けて、やっぱり今からでも住民と共有化を図っていただきたいという、そういうまちづくりという形でのガイドラインができるとうれしいなと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"田中委員","kind":"意見","question":"大事なことを忘れておりました。具体的なそういった障害のある方たちへの説明等を、今どのように考えられているのかといったところをお知らせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"アンケートの配布であったりを行って、漏れのないように、その意見をお聞きしていくという形で進めていきたいです。その場に、内容を確認したいというふうな形でもう事前にいただいておりますので、そうした機会を捉えてご意見を伺っていきたいです。","id":"exchange-097"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ障害者や子育て世帯、子どもたちといった当事者の声をきちんと聞いていただきたいと強く要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"区としてどう応えていくのか、こうしたことも含めて検討を行っていくということなのか、伺いたいと思います。それで、八潮のところで以前から鉄道の新線の話とかがあったと思うのですが、その関係性といいますか、どうなっているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"ワークショップの実施についての周知ですが、検討経過については周知するということは、今考えているところです。今現在、これから検討に着手するまちづくりマスタープラン、この改定の中でしっかり検討していきたいというふうに考えてあります。","id":"exchange-099"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"一般の方でも分かるように広報していただきたいということと、様々な意見が出るというふうに思いますので、そうした住民の意見をしっかりと反映させていっていただきたいというふうに要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"大沢委員","kind":"質問","question":"公共の施設整備率が非常に高い土地の特色があるとは思うのですけれども、ここの場所というのは、そこら辺の整備率は高く捉えられているのでしょうか。設備等を整備していくのか、そこらの今後出てくるビジョンですけれども、考え方を説明を求めました。","respondent":"鈴木都市計画課長","answer":"住宅系が７０.６％というところと、公園が２３％というところで、今後検討を進めていく中でしっかり考えていきたいです。","id":"exchange-101"},{"speaker":"田中委員","kind":"確認","question":"そこからちゃんと意見が反映されるのかというところを確認したいというのと、もう１回、具体的に教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"ある意味、そこにこの素案が直接届くように戸別配布をして、具体的に直接ご意見をいただく方法を今考えている。いただいたご意見をすべてということでは当然ないと思いますので、その内容をよく確認させていただいて、反映すべきところは反映していくです。","id":"exchange-102"},{"speaker":"田中委員","kind":"質問・要望","question":"こういったまちづくりにしたいといった声を確認しましたといった感じで、この地区の方たちにされるのかといったところとかを伺いたいです。まちづくりに参加したいと思っている方たちの意見をきちんと広く聞いてほしいなということを思っての要望ですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"３回程度のワークショップの実施後に、その経過についてはご説明させていただいて、意見をいただきながら進めていきたいというふうには考えてあります。","id":"exchange-103"},{"speaker":"田中委員","kind":"質問・要望","question":"それだと、ぜひ区として積極的にこういったワークショップでの議論がありましたといった周知をしていただきたいなと。これ以上負担になり過ぎないように、区としても積極的に周知をしていただきたいと要望いたしますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"その都度、全戸配布というのはなかなか難しいかなと思いますので、例えば、区のホームページで検討状況についてお知らせするとか、そこはいろいろ検討してまいりたいと思います。","id":"exchange-104"}]},{"id":"topic-03","title":"令和３年５月都営住宅入居者募集","agenda":"令和３年５月都営住宅入居者募集","exchanges":[{"speaker":"のだて副委員長","kind":"意見","question":"今回の住宅戸数ですとか、区内の戸数を知りたいのですが、プレス発表がこの後だということで、それに関連して載っていないのかどうかも含めてとの意見を述べました。","respondent":"竹田住宅課長","answer":"先ほど申し上げたとおり、４月２２日に今回の募集戸数が発表されますので、現段階では、私どもは承知していないです。参考までに申し上げますと、昨年の同時期が、５団地２３戸の募集があったです。","id":"exchange-105"}]},{"id":"topic-04","title":"戸越六丁目地区における密集住宅市街地整備促進事業の開始","agenda":"戸越六丁目地区における密集住宅市街地整備促進事業の開始","exchanges":[{"speaker":"田中委員","kind":"確認","question":"このタイトルにある密集住宅市街地整備促進事業のことでいいのかというところの確認と、その２か月間の事業の進捗を報告する会なのか、そこのところについてお知らせください。","respondent":"森木密整備推進課長","answer":"令和３年４月の密集事業の開始というものは、事業の内容を改めてご説明いたしまして、防災まちづくりへの理解を進めていきたいというふうに考えているところです。","id":"exchange-106"},{"speaker":"田中委員","kind":"意見","question":"この報告会の対象者は、どういった方になるのかといったことや、その周知を、感染症の広がりのこともありますし、どういった報告をしていくのかといったことをお知らせほしいと求めました。","respondent":"森木密整備推進課長","answer":"昨年度の勉強会につきましても、また、検討内容報告会につきましても、書面開催という形になっているところもあります。そういった部分で、漏れなく事業の開始、内容について、ご説明をしていきたいというふうに考えております。","id":"exchange-107"},{"speaker":"田中委員","kind":"質問","question":"ですので、１人でも多くの地域住民の方の参加が、意見聴取の場が大事だと思うのです。そういった意見聴取の場の拡充というか、どういった検討をされているのか、伺いたいと思います。","respondent":"森木密整備推進課長","answer":"例えば昨年度行いました検討内容報告会の中では、チラシにＱＲコードをつけまして、そこからアンケートフォームにそのまま飛べるようにしております。そういったことも活用しながら、コロナ禍の中でも意見をいただけるような工夫というのは…","id":"exchange-108"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"それぞれ何人ぐらいの方が参加して、どういう議論や意見が出されたのか、伺います。一遍に１,０００m2を確保すると、立ち退きなども出てしまうと思うのですが、どのようにやっていくのか、伺いたいと思います。","respondent":"森木密整備推進課長","answer":"それから検討内容報告会につきましては、また、地権者の方にも郵送しております。１００m2、前向きに交渉を進めていきたいというふうに考えておりまして、少しでも公園の面積を広げていければというふうに考えているところです。","id":"exchange-109"},{"speaker":"のだて副委員長","kind":"質問","question":"超高層ビルを林立させるのはやめるべきだと、住民合意を図って低層での建替えを進めるべきだというふうに思いますけれども、いかがでしょうか。「共同建替え ３棟等」と書いてありますが、その３棟は既に具体化をされているということなのか、伺います。","respondent":"森木密整備推進課長","answer":"２００m2といったところから少しずつ広げていきたい、合計１,０００m2ほどを取れればというふうに考えているところです。防災まちづくりについて検討している既存の組織がありますので、地域の方々と協力してつくっていきたいというふうに考えております。","id":"exchange-110"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"３町会の７名の方しかいないということになるので、広く意見を聞いて取り入れていけるようにしていっていただきたいというふうに思います。そうした形で低層での建替えをしていくということでやっていっていただきたいということで要望いたします。","respondent":"森木密整備推進課長","answer":"先ほど、３町会７名の方というふうにお話をさせていただきました。地域の方々についても、今後、区のほうもしっかりとサポートしながらやっていきたいと考えております。","id":"exchange-111"},{"speaker":"西本委員","kind":"確認","question":"全体的な確認なのですけれども、この補助２９号線もあって、どのぐらいのスパンを考えてこの図を描かれているのかなというふうに思うのです。さっきもあったのですけれども、これは当てがあるのか、全く当てがなく、ここにこういうものがあったらいいなということなのか、説明を求めました。","respondent":"森木密整備推進課長","answer":"なかなかこのとおりずっと進めるかどうかということはありますけれども、皆様と進めていきたいというふうに考えています。そういった中で建替えを考えていらっしゃるところについて、それなりに道路づけがよくて、１つひとつ増やしていければというふうに考えています。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"そういう手法の１つだと思うのですけれども、「えっ、どういうこと？先ほど３町会７人というふうになっておりましたけれども、もうちょっと丁寧にできないのだろうかと思うのですが、いかがか尋ねました。","respondent":"森木密整備推進課長","answer":"検討内容報告会という形で１回、４回程度は、ご意見をいただいているです。そういった部分で、いろいろな方々のご意見を聞いて今回の案ができているというふうにご理解いただければと思います。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほど、いろいろご意見を聞いているということだったのですが、どういうご意見があるのでしょうか。それはいかがか尋ねました。","respondent":"森木密整備推進課長","answer":"あるいは、その中につきましては大分狭い道路が多いですので、そういった細街路の拡幅が必要だろうというようなご意見をいただいたところです。区といたしましては、一定程度、地域の方々の意見を拾えているのではないかなというふうには考えているところです。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問・要望","question":"これは要望です。そのまとめ方、方法についても、それぞれの地権者の方々には十分配慮した形で進めていただくようにお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"田中委員","kind":"質問・要望","question":"この地区内に大原小学校だったりとか、あと子どもの施設だったりとか、福祉施設等があると思います。そういった周知の方法や、あと、意見聴取をどのように考えているのかだけお知らせほしいと求めました。","respondent":"森木密整備推進課長","answer":"それから土地をお持ちの方が直接的に関係してくるところですので、そういった方々の意見をいただきながらつくり上げているです。区のほうでホームページであったりとか、そういったことを活用しながら、できるだけ意見を集約していきたいというふうに考えています。","id":"exchange-116"}]},{"id":"topic-05","title":"東急大井町線（戸越公園駅付近）連続立体交差事業の着工準備採択","agenda":"東急大井町線（戸越公園駅付近）連続立体交差事業の着工準備採択","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"何かその調査、あと、連続立体交差事業についての要望というのはとても理解します。そこのところについてお知らせほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"事業を行っていくに見合う内容か、そういったＢ／Ｃであったりとか、事業効果も含めて検討してきたというふうに聞いてあります。都内全体で連続立体交差事業をやるところは、駅前広場も一緒に整備をしていっているというところがあります。","id":"exchange-117"},{"speaker":"のだて副委員長","kind":"質問","question":"採択された理由というのですか、そのところを伺いたいのと、どういった位置づけになっているのかということを伺いたい。何年後なのか、その見通しというのですか、どの程度なのかというところを伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"２番目の採択されると今後どのように進んでいくのかですが、範囲であったりとか、より具体的に整備を見据えて検討調査をしていくです。３番目のスケジュールの具体的なスパン等ですけれども、４月１日に採択されて…","id":"exchange-118"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"区とＪＲの説明会があったと思うのですけれども、その報告が今回あるのかなと思ったらなかったのですが、土地区画整理事業の説明だったと思います。今回報告がなかった理由と、次回には報告がされるのかといったところの確認をさせていただきたいのですが、委員長、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問・要望","question":"関連して要望なのですが、説明会の資料にスライドの資料が全く入っておりませんでした。住民からもスライドの資料が欲しいということでしたので、次回は必ず資料をすべて委員会のほうに提出していただきますようお願いします。","respondent":"末元都市整備推進担当部長","answer":"今回は任意の説明会ということで、ＪＲと区の共同の資料ということだったのですが、今回はＪＲのほうで公開したくないということでございましたので、今回は公開しておりませんが、次回は法令に則ったものですので、その辺はしっかり対応したいと思います。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問・要望","question":"一緒に前に座っているではないですか。それは公表すべきだと思いますので、次回はきっちりと提示するように、区のほうからもしっかりと要望を言ってください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-121"}]},{"id":"topic-07","title":"補助１６３号線（東急大井町線ガード下区間）電線共同溝等整備工事","agenda":"補助１６３号線（東急大井町線ガード下区間）電線共同溝等整備工事","exchanges":[{"speaker":"田中委員","kind":"確認","question":"障害のある方や、乳幼児を連れた方たちの通行の安全性の確保、そこのところだけ確認させてほしいのですけれども、いかがか尋ねました。","respondent":"溝口道路課長","answer":"本整備という形ではありませんで、そういったものはしっかり行いながら、そういったものの整備は行っていきたいと思っています。やっぱりどうしてもご迷惑をおかけすることがありますので、その辺については、周知しながら進めていきたいというふうに考えているところです。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"横断歩道なのですけども、これ、広がると、（信号の）時間も調整していただけるのですか。撮影方向2)の右側のほうですか、今後、安全性を確保していただけるものなのか尋ねました。","respondent":"溝口道路課長","answer":"補助２６号線が開通しますので、そういったご要望も様々いただいておりますので、そういったものも警察に伝えてきているところです。警察を含めて、しっかり協議をして、少しでも皆さんに利用しやすいような形にとれればというふうに考えているところです。","id":"exchange-123"}]},{"id":"topic-08","title":"しながわ区民公園北側ゾーンの改修","agenda":"しながわ区民公園北側ゾーンの改修","exchanges":[{"speaker":"西本委員","kind":"質問","question":"少年野球場と少年サッカー場、サッカー場は新設ですけれども、夜間の使用はできない、夜間照明は駄目だったのか尋ねました。","respondent":"高梨公園課長","answer":"全体としては、可否について、まず第１回のほうでは反対という意見が多うございました。利用者と周辺にお住まいの方々からの回答では、夜間用照明を引き続き設置しないということで、計画を立案しています。","id":"exchange-124"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"結構改修するということで、できる限り樹木を残してほしいということで、そういった声も反映していただきたいというふうに思います。ぜひ利用者の声も含めてですが、住民の方の意見も反映させてほしいと求めましたが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"適宜、状況を見ての声かけということで、ソフト面の対策と併せて実施をしていきたいと考えています。天然芝の野球場ということで計画しておりますけれども、併せて砂ぼこり対策も行っていく、このような考えです。","id":"exchange-125"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"利用者の声もぜひ大切にしてほしいと求めましたし、近隣住民の方の意見も大切だと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-126"},{"speaker":"田中委員","kind":"質問・要望","question":"説明会の実施について、オンライン等での説明会の開催とか、そういったことは検討されていないのか。会場に行きにくい方とかもいると思いますので、ぜひそういったことも検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"説明会に代わる周知の仕方といったところで、確かに手法の１つで検討する余地はあるのかなというふうには思っていますが、もし説明会の開催が難しいというような状況になった際には検討してまいりたいと考えています。","id":"exchange-127"}]},{"id":"topic-09","title":"令和３年度品川区・区内三消防署合同水防訓練","agenda":"令和３年度品川区・区内三消防署合同水防訓練","exchanges":[{"speaker":"西本委員","kind":"質問","question":"２番の自主避難施設開設訓練というのは、具体的に例を挙げて、どういう訓練なのか、説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"訓練の実施内容のお尋ねについてお答えします。昨年度作成いたしました避難所運営マニュアルに基づき訓練を実施していきます。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問","question":"これは職員だけということでよろしいのですか。自主避難なので、避難所運営会議もあるので、そことは全く関係なく、あくまでも職員だけということでよろしいのか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"区の職員のみで実施するのかというご質問ですが、そのとおりです。なお、周辺町会の方にもご視察いただこうと考えております。","id":"exchange-129"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212900?Template=document&Id=4318#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":85056,"voices":441}},{"id":"r03-20210419-9","meetingId":"r03-cm04","date":"2021年4月19日","dateIso":"2021-04-19","committee":"文教委員会","time":"午後 １時００分～午後 ３時２５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"品川区立学校施設長寿命化計画の策定","agenda":"品川区立学校施設長寿命化計画の策定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"８ページですが、改修から２０年経過すれば、改善指摘事項がなかったとしても自動的にＣになるという捉え方でいいのでしょうか。３点目は、１６ページの洋式化率なのですけれども、そこら辺をお伺いしたいです。","respondent":"有馬庶務課長","answer":"１２条点検の指摘事項か改修年度か低いほうをとるということですので、１２条点検で指摘があって直したとしても、クリアにもなります。それから、最後の誤記については、申し訳ありません、「バランス」ですので、訂正します。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"たしか鈴ケ森小学校が、評価結果でも全てＣで、それで、改修に向けた準備の話があったと思うのですけれども、コロナの関係なのでしょうかね、少しそれが後退したような感じに受け止めているのですが、現状と見通しを教えてほしいと求めました。","respondent":"有馬庶務課長","answer":"たしか令和２年度の予算のときに、これをある程度、敷地測量や計画検討ということで載せました。内部のほうでボリューム検討と言いますか、将来的に何クラスがいいのだろうかとか、内部検討は引き続き行っている状況です。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問","question":"ピークが令和１８年となっているのですけれども、現時点で、現在どういう考え方になっているのかを教えていただけたらと思います。これからまた３５人学級ですとか、教室の利用の仕方が変わってくるのかなと思うのですけれども、そういった影響等は何かありますか。","respondent":"有馬庶務課長","answer":"将来的にこの部分は地域開放エリアとして開放できる多目的ホールになりますとか、そういったところも併せて提案いただいて対応しております。人口増と併せて教室もたくさん要るだろうということですので、いずれにしても今すぐ転用だとかいうことは考えられずに…","id":"exchange-003"},{"speaker":"横山委員","kind":"意見","question":"人口推計ですとか、あと教室の学級の人数、いろいろな動きもあるかと思いますので、適宜見直していただくと書いてありますけれども、そのときそのときに合わせて見直ししながら進めていただけたらと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"人口が減ったからといって安易にどこかに転用というふうに考えないでいただきたいと思っていまして、あと、すまいるスクールの問題もありますよね。そういうふうな考え方をぜひ持っていただきたいと思うので、ぜひそういうふうな考えも持ってほしいと求めましたが、いかがか尋ねました。","respondent":"有馬庶務課長","answer":"最初からそれありきで全てを進めているわけではありません。ただ、将来的にはそういったところも考えていくということです。","id":"exchange-005"}]},{"id":"topic-02","title":"令和３年度学級編制","agenda":"令和３年度学級編制","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"何でこうなっているのか、特別な事情がある場合は実情に応じてという話もありましたけれども、では、どういう事情があるのかをお伺いしたいです。以上、お伺いしたいと思います。","respondent":"勝亦学務課長","answer":"そういった意味で、できるだけ学年が同じところにまとまってという考え方で３学級にしたいという話がありましたので、３学級にしています。先ほども出ました、３５人学級の中で東京都の加配がありますので…","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"来年も４学級になるのではないですかということで、国が３５人学級をやるって法律で変えたにも関わらず、やはりどうなのかなと。これは、法にのっとって３５人にしていただきたいのですが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"保護者アンケート等は行っておりますけれども、学級編制については区の責任において実施するということで実施しております。それから、学校選択等の動向を見まして、令和７年度の全学年３５人学級化を実現してまいりたいと考えております。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"特別な事情ではない、安易というか、やるべきことをやっていないのではないかと思うのです。そこら辺はどうなのですか、特別な事情と言えるのですか、私は言えないと思いますけれども、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"子どもの教育環境が大きく変わるというお話です。見ていただいたとおり３学級・６学年で１８学級、これが１つの教室棟のほうに収まっているということで、学校と相談しながら決めていくものです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは強く要望します。質問ですが、学級をもっと増やしてほしいという声は全く上がっていないのですか、そこだけ確認させてください。","respondent":"勝亦学務課長","answer":"学級編制の過程において、そのようなお声をいただいたとは伺っておりません。","id":"exchange-009"},{"speaker":"あべ委員","kind":"確認","question":"制度的なところを確認したいと思うのですけれども、区としてはどこまでの権限を持っていて、どこと相談してそれが実現できるものなのか。その範囲はどういうものなのかを説明を求めました。","respondent":"勝亦学務課長、有馬庶務課長","answer":"学級編制に関しましては、編制を行った後、東京都教育委員会のほうに報告しております。弾力的運用に関して具体的な基準等については、３５人学級に関しまして、国や東京都のほうから具体的な指針等は今のところ示されていません。 ４０名まではいけるという形になっていて、４０名を超えることはできない、そういう形になっている表です。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"こうしたやり方も区の権限ですよね。要は配置された教員数に応じてどのように組むかは、４０人という上限を超えなければ区の裁量に任されていると考えていいのか尋ねました。","respondent":"勝亦学務課長","answer":"はい、４０名を超えなければ、例えば、城南小学校、三木小学校のように、少なめに設定しても問題ありません。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"城南小学校と三木小学校については、学校側から特段の要望があったということで、逆に言えばほかのところからは特にそういうことがなかったと。これについては、学校全体の加配の先生を充ててクラスを分割していると解釈していいのか尋ねました。","respondent":"勝亦学務課長、工藤指導課長","answer":"おっしゃるとおりです。学級の細分について、城南小学校、三木小学校からお声が上がったもので、加配の教員を充てるという形で対応しております。 学務課長から説明のあったとおりなのですが、３５人以下の学級の実施、または小学校２年生における少人数指導およびチームティーチングの実施。活用の方法については、そのいずれかのところから選択できるようになっています。","id":"exchange-012"},{"speaker":"あべ委員","kind":"確認","question":"今これは各学年にプラス１ぐらい加配があるのでしたか、この２校というのは、そこを確認させてください。１８の教室棟のところにおさめるということになると、毎年はみ出すというか、その見通しを持っていらっしゃるかどうかを説明を求めました。","respondent":"勝亦学務課長、工藤指導課長、有馬庶務課長","answer":"やがて４０人を超えるようなことがあれば、専科棟、別の部屋を転用していく等も決断していかなければいけないかなと考えております。 ２年生の加配で配置した教員であれば、その当該学年で活用するようにという指導がありますので、私どももそのように学校に指導したところです。 １点補足しますと、３クラスずつ固まっているほうがいろいろとやりやすい、今は３クラスで行っているという状況もあります。ただし…","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"毎年のように学級数が変わっていくなんていうことがあったわけで、ほかの、なかなか言いにくいということなのですかね。現校長先生とのお話し合いでそうなっているのか、それとも、何か学校としての特質があるのか。","respondent":"有馬庶務課長","answer":"それ以外の何かの意味は特にありません。物理的な部分が厳しいということです。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"４年生の学級では７人という、この状況をどう考えているのか、何か取組みはお考えなのか尋ねました。","respondent":"勝亦学務課長","answer":"中延小学校について、今年度は全体の中で一番少ない２１人の入学ということで、合計１０７人となっております。各学校の特色ある学校作りという部分もありまして、そういった中で学校のよさをより発信していくような工夫が必要かと考えております。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"道路を挟んであるという関係なのですけれども、第二延山小学校と中延小学校の物理的人数調整とか、そういったことはできないのか尋ねました。","respondent":"勝亦学務課長","answer":"通学区域の方は必ず通学区域のところに入れる、その上で希望する学校を選択できるという選択肢を確保していくのが、制度の目的と考えております。学校の数字の増減でそこの配分等々をする考えは、今のところはございません。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"ただ、中延小学校は大変なのではないかと思っていますので、いろいろと創意工夫のもとしっかりとご検討していってほしいと求めました。","respondent":"勝亦学務課長","answer":"ご指摘いただいた部分を含めまして、学校と一緒に考えてまいりたいと思います。","id":"exchange-017"}]},{"id":"topic-03","title":"令和３年度品川区立幼稚園、小・中学校、義務教育学校、園長・校長・副校長異動者名簿","agenda":"令和３年度品川区立幼稚園、小・中学校、義務教育学校、園長・校長・副校長異動者名簿","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"小学校で、中学校から校長になられた方と、あと、中学校で小学校から校長になられた方がいらっしゃるのですけれども、それは、意図というか意味が、あるいは、学校の要望なのか、そこら辺を何かあれば説明を求めました。","respondent":"工藤指導課長","answer":"もともと山本校長は小学校籍の方でしたけれども、配置が令和２年度までは中学校でした。今回、令和３年度においては、それぞれの方の校種に応じた配置となっております。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"推移というか、増えてきているのか、落ち着いてきているのか、減っているのか。長い方でどのくらいなさっているのかを説明を求めました。","respondent":"工藤指導課長","answer":"小学校は昨年度は１１名に対して今年度は１０名ですし、中学校は昨年度１名だったところが今年度３名ですので、同じぐらいの幅で推移しております。再任用の最終が６５歳ですので、最長で５年ですけれども、今年度、本区でも５年目の方もおります。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"背景としては、管理職不足ですとか、その世代の不足があるのか、それとも一方で６５歳定年に対応した制度的なものがあるのか、説明を求めました。","respondent":"工藤指導課長","answer":"委員ご指摘ありましたけれども、主には管理職のなり手不足が言われております。校長も、必要数に対してはまだまだ掘り起こしが必要とご指導いただいていますので、管理職不足が主な要因になっていると私どもでも認識しております。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問・要望","question":"６５歳までとなると、不足しているから６５歳までというのは、なかなか寂しいものがあると感じております。そこについては、教育委員会はどのような考え方、あるいは努力をされているのかを説明を求めました。","respondent":"工藤指導課長","answer":"特に一貫教育等を進めている中で言えば、非常に必要であると考えておりますので、一貫教育を進めていきたいと考えております。","id":"exchange-021"}]},{"id":"topic-04","title":"低所得の子育て世帯に対する子育て世帯生活支援特別給付金（ひとり親世帯分）","agenda":"低所得の子育て世帯に対する子育て世帯生活支援特別給付金（ひとり親世帯分）","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"そうすると、この家計急変者の案内を送る方というのは、区のほうでどういった方を把握していらっしゃるのか。それで、内訳で５００名を見込んでいますけれども、そのうち発送できる、数が分かっているのはどれぐらいなのか尋ねました。","respondent":"伊東子育て応援課長","answer":"一応申請が必要となっていますので、こちらのほうから申請書とともにご案内を送付して申請していただいての支給という形になります。人数に換算しますと４５７名の方が申請されていますので、その方々に関しては、こちらのほうから申請書を送付するという方法です。","id":"exchange-022"},{"speaker":"たけうち委員","kind":"質問","question":"新たに、この１年近くの中で急変してしまった方については、昨年申請していないから案内が行かないわけですね。周知は、案内が行かない方に対して意識した周知をしていかないと漏れてしまう危険性がありますが、そこはどう考えるか尋ねました。","respondent":"伊東子育て応援課長","answer":"今回も昨年２月から急変された方が対象になっていますので、前回もらっている方に関しては、ほぼそのまま対象になると考えております。順次、１回だけではなくて、周知を図っていこうと考えております。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これはできるかどうか分かりませんが、ぜひ、よろしくお願いいたします。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"さまざまなところに、物理的に目で見える広報をお願いしたいと思いますけれども、いかがでしょうかというのが１つです。３点目は確認なのですが、今若干回復していても、一旦急変して落ち込んだときがあった方であれば受給できるということでよろしいのか尋ねました。","respondent":"伊東子育て応援課長","answer":"１点目の施設へのチラシ配付等々ですけれども、先ほどのほかの周知方法等を含めまして、やる方向での検討をさせていただきたいと思います。家計急変者の対応ですけれども、資料のほうには６月１日以降と記載していますが…","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ、そういったところでご案内がきちんとできる体制をとってほしいと求めましたが、いかがでしょうか。支給を１回にしなければいけないのでなければ、早く受け取っていただくことができないのかと思うのですが、いかがか尋ねました。","respondent":"伊東子育て応援課長","answer":"チラシを作ることまではまだ考えていませんけれども、内部的にはそういう形でやっていく予定です。７月１５日の１回だけではなくて、随時申請があって、なるべくスタートのところは早くやっていきたいと考えています。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問","question":"それから、できるだけ急いでということで、ありがたい姿勢だと思います。一応、申請の最終がいつごろ、昨年もということでしたけれども、年度いっぱいは申請ができるのかどうか、そのお尻のところを説明を求めました。","respondent":"伊東子育て応援課長","answer":"今回の支給に関しては、申請が令和４年２月末までということで、支給が年度内３月末までの支給という期限は決まっています。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、最後に、専決処分という形で今後進んでいくのかなと考えていますが、その判断の背景、理由と、今後の手続きについて説明を求めました。","respondent":"伊東子育て応援課長","answer":"今回の予算ですけれども、補正予算ということです。今年度の４月になってから通知が来て、それで５月に支給を目指せという話になった中で、そのような考えをしております。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"後半の質問ですが、今後どのような手続きをされていくのか尋ねました。","respondent":"伊東子育て応援課長","answer":"我々のほうから財政課のほうに補正予算の要求を上げたところです。それで、実際は財政課のほうで予算の手続きをします。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"すみません、最後に、コールセンターの番号がもう決まっていたら教えてください。契約がまさに今日ですけれども、終わっているのか尋ねました。","respondent":"伊東子育て応援課長","answer":"内部的に番号をとりましたので、事業者が云々というよりは、内部の経理課との中でやっています。すみません、今、番号までは分かりませんが、明日、ホームページ等々で公表します。","id":"exchange-030"},{"speaker":"筒井委員","kind":"確認","question":"先ほど来からご質問が出ているとおり、３００人とか６００人とか、そうした確保ができているのでしょうか。それは当然、１０分の１０の国庫負担でよろしいのでしょうかという確認をさせてください。","respondent":"伊東子育て応援課長","answer":"確かに実績から見ると、ちょっとした伸びということで算定していますけれども、長引いているということでは伸びる可能性は十分あると思います。少なければ返還という形にもなるので、その辺は国のほうとして、実績をしっかりと交付するという話は伺っております。","id":"exchange-031"},{"speaker":"芹澤副委員長","kind":"確認","question":"聞き漏らしていたら申し訳ないのですけれども確認で、前回、何名くらいの方が対象者になり得るという見込みだったのでしょうか。その見込みの中で申請されなかった方がどれぐらいいらっしゃって、申請しなかった原因は把握されていますか。","respondent":"伊東子育て応援課長","answer":"今回に関しては、たまたま昨年の実績があるということで、それに近い数字ということで見積もっているということです。と言っても、今年度これからの部分で影響が出てくる方もいらっしゃると思いますので、その分は増えていくだろうと思います。","id":"exchange-032"}]},{"id":"topic-05","title":"子ども・子育て会議","agenda":"子ども・子育て会議","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"両者の関係というか役割分担について、区としてはどのように位置づけているのか、改めてお聞かせいただきたいのが１つです。あえて「教育」というのが入っているのはどういう意味か、何かあるのか、お願いします。","respondent":"初貝保育教育運営担当課長","answer":"子ども・子育て支援法に基づきまして、区における子ども・子育て支援施策を、区の附属機関として設置しているところです。施設を設置することをメインに行っていたところですけれども、中身の教育などに関しましても、私のほうで所管していく形になっております。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"さまざま挙げられていますが、１つに、これはどういう意味なのか伺いたいなと。私は、いわゆる隠れ待機児童の実態も含めて把握する必要があるのではないかと、この文章を見てさらに思ったのですけれども、その意味を伺いたいです。","respondent":"初貝保育教育運営担当課長","answer":"潜在的な需要の調査に関しては、区の品川区子ども・子育て支援事業計画で、毎年実績や調査をしております。そういった中で、その数値の変化などで潜在的な需要が見えてくるのかなというのが、大まかなところかなと考えています。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"分かりづらい質問で申し訳ないです。子ども・子育て会議の審議内容として５つぐらい挙がっているのですけれども、これは実際にどういうふうに意向を把握しているのかを伺いたいです。","respondent":"初貝保育教育運営担当課長","answer":"潜在的なものを含めての意向調査ということで言いますと、子ども・子育て支援事業計画を作る上で、利用者や区民の方にアンケートをとっておりまして、その中で集計をとりまして、どういった意向があるのかを把握しています。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"定員を決めるときに意見を伺うという話もありましたけれども、そういうところにあるわけですから、隠れ待機児童の問題は重要な要素だと思うのです。文教委員会や議会にもしっかりと報告してもらうべきことだと思うのですが、そういう家庭の状況の意向調査を伺うとか、いかがか尋ねました。","respondent":"若生保育支援課長","answer":"隠れ待機児童については、区としては承知しておらず、把握しておりません。適切に相談につなげているということで対応しておりますので、今後もそちらのほうはやってまいりたいと考えております。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういったことをしっかりと報告した上で議論していただくよう求めたいと思いますし、再三要望していますが、使いたくないでしょうからね。不承諾を受けた方の、実際のもう少し詳しい内訳ということで、しっかりと報告していただくよう、改めて強く要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"昨年度の２回の子ども・子育て会議は、いずれも書面会議だったということなのですが、具体的にどういうやり方をしたのでしょうか。内容を各委員の方にお送りして、何か返答が返ってきたら、それをお答えする、それとも、ホームページに載っているのが質疑の全てなのか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"２月から３月に関しまして、各委員の方に資料とともに質問の回答用紙と、その返答をいただいております。それを我々のほうでまとめまして、回答という形で取りまとめております。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問","question":"会議録も読みましたけれども、これは１往復なのですかね。そういうことを聞きたかったのではなくてとか、もうちょっと詳しいことを教えてくださいとか、そういうやりとりはあったのか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"我々のほうでご質問いただいたところを回答しまして、そちらを回答して、委員長・副委員長にも確認いたしました。何分コロナの影響による、制約された中で、本来の形はできなかったのですけれども、今回そういった形で開催しております。","id":"exchange-039"},{"speaker":"あべ委員","kind":"質問・要望","question":"これでは不十分ではないかと、品川区の子ども・子育ての最も核となるところですから、これはもう少し工夫をしていただきたいと。オンラインを使ってということも始まっているみたいですけれども、そうしたことを考えて準備されているのか、お伺いしたいです。","respondent":"柏原子ども未来部長","answer":"今、委員ご指摘あったように、双方向の議論、やりとりが、書面会議では難しい面があると思っているところです。対面が難しい時期については、オンラインの開催など、やり方について検討をしているところです。","id":"exchange-040"},{"speaker":"せお委員","kind":"質問・要望","question":"書面会議はウェブにしていただきたいと、子ども・子育て会議も２回書面会議で、そういったことがあるのか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"昨年の会議の中でも、ウェブ会議ができないのかを検討いたしました。今、お話にもありましたが、次回の開催に向けてどういった形がとれるのかの検討に努めてまいりたいと考えています。","id":"exchange-041"},{"speaker":"横山委員","kind":"確認","question":"１点お伺いいたします。その中での確認なのですが、小学生以上の利用が難しいということで、現在の検討状況を教えていただけたらと思います。","respondent":"廣田子ども育成課長","answer":"学校のほうから、そこでももう少し配慮ができないかということがあったので、泣く泣く児童センターも小学生の利用を閉めるという形にしています。閉めるときには閉めるということで、大変かわいそうなのですけれども、今いろいろな可能性をあたっている状況です。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"密にならないような人数制限なり、何か手段を生み出していただいて、検討して進めていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"}]},{"id":"topic-06","title":"第三庁舎内オアシスルームの運用変更","agenda":"第三庁舎内オアシスルームの運用変更","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"第三庁舎のオアシスルームは結構人気があって、予約がとりにくい状況かと思うのですが、行政サービス利用者枠というのはどんな感じなのでしょうか。結構いっぱいなのか、こちらは大体希望者はすぐとれるのか、その辺を説明を求めました。","respondent":"若生保育支援課長","answer":"月に多いときで３日に１回程度１人利用するかどうか、少ない月ですと０人という状況もありますので、全体の中からしたら現状そこまで多くないと認識しております。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"その中で新設される登録のない児童については１名ということなのですが、２人目をとることはするのですか、しないのですか。やはりこれはもう１名で枠はあるけれども、今は使っているから２時間待ってくださいみたいな話になるのか尋ねました。","respondent":"若生保育支援課長","answer":"これは現状１名としておりまして、ただ、空いている場合については、その状況によるのですけれども、オアシスルームの委託先の受入体制が整っている状況であれば、そういった枠も柔軟に活用して受入れをしていきたいと考えております。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問","question":"この行政サービス利用枠の利用がかなり少ない状態というのは、この枠があることがもう少し知られていない部分もまだあるのではないかと思います。登録なくても使えますよという順番で、もう一回周知し直していただければと思うのですが、その辺はどのようにお考えか尋ねました。","respondent":"若生保育支援課長","answer":"ご意見をいただいたような内容で、恐らくこれまでもこの利用人数からすると、やはり周知が足りなかったことは担当としても認識していました。今回の１名の枠の拡大を機に、そういったポスターを貼るような形で対応していますので、今後も検討してまいります。","id":"exchange-046"},{"speaker":"横山委員","kind":"確認","question":"すみません、１点確認です。確認で、健康確認や、そういったところはどのように行っていくのかだけ説明を求めました。","respondent":"若生保育支援課長","answer":"今回のこの１名の、２時間以内ということで、そういった簡易な手続きでお預かりできるような形でやっております。","id":"exchange-047"},{"speaker":"せお委員","kind":"質問","question":"事前登録のない児童が１名利用できるということなのですけれども、これが新設された経緯をまず説明を求めました。","respondent":"若生保育支援課長","answer":"そういった声、ご要望等を多くいただいていて、現場からの声を担当のほうで把握しました。何らかの対応ができないかということで、また今後それは検討していきたいと思っていますが、そういう経緯で始めたものです。","id":"exchange-048"},{"speaker":"せお委員","kind":"質問・要望","question":"そうなると、私は以前から要望しているのですけれども、今は施設ごとに登録しなければいけない。１回の登録で全部のオアシスルームが使えるような方向への検討はされているのかを説明を求めました。","respondent":"若生保育支援課長","answer":"事業者ごとで保育者の対応、確認の項目なども違ってきますが、今後そういったところを共有できるように担当としては検討しているところです。切替えのタイミングに、仕様をどう見直せるか、これは鋭意検討していきたいと思います。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5028#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":36851,"voices":158}}]);
